(window.PARENT_DIGEST = window.PARENT_DIGEST || {})[12] = {"grade":12,"subjects":[{"id":"toan","name":"Toán","b":[{"t":"Toán 12, tập 1","c":[{"t":"Chương I. Ứng dụng đạo hàm để khảo sát và vẽ đồ thị hàm số","l":[{"t":"Bài 1. Tính đơn điệu và cực trị của hàm số","m":[{"t":"Tìm khoảng đơn điệu và cực trị của hàm số","w":"Đề cho hàm số (thường là đa thức bậc ba hoặc phân thức) và hỏi khoảng đồng biến, nghịch biến, điểm cực trị, giá trị cực trị, hoặc tham số m để hàm đơn điệu.","s":["Tìm tập xác định và tính đạo hàm y′.","Giải y′ = 0 (và tìm điểm y′ không xác định); lập bảng xét dấu y′.","Kết luận: y′ > 0 thì đồng biến, y′ < 0 thì nghịch biến; y′ đổi dấu từ + sang − tại x₀ là cực đại, từ − sang + là cực tiểu.","Tính giá trị cực trị y(x₀). Bài tham số: y′ ≥ 0 (hoặc ≤ 0) với mọi x thì dùng Δ′ ≤ 0 và hệ số a tương ứng."],"n":["Cực trị phải có y′ đổi dấu, chỉ y′ = 0 chưa đủ.","Phân biệt điểm cực trị x₀ với giá trị cực trị y(x₀).","Hàm bậc ba y′ là tam thức bậc hai: y′ ≥ 0 với mọi x khi a > 0 và Δ′ ≤ 0."]}],"sum":["Đơn điệu: f′ > 0 thì đồng biến, f′ < 0 thì nghịch biến. Cực trị: f′ đổi dấu qua x₀ (+ sang −: cực đại; − sang +: cực tiểu). Chỉ f′(x₀) = 0 thì chưa đủ để có cực trị.","Đồng biến, nghịch biến: Cho hàm số y = f(x) có đạo hàm trên khoảng (a; b).","Xét chiều biến thiên: Tính f′(x).","Điểm cực đại, điểm cực tiểu: Điểm cực đại và điểm cực tiểu gọi chung là điểm cực trị.","Điểm cực trị và giá trị cực trị","Dễ nhầm: f′(x₀) = 0 là có cực trị"],"d":["Tìm khoảng đơn điệu và cực trị của hàm số"],"e":["Sai: f′(x₀) = 0 thì x₀ là điểm cực trị. → Đúng: Phải có f′(x) đổi dấu khi x qua x₀. (Ví dụ y = x³: y′(0) = 0 nhưng y′ = 3x² ≥ 0 không đổi dấu, nên x = 0 không là điểm cực trị.)","Hay nhầm: Đây là điều kiện nghịch biến, không phải đồng biến.","Hay nhầm: Đạo hàm bằng 0 trên cả khoảng nghĩa là hàm số không đổi, không phải đồng biến.","Hay nhầm: Dấu của f(x) không quyết định chiều biến thiên; chiều biến thiên do dấu của f'(x) quyết định.","Hay nhầm: Đạo hàm đổi dấu tại x = ±1 nên hàm số không đồng biến trên toàn ℝ.","Hay nhầm: Đạo hàm đổi dấu nên hàm số không nghịch biến trên toàn ℝ."],"q":{"n":23,"lv":{"Biết":4,"Hiểu":12,"Vận dụng":6,"Nâng cao":1}}},{"t":"Bài 2. Giá trị lớn nhất và giá trị nhỏ nhất của hàm số","m":[{"t":"Tìm giá trị lớn nhất, nhỏ nhất trên một đoạn","w":"Đề cho hàm số liên tục trên đoạn [a; b] và hỏi max, min; hoặc bài toán thực tế quy về tìm max, min.","s":["Tính y′ và giải y′ = 0, chỉ giữ các nghiệm thuộc [a; b].","Tính giá trị hàm tại các nghiệm giữ lại và tại hai đầu mút a, b.","So sánh các giá trị: số lớn nhất là max, số nhỏ nhất là min.","Bài thực tế: đặt ẩn, lập hàm một biến, tìm điều kiện của ẩn rồi áp dụng các bước trên."],"n":["Phải tính giá trị tại hai đầu mút, không chỉ tại điểm cực trị.","Loại nghiệm y′ = 0 không thuộc đoạn đang xét.","Có thể dùng bảng biến thiên cho khoảng; với đoạn thì so sánh giá trị."]}],"sum":["Trên đoạn [a; b], hàm liên tục luôn có GTLN và GTNN: so sánh f(a), f(b) với giá trị tại các điểm cực trị thuộc (a; b). Trên khoảng hoặc nửa khoảng thì có thể không tồn tại.","Giá trị lớn nhất: Cho hàm số y = f(x) xác định trên tập D.","Giá trị nhỏ nhất: Nếu đề không nói “trên tập D” thì hiểu là trên toàn bộ tập xác định.","Cách tìm GTLN, GTNN: Trên tập D bất kì: lập bảng biến thiên trên D rồi kết luận.","Khi nào có, khi nào không","Dễ nhầm: chỉ so sánh hai đầu mút"],"d":["Tìm giá trị lớn nhất, nhỏ nhất trên một đoạn"],"e":["Sai: Trên [a; b] chỉ cần so sánh f(a) và f(b). → Đúng: Phải so sánh thêm giá trị tại các điểm cực trị nằm trong (a; b). (Ví dụ y = x² − 4x trên [0; 5]: f(0) = 0, f(5) = 5 nhưng f(2) = −4 nhỏ hơn, nên GTNN là −4, GTLN là 5.)","Hay nhầm: Đây là định nghĩa của giá trị nhỏ nhất, không phải giá trị lớn nhất.","Hay nhầm: Hàm số không cần có cùng giá trị M tại mọi x; điều kiện là f(x) không vượt quá M và M được đạt tại một điểm.","Hay nhầm: Chỉ có f(x₀) ≤ M thì chưa đủ; M phải là giá trị lớn nhất và được đạt đúng bằng f(x₀).","Hay nhầm: 0 là f(0), giá trị tại đầu mút, không phải giá trị nhỏ nhất vì f(1) = −1 nhỏ hơn.","Hay nhầm: 3 là giá trị lớn nhất f(3), không phải giá trị nhỏ nhất."],"q":{"n":18,"lv":{"Biết":3,"Hiểu":8,"Vận dụng":6,"Nâng cao":1}}},{"t":"Bài 3. Đường tiệm cận của đồ thị hàm số","m":[{"t":"Tìm tiệm cận của đồ thị hàm số","w":"Đề cho hàm phân thức và hỏi tiệm cận đứng, tiệm cận ngang, tiệm cận xiên hoặc số tiệm cận.","s":["Tìm tập xác định và các giá trị làm mẫu bằng 0 mà tử khác 0: đó là tiệm cận đứng x = x₀.","Tính lim khi x → ±∞ của y; nếu bằng số hữu hạn b thì y = b là tiệm cận ngang.","Hàm y = (ax + b)/(cx + d), c ≠ 0: tiệm cận ngang y = a/c, tiệm cận đứng x = −d/c.","Hàm có bậc tử lớn hơn bậc mẫu đúng 1: chia đa thức để tìm tiệm cận xiên."],"n":["Nếu x₀ làm cả tử và mẫu bằng 0 thì chưa chắc là tiệm cận đứng; phải rút gọn trước.","Tiệm cận ngang xét cả hai phía +∞ và −∞.","Đồ thị hàm đa thức không có tiệm cận."]}],"sum":["Tiệm cận ngang y = y₀: lim f(x) = y₀ khi x → ±∞. Tiệm cận đứng x = x₀: lim f(x) = ±∞ khi x → x₀⁺ hoặc x₀⁻. Tiệm cận xiên y = ax + b: lim [f(x) − (ax + b)] = 0.","Tiệm cận ngang","Tiệm cận đứng: Tiệm cận đứng có dạng x = x₀ (đường thẳng đứng).","Tiệm cận xiên","Cách tìm tiệm cận xiên","Hàm phân thức: nhìn bậc tử và mẫu"],"d":["Tìm tiệm cận của đồ thị hàm số"],"e":["Sai: Mọi giá trị làm mẫu bằng 0 đều cho tiệm cận đứng. → Đúng: Phải kiểm tra tử số khác 0 (hoặc tính giới hạn). (Ví dụ y = (x² − 1)/(x − 1) = x + 1 với x ≠ 1: mẫu bằng 0 tại x = 1 nhưng giới hạn bằng 2, nên x = 1 không là…)","Hay nhầm: Đây là điều kiện của tiệm cận đứng, không phải tiệm cận ngang.","Hay nhầm: Điều kiện f(y₀) = 0 không liên quan đến tiệm cận.","Hay nhầm: Nếu f(x) = y₀ với mọi x thì đồ thị là một đường thẳng trùng với tiệm cận, không phải đặc trưng của tiệm cận ngang.","Hay nhầm: Mẫu số bằng 0 tại x = 0 và tử số khác 0 ở đó, nên đồ thị có tiệm cận đứng.","Hay nhầm: Chỉ có một giá trị làm mẫu số bằng 0, nên chỉ có một tiệm cận đứng."],"q":{"n":14,"lv":{"Biết":6,"Hiểu":3,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 4. Khảo sát sự biến thiên và vẽ đồ thị của hàm số","m":[{"t":"Khảo sát hàm số và các bài toán liên quan đồ thị","w":"Đề yêu cầu khảo sát và vẽ đồ thị, hoặc tìm điểm uốn, tâm đối xứng, số giao điểm với trục hoành.","s":["Tập xác định, tính đạo hàm, tìm cực trị và lập bảng biến thiên.","Tìm giới hạn ở vô cực và tiệm cận (nếu có).","Tìm điểm đặc biệt: giao với trục tung, trục hoành, điểm uốn (y″ = 0).","Vẽ đồ thị; số giao điểm với y = k chính là số nghiệm của f(x) = k."],"n":["Hàm bậc ba có tâm đối xứng là điểm uốn.","Số nghiệm của f(x) = k bằng số giao điểm của đồ thị với đường y = k.","Hàm bậc ba y = ax³ + bx² + cx + d có thể có 0 hoặc 2 cực trị."]}],"sum":["Khảo sát hàm số: tập xác định, sự biến thiên (y′, cực trị, giới hạn, tiệm cận, bảng biến thiên), rồi vẽ đồ thị. Bậc ba có tâm đối xứng (điểm uốn) và không có tiệm cận; phân thức bậc nhất có tâm đối…","Sơ đồ khảo sát hàm số y = f(x): Bước 1: Tìm tập xác định.","Mẹo vẽ đồ thị cho chính xác: Xác định thêm một số điểm đặc biệt, như giao điểm với các trục toạ độ (khi không quá phức tạp).","Hàm số bậc ba y = ax³ + bx² + cx + d: Hàm số bậc ba không có tiệm cận.","Hàm phân thức y = (ax + b)/(cx + d): Giao điểm của hai tiệm cận là tâm đối xứng của đồ thị."],"d":["Khảo sát hàm số và các bài toán liên quan đồ thị"],"e":["Hay nhầm: Vẽ đồ thị là bước cuối cùng, dựa trên bảng biến thiên đã lập.","Hay nhầm: Bảng biến thiên cần có đạo hàm và tập xác định, nên phải làm sau bước tìm tập xác định.","Hay nhầm: Giới hạn tại vô cực là một phần của bước khảo sát sự biến thiên, không phải bước đầu.","Hay nhầm: Hàm số bậc ba có tối đa hai điểm cực trị, và ở đây y' không đổi dấu nên không có điểm nào.","Hay nhầm: Muốn có hai cực trị, y' phải có hai nghiệm đổi dấu; ở đây y' không có nghiệm.","Hay nhầm: Hàm số bậc ba không thể có ba điểm cực trị."],"q":{"n":14,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":6,"Nâng cao":1}}},{"t":"Bài 5. Ứng dụng đạo hàm để giải quyết một số vấn đề liên quan đến thực tiễn","sum":["Vận tốc v = s′, gia tốc a = v′ = s″; chi phí biên là C′(x). Bài tối ưu hoá: lập hàm số Q(x), tìm tập xác định theo ý nghĩa thực tế, tìm GTLN hoặc GTNN, rồi kết luận theo ngữ cảnh.","Tốc độ thay đổi: Với y = f(x):","Chuyển động thẳng: Cho s = s(t) là hàm vị trí của vật.","Bài toán kinh tế","Quy trình giải bài toán tối ưu hoá: Bước 1: Xác định đại lượng Q cần lớn nhất hoặc nhỏ nhất và biểu diễn nó qua các đại lượng khác."],"e":["Hay nhầm: s(t) là vị trí, không phải vận tốc.","Hay nhầm: s''(t) là gia tốc, không phải vận tốc.","Hay nhầm: s(t)/t là vận tốc trung bình trên khoảng từ 0 đến t, không phải vận tốc tức thời.","Hay nhầm: Tổng chi phí là C(x), không phải đạo hàm của nó.","Hay nhầm: Chi phí cố định là giá trị C(0), không phải C'(x).","Hay nhầm: Số đơn vị tối đa không được xác định bởi đạo hàm chi phí biên."],"q":{"n":11,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài tập cuối chương I","e":["Hay nhầm: Hệ số của x³ âm và y' < 0 với mọi x, nên hàm số nghịch biến chứ không đồng biến.","Hay nhầm: y' không đổi dấu nên không có cực trị.","Hay nhầm: Hàm số nghịch biến trên toàn ℝ, không đổi chiều tại x = 0.","Hay nhầm: Trên hai khoảng này y' < 0, hàm số nghịch biến.","Hay nhầm: Hàm số không đơn điệu trên cả (−∞; 0), vì y' đổi dấu tại x = −1.","Hay nhầm: Trên (0; +∞) hàm số đổi chiều tại x = 1 nên không đồng biến trên cả khoảng."],"q":{"n":95,"lv":{"Biết":5,"Hiểu":60,"Vận dụng":28,"Nâng cao":2}}}]},{"t":"Chương II. Vectơ và hệ trục toạ độ trong không gian","l":[{"t":"Bài 6. Vectơ trong không gian","sum":["Ba quy tắc cộng: ba điểm AB + BC = AC, hình bình hành AB + AD = AC, hình hộp AB + AD + AA′ = AC′. Hiệu: OB − OA = AB. Tích vô hướng a·b = |a|·|b|·cos(a, b) là một số, bằng 0 khi hai vectơ vuông góc.","Vectơ và độ dài: Vectơ trong không gian là một đoạn thẳng có hướng.","Cùng phương, bằng nhau: Hai vectơ cùng phương nếu giá của chúng song song hoặc trùng nhau; khi đó chúng cùng hướng hoặc ngược hướng.","Vectơ-không: Vectơ có điểm đầu và điểm cuối trùng nhau gọi là vectơ-không, kí hiệu 0.","Ba quy tắc cộng vectơ","Hiệu của hai vectơ"],"e":["Sai: a·b là một vectơ. → Đúng: a·b là một số thực; còn a + b, ka mới là vectơ.","Hay nhầm: AD không nằm trong mặt phẳng (ABC).","Hay nhầm: AD không nằm trong mặt phẳng (ABC).","Hay nhầm: Có cặp AB, AC nằm trong mặt phẳng (ABC).","Hay nhầm: AD' không nằm trong mặt đáy ABCD.","Hay nhầm: AD' không nằm trong mặt đáy ABCD."],"q":{"n":25,"lv":{"Biết":1,"Hiểu":21,"Vận dụng":3}}},{"t":"Bài 7. Hệ trục toạ độ trong không gian","sum":["Hệ Oxyz có ba trục đôi một vuông góc tại O. M(x; y; z) khi OM = xi + yj + zk. Vectơ MN = (x_N − x_M; y_N − y_M; z_N − z_M): điểm cuối trừ điểm đầu. Hình chiếu lên mặt phẳng toạ độ thì thành phần còn…","Hệ toạ độ Oxyz: Ba trục Ox, Oy, Oz đôi một vuông góc tại gốc O; i, j, k là các vectơ đơn vị trên ba trục.","Toạ độ của một điểm: Bộ ba số (x; y; z) là duy nhất với mỗi điểm M.","Toạ độ của một vectơ: Toạ độ của vectơ a cũng là toạ độ của điểm M sao cho OM = a.","Toạ độ vectơ MN","Hình chiếu vuông góc của M(x; y; z)"],"e":["Sai: MN = M − N (lấy điểm đầu trừ điểm cuối). → Đúng: MN = điểm cuối − điểm đầu, tức N − M.","Hay nhầm: Cả ba cặp mặt đều vuông góc.","Hay nhầm: Các mặt phẳng này cắt nhau theo các trục.","Hay nhầm: Điều này không liên quan đến đơn vị đo.","Hay nhầm: Trong hình lập phương ba cạnh đó vuông góc đôi một.","Hay nhầm: Cả ba cạnh cùng độ dài 1."],"q":{"n":28,"lv":{"Biết":1,"Hiểu":26,"Vận dụng":1}}},{"t":"Bài 8. Biểu thức toạ độ của các phép toán vectơ","m":[{"t":"Tính toán với tọa độ vectơ trong không gian","w":"Đề cho tọa độ các điểm hoặc vectơ và hỏi độ dài, tích vô hướng, góc, trung điểm, trọng tâm.","s":["Tìm tọa độ vectơ: AB = (x_B − x_A; y_B − y_A; z_B − z_A).","Độ dài: |a| = √(x² + y² + z²); khoảng cách AB = |AB|.","Tích vô hướng a·b = x₁x₂ + y₁y₂ + z₁z₂; cos(a, b) = a·b/(|a||b|); a ⊥ b ⇔ a·b = 0.","Trung điểm M của AB có tọa độ nửa tổng; trọng tâm tam giác là trung bình cộng của ba đỉnh."],"n":["Vectơ AB là (điểm cuối) trừ (điểm đầu), không đảo ngược.","Cos góc giữa hai vectơ có thể âm; góc giữa hai đường thẳng thì lấy giá trị tuyệt đối.","Rút gọn số trước khi lấy căn."]}],"sum":["Với a = (x; y; z), b = (x′; y′; z′): cộng, trừ, nhân số làm từng toạ độ; a·b = xx′ + yy′ + zz′; |a| = √(x² + y² + z²); a ⊥ b khi a·b = 0. Trung điểm, trọng tâm: trung bình cộng toạ độ.","Cộng, trừ, nhân với một số: Cho a = (x; y; z), b = (x′; y′; z′) và số thực k:","Hai vectơ cùng phương","Trung điểm và trọng tâm","Tích vô hướng và vuông góc","Độ dài và khoảng cách"],"d":["Tính toán với tọa độ vectơ trong không gian"],"e":["Sai: Tích vô hướng a·b = (xx′; yy′; zz′). → Đúng: a·b là một số: cộng ba tích xx′ + yy′ + zz′.","Hay nhầm: Thành phần thứ ba phải là 6 + 4 + 4 = 14.","Hay nhầm: Thành phần thứ hai phải âm: 0 − 9 − 4 = −13.","Hay nhầm: Thành phần thứ nhất phải là −2.","Hay nhầm: Hai vectơ không cùng phương (a không tỉ lệ với b).","Hay nhầm: Hai vectơ không bằng nhau."],"q":{"n":30,"lv":{"Hiểu":18,"Vận dụng":10,"Biết":2}}},{"t":"Bài tập cuối chương II","e":["Hay nhầm: Đúng: BG + CG + DG = 0 vì G là trọng tâm BCD.","Hay nhầm: Đúng: AB + AC + AD = 3AG.","Hay nhầm: Đúng: CC' = AA' nên AB + CC' = AB'.","Hay nhầm: Đúng: BB' = AA' nên AD + BB' = AD'.","Hay nhầm: a²/4 không khớp với AB·AM = a²/2.","Hay nhầm: a²/3 không khớp với kết quả tính bằng vectơ trung bình."],"q":{"n":27,"lv":{"Hiểu":13,"Vận dụng":12,"Biết":2}}}]},{"t":"Chương III. Các số đặc trưng đo mức độ phân tán của mẫu số liệu ghép nhóm","l":[{"t":"Bài 9. Khoảng biến thiên và khoảng tứ phân vị","sum":["Khoảng biến thiên R = a_{k+1} − a₁ (đầu mút phải nhóm cuối trừ đầu mút trái nhóm đầu). Khoảng tứ phân vị Δ_Q = Q₃ − Q₁ không bị ảnh hưởng bởi giá trị bất thường. Với mẫu ghép nhóm, các giá trị này…","Khoảng biến thiên R: a₁ là đầu mút trái của nhóm đầu; a_{k+1} là đầu mút phải của nhóm cuối.","Tứ phân vị thứ r (r = 1, 2, 3): n là cỡ mẫu; m_i là tần số của nhóm thứ i.","Khoảng tứ phân vị: Chỉ phụ thuộc vào nửa giữa của mẫu nên không bị ảnh hưởng bởi giá trị bất thường.","Số liệu ghép nhóm chỉ là xấp xỉ: Giá trị R và Δ_Q tính từ mẫu ghép nhóm là giá trị xấp xỉ."],"e":["Hay nhầm: Khoảng biến thiên của tổ 2 nhỏ hơn.","Hay nhầm: Có thể so sánh vì cùng đơn vị phút.","Hay nhầm: Phòng X có khoảng tứ phân vị nhỏ hơn nên ít phân tán hơn.","Hay nhầm: Có thể so sánh vì cùng đơn vị phút.","Hay nhầm: Mẫu ghép nhóm không cho giá trị chính xác của khoảng biến thiên.","Hay nhầm: Mẫu gốc cho giá trị chính xác."],"q":{"n":22,"lv":{"Hiểu":12,"Vận dụng":8,"Biết":2}}},{"t":"Bài 10. Phương sai và độ lệch chuẩn","m":[{"t":"Tính phương sai và độ lệch chuẩn của mẫu số liệu ghép nhóm","w":"Đề cho bảng tần số ghép nhóm và yêu cầu tính số trung bình, phương sai, độ lệch chuẩn hoặc so sánh độ phân tán.","s":["Lập giá trị đại diện x_i của mỗi nhóm (trung bình hai đầu mút) và tần số m_i.","Tính số trung bình x̄ = (Σ m_i x_i)/n với n = Σ m_i.","Tính phương sai s² = (Σ m_i (x_i − x̄)²)/n (hoặc s² = Σ m_i x_i²/n − x̄²).","Độ lệch chuẩn s = √s²; so sánh các mẫu có số trung bình gần nhau."],"n":["Dùng giá trị đại diện, không dùng đầu mút.","Phương sai là số không âm; s² bằng 0 khi mọi giá trị bằng nhau.","Độ lệch chuẩn cùng đơn vị với số liệu, phương sai thì đơn vị bình phương."]}],"sum":["Phương sai s² = (m₁(x₁ − x̄)² + … + m_k(x_k − x̄)²)/n; độ lệch chuẩn s = √s². Công thức rút gọn: s² = (Σ m_i·x_i²)/n − x̄². Càng lớn thì mẫu càng phân tán; chỉ so sánh khi các số trung bình gần nhau.","Phương sai s²: n = m₁ + … + m_k là cỡ mẫu; m_i là tần số của nhóm i.","Độ lệch chuẩn s: Có cùng đơn vị với đơn vị của mẫu số liệu (phương sai thì có đơn vị bình phương).","Công thức rút gọn","Ý nghĩa: Đo mức độ phân tán của mẫu quanh số trung bình: giá trị càng lớn thì mẫu càng phân tán.","So sánh và ứng dụng: Trong tài chính, độ lệch chuẩn của lợi nhuận đo độ rủi ro của phương án đầu tư."],"d":["Tính phương sai và độ lệch chuẩn của mẫu số liệu ghép nhóm"],"e":["Sai: x_i là tần số của nhóm. → Đúng: x_i là giá trị đại diện (trung điểm nhóm); tần số là m_i.","Hay nhầm: Đây là phương sai (làm tròn), không phải độ lệch chuẩn.","Hay nhầm: Đây là số trung bình, không phải độ lệch chuẩn.","Hay nhầm: Đó là số trung bình, không phải phương sai hay độ lệch chuẩn.","Hay nhầm: Số lần chạy là tần số, không liên quan đến phương sai.","Hay nhầm: Đó là giá trị nhỏ nhất, không phải ý nghĩa của độ phân tán."],"q":{"n":27,"lv":{"Hiểu":8,"Vận dụng":17,"Biết":2}}},{"t":"Bài tập cuối chương III","e":["Hay nhầm: Lấy 18 − 15, chưa đúng hai đầu mút.","Hay nhầm: Hiệu 18 − 14 không phải đầu mút của nhóm cuối.","Hay nhầm: Lấy 20 − 14, sai đầu mút.","Hay nhầm: Tần số tích luỹ của [14; 15) chỉ là 1 < 5.","Hay nhầm: Tần số tích luỹ của [15; 16) là 4 < 5.","Hay nhầm: Tứ phân vị thứ nhất không nằm ở nhóm có tần số tích luỹ 18."],"q":{"n":25,"lv":{"Hiểu":8,"Vận dụng":15,"Biết":2}}}]}]},{"t":"Toán 12, tập 2","c":[{"t":"Chương IV. Nguyên hàm và tích phân","l":[{"t":"Bài 11. Nguyên hàm","m":[{"t":"Tìm nguyên hàm thỏa điều kiện cho trước","w":"Đề cho f(x) và điều kiện F(x₀) = y₀, yêu cầu tìm F(x) hoặc giá trị F tại điểm khác.","s":["Tìm một nguyên hàm tổng quát: F(x) = ∫f(x)dx + C, dùng bảng nguyên hàm từng hạng tử.","Thay điều kiện F(x₀) = y₀ để tìm C.","Viết F(x) cụ thể.","Thay x vào F(x) để tính giá trị cần tìm."],"n":["Nhớ cộng hằng số C; mỗi nguyên hàm sai khác một hằng số.","∫xⁿdx = xⁿ⁺¹/(n + 1) + C với n ≠ −1.","Kiểm tra bằng cách lấy đạo hàm F(x) có ra f(x) không."]}],"sum":["F là nguyên hàm của f trên K khi F′(x) = f(x). Mọi nguyên hàm có dạng F(x) + C. Nhớ bảng: ∫x^α dx = x^(α+1)/(α+1) + C; ∫(1/x)dx = ln|x| + C; ∫cos x dx = sin x + C; ∫sin x dx = −cos x + C.","Nguyên hàm: Cho f(x) xác định trên khoảng K (hoặc đoạn, nửa khoảng).","Họ các nguyên hàm: Nếu F(x) là một nguyên hàm của f(x) thì mọi nguyên hàm của f(x) đều có dạng F(x) + C.","Tính chất","Bảng nguyên hàm thường gặp","Dễ nhầm: ∫(1/x)dx"],"d":["Tìm nguyên hàm thỏa điều kiện cho trước"],"e":["Sai: Viết ∫2x dx = x². → Đúng: Phải thêm hằng số: ∫2x dx = x² + C.","Sai: ∫(1/x)dx = ln x + C. → Đúng: ∫(1/x)dx = ln|x| + C (có dấu giá trị tuyệt đối). (Công thức x^α không dùng được khi α = −1; trường hợp đó có công thức riêng là ln|x|.)","Hay nhầm: G'(x) = x² + 2x khác f(x).","Hay nhầm: G không phải nguyên hàm vì G'(x) ≠ f(x).","Hay nhầm: F'(x) = f(x) nên F là nguyên hàm.","Hay nhầm: Đạo hàm của 1/x² là −2/x³, không phải 1/x."],"q":{"n":34,"lv":{"Hiểu":24,"Vận dụng":8,"Biết":2}}},{"t":"Bài 12. Tích phân","m":[{"t":"Tính tích phân bằng nguyên hàm và tính chất","w":"Đề cho tích phân xác định của hàm đa thức, hoặc cho các tích phân đã biết và yêu cầu suy ra tích phân khác.","s":["Tìm một nguyên hàm F(x) của f(x).","Áp dụng công thức Newton–Leibniz: ∫ₐᵇ f(x)dx = F(b) − F(a).","Với tích phân cho trước: dùng tính chất cộng đoạn, tuyến tính (hằng số ra ngoài, tổng bằng tổng).","Tính cẩn thận dấu và kiểm tra bằng ý nghĩa hình học (diện tích) nếu f không âm."],"n":["Không cần cộng C khi tính tích phân xác định.","Đảo cận thì đổi dấu: ∫ₐᵇ = −∫ᵇₐ.","Tính chất cộng đoạn chỉ áp dụng khi cùng hàm f."]}],"sum":["∫_a^b f(x)dx = F(b) − F(a) với F là một nguyên hàm của f: cận trên trừ cận dưới. Nếu f ≥ 0 trên [a; b] thì tích phân là diện tích hình thang cong. Đổi cận thì đổi dấu: ∫_a^b = −∫_b^a.","Diện tích hình thang cong: Hình thang cong giới hạn bởi y = f(x) liên tục, không âm trên [a; b], trục hoành và hai đường x = a, x = b.","Tích phân từ a đến b: a gọi là cận dưới, b là cận trên.","Quy ước và ý nghĩa hình học: Nếu f(x) liên tục và không âm trên [a; b] thì ∫_a^b f(x)dx là diện tích hình thang cong giới hạn bởi y = f(x), trục hoành, x = a, x = b.","Tính chất","Giá trị trung bình của hàm số"],"d":["Tính tích phân bằng nguyên hàm và tính chất"],"e":["Sai: ∫_a^b f(x)dx = F(a) − F(b). → Đúng: Cận trên trừ cận dưới: F(b) − F(a).","Hay nhầm: Hình được giới hạn bởi trục hoành, không phải trục tung.","Hay nhầm: Đường cong là y = x², không phải x³.","Hay nhầm: Hai đường thẳng là x = 1 và x = 2.","Hay nhầm: √3/2 là sin(π/3), không phải sin(π/6).","Hay nhầm: 1 là sin(π/2), không phải sin(π/6)."],"q":{"n":36,"lv":{"Biết":1,"Hiểu":25,"Vận dụng":10}}},{"t":"Bài 13. Ứng dụng hình học của tích phân","m":[{"t":"Tính diện tích hình phẳng và thể tích khối tròn xoay","w":"Đề cho các đường y = f(x), y = g(x), x = a, x = b và hỏi diện tích hình phẳng hoặc thể tích khối tròn xoay quanh Ox.","s":["Tìm các cận bằng cách giải f(x) = g(x) (nếu đề chưa cho đủ cận).","Xét dấu f(x) − g(x) trên đoạn để bỏ dấu giá trị tuyệt đối: S = ∫ₐᵇ |f(x) − g(x)| dx.","Thể tích quay quanh Ox: V = π∫ₐᵇ [f(x)]² dx.","Tính tích phân, ghi đơn vị."],"n":["Diện tích luôn dương; nếu hiệu âm phải đổi dấu hoặc lấy giá trị tuyệt đối.","Nếu hiệu đổi dấu trên đoạn thì chia đoạn tại nghiệm.","Công thức thể tích có π và bình phương của hàm."]}],"sum":["Diện tích: S = ∫|f(x)|dx (với trục hoành) hoặc ∫|f(x) − g(x)|dx (hai đồ thị). Thể tích vật thể: V = ∫S(x)dx. Khối tròn xoay quanh Ox: V = π∫f²(x)dx. Chú ý: có giá trị tuyệt đối với diện tích, có π…","Diện tích hình phẳng giới hạn bởi một đồ thị: Đồ thị y = f(x) liên tục, trục hoành và hai đường x = a, x = b (a < b):","Diện tích giới hạn bởi hai đồ thị: Nếu f(x) − g(x) không đổi dấu trên [a; b] thì S = |∫_a^b [f(x) − g(x)]dx|.","Thể tích vật thể theo diện tích thiết diện: Vật thể B nằm giữa hai mặt phẳng vuông góc với Ox tại x = a và x = b; thiết diện vuông góc Ox tại x có diện tích S(x) liên tục trên [a; b]:","Thể tích khối tròn xoay quanh trục Ox: Quay hình phẳng giới hạn bởi y = f(x) ≥ 0, trục hoành, x = a, x = b quanh Ox:"],"d":["Tính diện tích hình phẳng và thể tích khối tròn xoay"],"e":["Sai: Tính S = ∫_a^b f(x)dx mà không xét dấu f(x). → Đúng: Phải lấy giá trị tuyệt đối: chia đoạn tại nghiệm để bỏ dấu |·|. (Ví dụ ∫_0^2 (x − 1)dx = 0, nhưng diện tích thật là ∫_0^2 |x − 1|dx = 1.)","Hay nhầm: Hai phần có diện tích dương, không triệt tiêu nhau khi lấy trị tuyệt đối.","Hay nhầm: 2π là độ dài đường tròn đơn vị, không phải diện tích này.","Hay nhầm: Chỉ tính một nửa, bỏ qua phần dưới trục hoành.","Hay nhầm: Đã quên trừ giá trị tại cận dưới (giá trị bằng 1).","Hay nhầm: 1 − √2 có dấu sai: cos x − sin x ≥ 0 trên [0; π/4]."],"q":{"n":32,"lv":{"Hiểu":21,"Vận dụng":9,"Biết":2}}},{"t":"Bài tập cuối chương IV","e":["Hay nhầm: Đạo hàm của 2cos 2x là −4sin 2x.","Hay nhầm: Đạo hàm của −cos 2x là 2sin 2x, không phải sin 2x.","Hay nhầm: Đạo hàm của (1/2)cos 2x là −sin 2x, sai dấu.","Hay nhầm: Nguyên hàm của eˣ là eˣ, không phải xeˣ.","Hay nhầm: Đây là f(x), không phải nguyên hàm (F(0) = 1 − 3 = −2).","Hay nhầm: Không đúng: nguyên hàm của e^(−x) là −e^(−x)."],"q":{"n":22,"lv":{"Hiểu":19,"Vận dụng":1,"Biết":2}}}]},{"t":"Chương V. Phương pháp toạ độ trong không gian","l":[{"t":"Bài 14. Phương trình mặt phẳng","m":[{"t":"Viết phương trình mặt phẳng và tính khoảng cách","w":"Đề cho điểm, vectơ pháp tuyến, hai vectơ chỉ phương hoặc ba điểm và yêu cầu viết phương trình mặt phẳng; hoặc tính khoảng cách điểm đến mặt phẳng.","s":["Tìm vectơ pháp tuyến n: cho sẵn, hoặc n = [u, v] (tích có hướng) của hai vectơ không cùng phương nằm trong mặt phẳng.","Viết phương trình dạng a(x − x₀) + b(y − y₀) + c(z − z₀) = 0 với (x₀; y₀; z₀) là điểm thuộc mặt phẳng.","Khai triển về ax + by + cz + d = 0.","Khoảng cách từ M(x₁; y₁; z₁) đến mặt phẳng: d = |ax₁ + by₁ + cz₁ + d|/√(a² + b² + c²)."],"n":["Vectơ pháp tuyến vuông góc với mọi vectơ nằm trong mặt phẳng.","Có thể nhân n với số khác 0 mà phương trình không đổi.","Thế tọa độ ba điểm vào phương trình để kiểm tra."]}],"sum":["Mặt phẳng đi qua M₀ có vectơ pháp tuyến n = (A; B; C): A(x − x₀) + B(y − y₀) + C(z − z₀) = 0. Khoảng cách từ M₀ đến (P): d = |Ax₀ + By₀ + Cz₀ + D| / √(A² + B² + C²). Vuông góc: AA′ + BB′ + CC′ = 0.","Vectơ pháp tuyến: Vectơ n ≠ 0 là vectơ pháp tuyến của mặt phẳng (α) nếu giá của n vuông góc với (α).","Tích có hướng: [u, v] vuông góc với cả u và v.","Phương trình tổng quát: Mọi phương trình dạng Ax + By + Cz + D = 0 (A, B, C không đồng thời bằng 0) là phương trình của một mặt phẳng.","Phương trình đoạn chắn: Mặt phẳng cắt Ox, Oy, Oz tại A(a; 0; 0), B(0; b; 0), C(0; 0; c) với abc ≠ 0:","Hai mặt phẳng (P), (Q): (P): Ax + By + Cz + D = 0 và (Q): A′x + B′y + C′z + D′ = 0"],"d":["Viết phương trình mặt phẳng và tính khoảng cách"],"e":["Sai: Có n′ = kn là hai mặt phẳng song song. → Đúng: Phải có thêm D′ ≠ kD; nếu D′ = kD thì hai mặt phẳng trùng nhau.","Hay nhầm: Thành phần thứ hai là 0·3 − 1·(−4) = 4, không phải −4.","Hay nhầm: Thành phần đầu là (−2)(−4) − 0·1 = 8, không âm.","Hay nhầm: Thành phần thứ ba là 1·1 − (−2)·3 = 7, không âm.","Hay nhầm: Thành phần thứ hai là 0·1 − 2·2 = −4, không phải 4.","Hay nhầm: Thành phần đầu là (−1)(2) − 0·(−1) = −2, không phải 2."],"q":{"n":31,"lv":{"Hiểu":21,"Vận dụng":8,"Biết":2}}},{"t":"Bài 15. Phương trình đường thẳng trong không gian","m":[{"t":"Điểm thuộc đường thẳng và giao điểm đường thẳng với mặt phẳng","w":"Đề cho đường thẳng d dạng tham số hoặc chính tắc, hỏi điểm thuộc d, vectơ chỉ phương, giao điểm với mặt phẳng.","s":["Viết d dạng tham số: x = x₀ + at, y = y₀ + bt, z = z₀ + ct với (a; b; c) là vectơ chỉ phương.","Điểm thuộc d: thay giá trị t cụ thể.","Giao điểm với mặt phẳng (P): thế x, y, z theo t vào phương trình (P), giải ra t.","Thay t vào tham số để có tọa độ giao điểm."],"n":["Dạng chính tắc (x − x₀)/a = (y − y₀)/b = (z − z₀)/c cho cùng ba biểu thức bằng t.","Nếu phương trình theo t vô nghiệm thì d song song (P); nghiệm với mọi t thì d nằm trong (P).","Vectơ chỉ phương có thể nhân với số khác 0."]}],"sum":["Đường thẳng qua M₀(x₀; y₀; z₀) có vectơ chỉ phương u = (a; b; c): tham số x = x₀ + at, y = y₀ + bt, z = z₀ + ct. Hai đường thẳng vuông góc khi u₁·u₂ = 0. Vị trí tương đối xét bằng u₁, u₂ và…","Vectơ chỉ phương: Vectơ u ≠ 0 là vectơ chỉ phương của Δ nếu giá của u song song hoặc trùng với Δ.","Phương trình tham số và chính tắc: Δ đi qua M₀(x₀; y₀; z₀), vectơ chỉ phương u = (a; b; c):","Hai đường thẳng vuông góc","Vị trí tương đối của Δ₁ (qua A₁, u₁) và Δ₂ (qua A₂, u₂)"],"d":["Điểm thuộc đường thẳng và giao điểm đường thẳng với mặt phẳng"],"e":["Sai: Luôn viết được phương trình chính tắc. → Đúng: Chỉ viết được khi a, b, c đều khác 0 (mẫu số không được bằng 0).","Hay nhầm: Với x = 2 thì t = 0, khi đó y = 0 ≠ 3, nên (2; 3; 1) không thuộc Δ.","Hay nhầm: Vectơ chỉ phương là các hệ số của t, tức (1; 3; 1), không phải (2; 3; 1).","Hay nhầm: Với x = 0 thì t = −2, khi đó y = −6 ≠ 0, nên O không thuộc Δ.","Hay nhầm: Điểm đi qua bị đổi dấu: phải là (1; −2; 4), không phải (−1; 2; −4).","Hay nhầm: Thành phần thứ hai của vectơ chỉ phương là −5, không phải 5."],"q":{"n":31,"lv":{"Biết":1,"Hiểu":13,"Vận dụng":17}}},{"t":"Bài 16. Công thức tính góc trong không gian","m":[{"t":"Tính góc giữa đường thẳng, mặt phẳng","w":"Đề cho vectơ chỉ phương, vectơ pháp tuyến và hỏi côsin hoặc sin của góc giữa hai đường thẳng, đường thẳng – mặt phẳng, hai mặt phẳng.","s":["Xác định vectơ chỉ phương u của đường thẳng, vectơ pháp tuyến n của mặt phẳng.","Hai đường thẳng: cos φ = |u₁·u₂|/(|u₁||u₂|). Hai mặt phẳng: cos φ = |n₁·n₂|/(|n₁||n₂|).","Đường thẳng – mặt phẳng: sin φ = |u·n|/(|u||n|).","Tính tử và mẫu rồi rút gọn; góc nhận giá trị trong [0°; 90°]."],"n":["Dùng giá trị tuyệt đối vì góc giữa hai đường thẳng không quá 90°.","Đường thẳng – mặt phẳng dùng sin, không dùng cos.","Tính |u| và |n| cẩn thận, tránh quên căn."]}],"sum":["Đường – đường: cos = |u·u′|/(|u||u′|). Đường – mặt: sin = |u·n|/(|u||n|). Mặt – mặt: cos = |n·m|/(|n||m|). Luôn có giá trị tuyệt đối ở tử số vì góc giữa hai đường, hai mặt không quá 90°.","Góc giữa hai đường thẳng: Δ, Δ′ có vectơ chỉ phương u = (a; b; c), u′ = (a′; b′; c′):","Góc giữa đường thẳng và mặt phẳng: Δ có vectơ chỉ phương u = (a; b; c), (P) có vectơ pháp tuyến n = (A; B; C):","Góc giữa hai mặt phẳng: (P), (Q) có vectơ pháp tuyến n, m:","Tổng hợp: Nếu không nói gì thêm, góc tính theo đơn vị độ và làm tròn đến chữ số thập phân thứ nhất."],"d":["Tính góc giữa đường thẳng, mặt phẳng"],"e":["Sai: Góc giữa đường và mặt tính bằng cos của u và n. → Đúng: Dùng sin: góc đường – mặt bù với góc giữa u và n.","Hay nhầm: Mẫu là √2 · 3 = 3√2, không phải 3.","Hay nhầm: Tử số là |u · u′| = 4, không phải 1.","Hay nhầm: Rút gọn sai: 4/(3√2) = 2√2/3, không phải 2/3.","Hay nhầm: Thành phần z của u là −2, nên tử số là 2, không phải 1.","Hay nhầm: |u| = √(1 + 4 + 4) = 3, không phải √5."],"q":{"n":19,"lv":{"Hiểu":11,"Vận dụng":6,"Biết":2}}},{"t":"Bài 17. Phương trình mặt cầu","m":[{"t":"Tìm tâm, bán kính mặt cầu và viết phương trình mặt cầu","w":"Đề cho phương trình mặt cầu dạng khai triển, hoặc cho tâm và điều kiện (qua điểm, tiếp xúc mặt phẳng) và yêu cầu viết phương trình.","s":["Dạng x² + y² + z² − 2ax − 2by − 2cz + d = 0: tâm I(a; b; c), R = √(a² + b² + c² − d).","Cho tâm I và điểm A thuộc mặt cầu: R = IA.","Mặt cầu tâm I tiếp xúc mặt phẳng (P): R = d(I, (P)).","Viết (x − a)² + (y − b)² + (z − c)² = R²."],"n":["Hệ số của x là −2a, nên a bằng nửa hệ số đổi dấu.","Phải kiểm tra a² + b² + c² − d > 0 mới là mặt cầu.","R² chứ không phải R trong vế phải của phương trình."]}],"sum":["Mặt cầu tâm I(a; b; c), bán kính R: (x − a)² + (y − b)² + (z − c)² = R². Dạng khai triển x² + y² + z² − 2ax − 2by − 2cz + d = 0 là mặt cầu khi a² + b² + c² − d > 0, khi đó R = √(a² + b² + c² − d).","Phương trình mặt cầu: Mặt cầu (S) tâm I(a; b; c) bán kính R > 0:","Dạng khai triển","Vị trí của điểm M so với mặt cầu"],"d":["Tìm tâm, bán kính mặt cầu và viết phương trình mặt cầu"],"e":["Sai: Từ (x + 2)² suy ra tâm có hoành độ 2. → Đúng: (x + 2)² = (x − (−2))² nên hoành độ tâm là −2.","Hay nhầm: Tâm có tọa độ đối dấu: phải là (1; −3; 0).","Hay nhầm: R² = 5 nên R = √5, không phải 5.","Hay nhầm: Tọa độ y của tâm là −3, không phải 3.","Hay nhầm: Tâm có dấu sai: phải là (3/2; 0; −3).","Hay nhầm: Vế phải phải là R² = 81/16, không phải 9/4."],"q":{"n":27,"lv":{"Hiểu":18,"Vận dụng":7,"Biết":2}}},{"t":"Bài tập cuối chương V","e":["Hay nhầm: Hệ số của y là −2, không phải 2.","Hay nhầm: Hệ số của y là −2 và của z là −3.","Hay nhầm: Hệ số của z là −3, không phải 3.","Hay nhầm: Vectơ pháp tuyến không phải (1; −1; 2).","Hay nhầm: Vectơ pháp tuyến không phải (1; −1; 2).","Hay nhầm: Hằng số sai: thay I được 2 − 1 − 2 − 1 ≠ 0."],"q":{"n":30,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":21}}}]},{"t":"Chương VI. Xác suất có điều kiện","l":[{"t":"Bài 18. Xác suất có điều kiện","m":[{"t":"Tính xác suất có điều kiện","w":"Đề cho hai biến cố A, B (lấy bi, rút thẻ, bảng số liệu) và hỏi P(A|B), P(AB), hoặc kiểm tra hai biến cố độc lập.","s":["Xác định biến cố đã xảy ra (điều kiện B) và biến cố cần tính A.","Tính P(B) và P(AB) (hoặc dùng bảng: lấy số liệu của A trong nhóm B chia tổng của B).","P(A|B) = P(AB)/P(B); công thức nhân P(AB) = P(B)·P(A|B).","Kiểm tra độc lập: P(AB) = P(A)·P(B)."],"n":["Điều kiện đã xảy ra, nên mẫu số là số kết quả của B, không phải toàn bộ không gian mẫu.","Lấy không hoàn lại thì số phần tử giảm một sau mỗi lần lấy.","P(A|B) khác P(B|A) nói chung."]}],"sum":["P(A | B) = P(AB)/P(B) (P(B) > 0): mẫu số là xác suất của biến cố đã xảy ra. Nhân xác suất: P(AB) = P(B)·P(A | B) = P(A)·P(B | A). Độc lập khi P(AB) = P(A)·P(B).","Xác suất có điều kiện: Xác suất của biến cố A với điều kiện biến cố B đã xảy ra (P(B) > 0):","Công thức nhân xác suất: Với hai biến cố A, B bất kì:","Sơ đồ cây: Các nhánh ghi xác suất có điều kiện.","Hai biến cố độc lập: Khi đó P(A | B) = P(A) và P(B | A) = P(B).","Dùng bảng thống kê 2 × 2: Bảng có hai dòng và hai cột."],"d":["Tính xác suất có điều kiện"],"e":["Sai: Nhầm P(A | B) với P(B | A). → Đúng: P(A | B) chia cho P(B) (biến cố đã xảy ra); P(B | A) chia cho P(A).","Hay nhầm: 20/29 là xác suất An lấy trắng khi không biết gì về Bình, sai vì Bình đã lấy một viên trắng.","Hay nhầm: Mẫu phải là 29 viên còn lại, không phải 30.","Hay nhầm: 10/29 là xác suất An lấy được bi đen.","Hay nhầm: 1/20 là xác suất rút được thẻ số 10 khi không biết thông tin số chẵn.","Hay nhầm: 1/2 là xác suất rút được số chẵn, không phải xác suất thẻ số 10."],"q":{"n":28,"lv":{"Biết":1,"Hiểu":18,"Vận dụng":9}}},{"t":"Bài 19. Công thức xác suất toàn phần và công thức Bayes","m":[{"t":"Xác suất toàn phần và công thức Bayes","w":"Đề có một biến cố E xảy ra qua nhiều nguyên nhân (máy A, máy B; hộp 1, hộp 2) và hỏi P(E), hoặc hỏi nguyên nhân nào gây ra E biết E đã xảy ra.","s":["Đặt các biến cố nguyên nhân A₁, A₂,... (đôi một xung khắc, tổng xác suất bằng 1) và biến cố kết quả E.","Xác suất toàn phần: P(E) = P(A₁)P(E|A₁) + P(A₂)P(E|A₂) + ...","Bayes: P(A₁|E) = P(A₁)P(E|A₁)/P(E).","Thay số, rút gọn phân số."],"n":["Các nguyên nhân phải bao quát hết khả năng, tổng xác suất bằng 1.","Mẫu số của Bayes chính là xác suất toàn phần P(E).","Đừng nhầm P(E|A₁) (cho trước) với P(A₁|E) (cần tìm)."]}],"sum":["Toàn phần: P(B) = P(A)·P(B | A) + P(Ā)·P(B | Ā). Bayes: P(A | B) = P(A)·P(B | A) / P(B). Trên sơ đồ cây: nhân dọc đường đi, cộng các đường đi đến cùng kết quả.","Công thức xác suất toàn phần: Với hai biến cố A và Ā (đối của A):","Sơ đồ hình cây: Nhân các xác suất dọc theo mỗi đường đi.","Công thức Bayes"],"d":["Xác suất toàn phần và công thức Bayes"],"e":["Hay nhầm: 0,6 là P(B | A), xác suất đỗ khi đã chọn A00, không phải xác suất chọn A00 khi biết đã đỗ.","Hay nhầm: 0,8 là P(A), xác suất chọn A00 trước khi biết kết quả.","Hay nhầm: 0,95 không liên quan đến bài toán này.","Hay nhầm: 0,9 là P(xác nhận | loại I), không phải xác suất chai là loại I khi đã được xác nhận.","Hay nhầm: 0,3 là tỉ lệ rượu loại I trước khi nếm.","Hay nhầm: 0,95 là xác suất xác nhận đúng chai không phải loại I."],"q":{"n":13,"lv":{"Hiểu":4,"Vận dụng":7,"Biết":2}}},{"t":"Bài tập cuối chương VI","e":["Hay nhầm: 3/16 không khớp: P(AB) = P(A) · P(B | A) = 2/15, không phải 3/16.","Hay nhầm: 1/5 không đúng: P(AB) = 2/5 · 1/3 = 2/15.","Hay nhầm: 4/15 là 2/5 · 2/3, nhưng P(B | A) = 1/3 nên P(AB) = 2/15.","Hay nhầm: 1/7 không khớp: P(Ā) = 3/5 và P(B | Ā) = 1/4, tích là 3/20.","Hay nhầm: 4/19 không đúng: P(BĀ) = 3/5 · 1/4 = 3/20.","Hay nhầm: 4/21 không đúng: P(BĀ) = P(Ā) · P(B | Ā) = 3/20."],"q":{"n":15,"lv":{"Hiểu":6,"Vận dụng":7,"Biết":2}}}]},{"t":"Bài tập ôn tập cuối năm","l":[{"t":"Bài tập ôn tập cuối năm","e":["Hay nhầm: Trên (−∞; 1) đạo hàm dương, hàm đồng biến.","Hay nhầm: Trên (3; +∞) đạo hàm dương, hàm đồng biến.","Hay nhầm: Đạo hàm đổi dấu nên hàm không nghịch biến trên toàn ℝ.","Hay nhầm: y(2) = 7 > 6, nên M không thể bằng 6.","Hay nhầm: 19/3 là y(4), nhưng y(2) = 7 lớn hơn.","Hay nhầm: 20/3 không phải giá trị của hàm số trên đoạn [2; 4]."],"q":{"n":39,"lv":{"Hiểu":8,"Vận dụng":29,"Biết":2}}}]}]},{"t":"Đề thi thử tốt nghiệp","c":[{"t":"Đề thi thử theo cấu trúc tốt nghiệp THPT","l":[{"t":"Đề thi thử tốt nghiệp THPT số 1","e":["Hay nhầm: Nhầm với nguyên hàm của sin x.","Hay nhầm: Lấy chính hàm số, không phải nguyên hàm.","Hay nhầm: Nhầm với nguyên hàm của 1/cos²x.","Hay nhầm: k là số nhóm, không phải cỡ mẫu.","Hay nhầm: Đây là tích của hai tần số, không phải tổng.","Hay nhầm: Đây là khoảng biến thiên R."],"q":{"n":22,"lv":{"Biết":2,"Hiểu":10,"Vận dụng":10}}},{"t":"Đề thi thử tốt nghiệp THPT số 2","e":["Hay nhầm: Chia cho tổng độ dài thay vì tích độ dài.","Hay nhầm: Dùng hiệu vectơ thay vì tích vô hướng.","Hay nhầm: Quên chia cho tích độ dài.","Hay nhầm: Đó là đạo hàm của x^α, không phải nguyên hàm.","Hay nhầm: Nhầm với công thức có logarit.","Hay nhầm: Hệ số của x³ âm nên đồ thị đi xuống bên phải, trái với hình."],"q":{"n":22,"lv":{"Biết":2,"Hiểu":10,"Vận dụng":10}}},{"t":"Đề thi thử tốt nghiệp THPT số 3","e":["Hay nhầm: Cộng hai vectơ thay vì trừ.","Hay nhầm: Tính sai thành phần y: 2 + (−1) = 1.","Hay nhầm: Đạo hàm của cos x là −sin x, không phải sin x.","Hay nhầm: Nhầm với nguyên hàm của cos x.","Hay nhầm: Nhầm với nguyên hàm của 1/cos²x.","Hay nhầm: Đảo ngược: x = −2 là cực đại, x = 0 là cực tiểu."],"q":{"n":22,"lv":{"Biết":2,"Hiểu":10,"Vận dụng":10}}}]}]}]},{"id":"ly","name":"Vật lí","b":[{"t":"Vật lí 12","c":[{"t":"Chương I. Vật lí nhiệt","l":[{"t":"Bài 1. Cấu trúc của chất. Sự chuyển thể","sum":["Chất cấu tạo từ phân tử chuyển động hỗn loạn không ngừng, giữa chúng có lực liên kết. Rắn có thể tích và hình dạng riêng; lỏng chỉ có thể tích riêng; khí không có cả hai. Sáu quá trình chuyển thể:…","Mô hình động học phân tử: Chất được cấu tạo từ các hạt riêng biệt là phân tử.","Chuyển động Brown: Chuyển động hỗn loạn, không ngừng của các hạt rất nhỏ (như hạt phấn hoa) do va chạm với các phân tử chất lỏng hoặc chất khí.","Ba thể của chất: Khoảng cách giữa các phân tử càng lớn thì lực liên kết càng yếu.","Sáu quá trình chuyển thể","Bay hơi và sôi"],"e":["Sai: Chất lỏng chỉ hoá hơi khi sôi. → Đúng: Bay hơi xảy ra ở mọi nhiệt độ; sôi chỉ xảy ra ở nhiệt độ sôi.","Hay nhầm: Đây là nội dung thứ nhất của mô hình.","Hay nhầm: Đây là nội dung thứ hai của mô hình.","Hay nhầm: Đây là nội dung thứ ba của mô hình.","Hay nhầm: Chất rắn cũng có các phân tử dao động không ngừng, không đứng yên.","Hay nhầm: Thí nghiệm Brown cho thấy cấu tạo gián đoạn, không phải liên tục."],"q":{"n":12,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":1}}},{"t":"Bài 2. Nội năng. Định luật I của nhiệt động lực học","m":[{"t":"Áp dụng định luật I nhiệt động lực học","w":"Đề cho nhiệt lượng nhận hoặc tỏa, công nhận hoặc sinh và hỏi độ biến thiên nội năng, hoặc ngược lại.","s":["Xác định dấu của Q: vật nhận nhiệt thì Q > 0, tỏa nhiệt thì Q < 0.","Xác định dấu của A: vật nhận công thì A > 0, sinh công thì A < 0.","Áp dụng ΔU = A + Q.","Kết luận nội năng tăng (ΔU > 0) hay giảm (ΔU < 0)."],"n":["Chú ý dấu: khí sinh công cho môi trường thì A âm.","Đơn vị đều là jun (J).","Quá trình đẳng tích: A = 0 nên ΔU = Q."]}],"sum":["Nội năng U là tổng động năng và thế năng của các phân tử. Định luật I: ΔU = A + Q. Quy ước dấu: nhận vào thì dương (Q > 0, A > 0), toả ra hoặc sinh công thì âm (Q < 0, A < 0).","Nội năng: Nội năng U của vật là tổng động năng và thế năng của các phân tử cấu tạo nên vật.","Hai cách làm thay đổi nội năng: Thực hiện công (A).","Định luật I của nhiệt động lực học: Là sự vận dụng định luật bảo toàn năng lượng vào các quá trình thay đổi nội năng.","Quy ước dấu"],"d":["Áp dụng định luật I nhiệt động lực học"],"e":["Sai: Vật toả nhiệt thì Q > 0. → Đúng: Vật toả nhiệt thì Q < 0; vật sinh công thì A < 0.","Hay nhầm: Đây là cơ năng của vật, không phải nội năng.","Hay nhầm: Nhiệt lượng là phần năng lượng được truyền đi, không phải nội năng.","Hay nhầm: Công là số đo quá trình truyền năng lượng, không phải dạng năng lượng dự trữ.","Hay nhầm: J/kg là đơn vị của nhiệt hoá hơi, nóng chảy riêng.","Hay nhầm: J/(kg·K) là đơn vị của nhiệt dung riêng."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 3. Nhiệt độ. Thang nhiệt độ - nhiệt kế","sum":["Nhiệt truyền từ vật nóng sang vật lạnh; bằng nhau là cân bằng nhiệt. Đổi: T(K) = t(°C) + 273 (chính xác 273,15); t(°F) = 32 + 1,8·t(°C). Nhiệt độ đặc trưng cho động năng trung bình của phân tử.","Nhiệt độ và cân bằng nhiệt: Hai vật khác nhiệt độ tiếp xúc: nhiệt năng truyền từ vật có nhiệt độ cao sang vật có nhiệt độ thấp.","Thang Celsius: 0 °C: nhiệt độ đóng băng của nước tinh khiết.","Thang Kelvin: 0 K là độ không tuyệt đối, tương ứng −273,15 °C.","Đổi giữa các thang","Nhiệt độ và nhiệt kế: Nhiệt độ đặc trưng cho động năng trung bình của chuyển động nhiệt của phân tử: nhiệt độ càng cao thì động năng trung bình càng lớn."],"e":["Hay nhầm: Chiều này ngược lại với quy luật truyền nhiệt.","Hay nhầm: Khối lượng không quyết định chiều truyền nhiệt.","Hay nhầm: Chiều truyền nhiệt luôn xác định được theo nhiệt độ.","Hay nhầm: Nội năng không quyết định chiều truyền nhiệt.","Hay nhầm: Khối lượng cũng không quyết định chiều truyền nhiệt.","Hay nhầm: Khi nhiệt độ bằng nhau, nhiệt năng không truyền."],"q":{"n":12,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":1}}},{"t":"Bài 4. Nhiệt dung riêng","m":[{"t":"Tính nhiệt lượng và bài toán cân bằng nhiệt","w":"Đề cho khối lượng, nhiệt dung riêng, độ tăng nhiệt độ và hỏi nhiệt lượng; hoặc trộn hai vật và hỏi nhiệt độ cuối.","s":["Đổi đơn vị: m (kg), c (J/kg·K), ΔT (K hay °C, độ chênh bằng nhau).","Nhiệt lượng Q = m·c·ΔT.","Cân bằng nhiệt: nhiệt tỏa ra = nhiệt thu vào, m₁c₁(t₁ − t) = m₂c₂(t − t₂).","Giải phương trình tìm nhiệt độ cuối t, kiểm tra t nằm giữa hai nhiệt độ đầu."],"n":["ΔT luôn là hiệu hai nhiệt độ, dương khi tính độ lớn nhiệt lượng.","Chất cùng loại thì c giản ước hai vế.","Kết quả t phải nằm giữa t₂ và t₁."]}],"sum":["Nhiệt lượng làm nóng: Q = m·c·ΔT, c là nhiệt dung riêng, đơn vị J/(kg·K). c càng lớn thì vật nóng lên càng chậm. Nước có c lớn (4200) nên dùng làm chất tải nhiệt, làm mát.","Nhiệt lượng làm nóng vật: Q tỉ lệ thuận với khối lượng m và độ tăng nhiệt độ ΔT.","Nhiệt dung riêng của một chất: Là nhiệt lượng cần truyền cho 1 kg chất đó để nhiệt độ tăng thêm 1 °C (hoặc 1 K).","Ứng dụng của nước: Nước có c lớn, hấp thụ nhiều nhiệt mà nhiệt độ tăng ít, nên dùng làm chất tải nhiệt trong hệ thống làm mát.","Đo nhiệt dung riêng của nước: Đo khối lượng nước m, độ tăng nhiệt độ Δt và nhiệt lượng Q do dòng điện qua điện trở toả ra trong thời gian đun τ."],"d":["Tính nhiệt lượng và bài toán cân bằng nhiệt"],"e":["Sai: Chất có c lớn thì nóng lên nhanh. → Đúng: Chất có c lớn cần nhiều nhiệt hơn để tăng cùng độ nhiệt nên nóng lên chậm hơn.","Hay nhầm: Đây là định nghĩa nhiệt nóng chảy riêng.","Hay nhầm: Đây là định nghĩa nhiệt đông đặc, không phải nhiệt dung riêng.","Hay nhầm: Nhiệt dung riêng không gắn với mốc 100 °C.","Hay nhầm: J/kg là đơn vị của nhiệt hoá hơi và nóng chảy riêng.","Hay nhầm: Nước dẫn nhiệt tốt hơn nhiều chất lỏng khác."],"q":{"n":14,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":5}}},{"t":"Bài 5. Nhiệt nóng chảy riêng","m":[{"t":"Tính nhiệt lượng làm nóng chảy và quá trình nhiều giai đoạn","w":"Đề cho khối lượng vật và nhiệt nóng chảy riêng, hỏi nhiệt lượng để vật nóng chảy hoàn toàn; hoặc đun từ nhiệt độ thấp đến khi chảy hết.","s":["Chia quá trình thành các giai đoạn: nóng lên đến nhiệt độ nóng chảy (Q₁ = mcΔT), nóng chảy ở nhiệt độ không đổi (Q₂ = λm).","Tính từng nhiệt lượng với đơn vị J.","Cộng các nhiệt lượng: Q = Q₁ + Q₂ (+ ...).","Kiểm tra: nếu chỉ cung cấp một nhiệt lượng cho trước thì so sánh với từng giai đoạn."],"n":["Trong lúc nóng chảy nhiệt độ không đổi, không dùng mcΔT.","Đá ở 0 °C chỉ cần Q = λm; đá dưới 0 °C cần nâng lên 0 °C trước.","Nhớ λ của nước đá là 3,34·10⁵ J/kg."]}],"sum":["Nhiệt lượng làm nóng chảy hoàn toàn: Q = λ·m, λ là nhiệt nóng chảy riêng (J/kg). Khi nóng chảy nhiệt độ không đổi: nhiệt nhận vào làm tăng thế năng phân tử, không làm tăng động năng.","Nhiệt lượng làm nóng chảy: Q là nhiệt lượng từ lúc vật bắt đầu nóng chảy đến khi nóng chảy hoàn toàn.","Nhiệt nóng chảy riêng của một số chất: Là nhiệt lượng làm 1 kg chất nóng chảy hoàn toàn ở nhiệt độ nóng chảy.","Trong lúc nóng chảy: Nhiệt độ không đổi nhưng vật vẫn nhận nhiệt.","Ứng dụng: Đúc kim loại."],"d":["Tính nhiệt lượng làm nóng chảy và quá trình nhiều giai đoạn"],"e":["Sai: Vật nhận nhiệt thì nhiệt độ luôn tăng. → Đúng: Khi đang nóng chảy, vật nhận nhiệt nhưng nhiệt độ giữ nguyên (đoạn nằm ngang trên đồ thị).","Hay nhầm: Đây là định nghĩa nhiệt dung riêng.","Hay nhầm: Đây là định nghĩa nhiệt hoá hơi riêng, khác về quá trình.","Hay nhầm: Nhiệt độ nóng chảy là một nhiệt độ, không phải nhiệt lượng.","Hay nhầm: J/(kg·K) là đơn vị của nhiệt dung riêng.","Hay nhầm: Nếu động năng tăng thì nhiệt độ sẽ tăng."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":5}}},{"t":"Bài 6. Nhiệt hoá hơi riêng","m":[{"t":"Tính nhiệt lượng hóa hơi","w":"Đề cho khối lượng chất lỏng, nhiệt hóa hơi riêng và hỏi nhiệt lượng cần để hóa hơi hoặc ngưng tụ; hoặc quá trình đun từ nhiệt độ thấp đến hóa hơi hoàn toàn.","s":["Chia quá trình: đun nóng đến nhiệt độ sôi (Q₁ = mcΔT), hóa hơi ở nhiệt độ không đổi (Q₂ = Lm).","Tính từng nhiệt lượng với m (kg), c (J/kg·K), L (J/kg).","Cộng lại: Q = Q₁ + Q₂.","Ngưng tụ hoàn toàn thì tỏa nhiệt lượng đúng bằng Lm."],"n":["Nhiệt độ không đổi trong lúc hóa hơi, không dùng mcΔT cho giai đoạn này.","Nhiệt hóa hơi riêng của nước ở 100 °C là 2,3·10⁶ J/kg.","Nước bắt đầu sôi ở 100 °C (áp suất chuẩn)."]}],"sum":["Nhiệt lượng làm hoá hơi: Q = L·m, L là nhiệt hoá hơi riêng (J/kg). Khi sôi nhiệt độ không đổi. λ và L gọi là ẩn nhiệt riêng. Ứng dụng: máy điều hoà, nồi hấp tiệt trùng.","Nhiệt lượng làm hoá hơi: Nhiệt lượng cung cấp cho chất lỏng hoá hơi ở nhiệt độ không đổi tỉ lệ thuận với khối lượng.","Nhiệt hoá hơi riêng của một số chất: Là nhiệt lượng làm 1 kg chất lỏng hoá hơi hoàn toàn ở một nhiệt độ xác định (bảng dưới: ở nhiệt độ sôi, áp suất tiêu chuẩn).","Ẩn nhiệt riêng: Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng gọi chung là ẩn nhiệt riêng.","Ứng dụng: Thiết bị làm lạnh như máy điều hoà."],"d":["Tính nhiệt lượng hóa hơi"],"e":["Hay nhầm: Đây là định nghĩa nhiệt dung riêng.","Hay nhầm: Đây là định nghĩa nhiệt đông đặc, ngược chiều với hoá hơi.","Hay nhầm: Nhiệt độ sôi là một nhiệt độ, không phải nhiệt lượng.","Hay nhầm: J/(kg·K) là đơn vị nhiệt dung riêng.","Hay nhầm: Khi sôi, nước thu nhiệt chứ không toả nhiệt.","Hay nhầm: Đây là nhiệt dung riêng, không phải nhiệt hoá hơi riêng."],"q":{"n":12,"lv":{"Biết":4,"Hiểu":3,"Vận dụng":5}}},{"t":"Bài 7. Bài tập về vật lí nhiệt","sum":["Bốn công thức: ΔU = A + Q; Q = m·c·ΔT; Q = λ·m; Q = L·m. Khi các vật chỉ trao đổi nhiệt với nhau: Q_toả = Q_thu. Chia bài làm giai đoạn: đổi nhiệt độ dùng c, đổi thể dùng λ hoặc L.","Công thức cần nhớ","Phương trình cân bằng nhiệt: Khi các vật chỉ truyền nhiệt cho nhau, không truyền ra ngoài:","Khi có cả công và nhiệt: Nội năng thay đổi đồng thời do thực hiện công và truyền nhiệt: dùng ΔU = A + Q."],"e":["Sai: Dùng cân bằng nhiệt cả khi có nhiệt mất ra môi trường. → Đúng: Phải chắc hệ cô lập về nhiệt; nếu có mất nhiệt thì Q_toả > Q_thu.","Hay nhầm: Đây là quy ước ngược lại với sách giáo khoa.","Hay nhầm: Đây là quy ước sai ở cả hai đại lượng.","Hay nhầm: A và Q có thể âm khi vật thực hiện công hoặc truyền nhiệt.","Hay nhầm: Đã bỏ dấu âm của công khi vật thực hiện công.","Hay nhầm: Đã đảo dấu, coi vật nhận công 300 J và truyền nhiệt 800 J."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":4}}}]},{"t":"Chương II. Khí lí tưởng","l":[{"t":"Bài 8. Mô hình động học phân tử chất khí","sum":["Mô hình động học phân tử chất khí: phân tử rất nhỏ so với khoảng cách giữa chúng; chuyển động hỗn loạn không ngừng; va chạm với thành bình gây áp suất. Khí lí tưởng: phân tử là chất điểm, va chạm…","Chuyển động Brown trong chất khí: Chuyển động Brown cũng xảy ra trong chất khí: phân tử khí chuyển động hỗn loạn, không ngừng.","Tốc độ phân tử mang tính thống kê: Trong khối khí có phân tử nhanh hơn, chậm hơn hoặc bằng tốc độ trung bình.","Ba nội dung của mô hình: (1) Kích thước phân tử rất nhỏ so với khoảng cách giữa chúng.","Khí lí tưởng: Là mô hình đơn giản hoá: phân tử là chất điểm."],"e":["Sai: Mọi phân tử khí có cùng một tốc độ. → Đúng: Các phân tử có tốc độ khác nhau; chỉ nói về tốc độ trung bình của cả khối khí.","Hay nhầm: Đây là nội dung đúng của mô hình: các phân tử chuyển động hỗn loạn, không ngừng.","Hay nhầm: Đây là nội dung đúng của mô hình: kích thước phân tử rất nhỏ so với khoảng cách.","Hay nhầm: Đây là nội dung đúng của mô hình: va chạm với thành bình gây áp suất.","Hay nhầm: Nếu phân tử đứng yên thì hạt khói không thể chuyển động.","Hay nhầm: Chuyển động Brown cho thấy cấu tạo gián đoạn."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":1}}},{"t":"Bài 9. Định luật Boyle","m":[{"t":"Bài toán quá trình đẳng nhiệt","w":"Đề cho khí biến đổi ở nhiệt độ không đổi, cho hai trong bốn giá trị p₁, V₁, p₂, V₂ và hỏi giá trị còn lại.","s":["Xác định nhiệt độ không đổi: đẳng nhiệt.","Viết p₁V₁ = p₂V₂.","Giải tìm đại lượng chưa biết; thống nhất đơn vị áp suất và thể tích hai bên.","Kiểm tra chiều biến đổi: p tăng thì V giảm."],"n":["Đơn vị áp suất ở hai vế phải giống nhau (atm, Pa...).","Nén khí thì thể tích giảm, áp suất tăng.","Đẳng nhiệt không cần đổi sang kelvin."]}],"sum":["Định luật Boyle (đẳng nhiệt): T không đổi thì p·V = hằng số, tức p₁V₁ = p₂V₂. Đồ thị p–V là nhánh hypebol; nhiệt độ cao hơn thì đường nằm xa gốc hơn.","Thông số trạng thái: Một lượng khí xác định được đặc trưng bởi ba thông số: thể tích V, áp suất p, nhiệt độ T.","Quá trình đẳng nhiệt: Biến đổi trạng thái của một khối lượng khí xác định khi nhiệt độ giữ không đổi.","Định luật Boyle: Nhiệt độ của một khối lượng khí xác định không đổi thì áp suất tỉ lệ nghịch với thể tích:","Đồ thị p–V: Trong hệ toạ độ (p, V) là một nhánh của đường hypebol."],"d":["Bài toán quá trình đẳng nhiệt"],"e":["Sai: Đường đẳng nhiệt ứng với nhiệt độ cao hơn nằm gần gốc toạ độ hơn. → Đúng: Nhiệt độ cao hơn thì đường nằm xa gốc toạ độ hơn.","Hay nhầm: Vận tốc không phải thông số trạng thái của khí.","Hay nhầm: Khối lượng riêng là hệ quả, không phải thông số trạng thái cơ bản đi kèm.","Hay nhầm: Cần cả ba thông số, không chỉ nhiệt độ.","Hay nhầm: Đó là quá trình đẳng tích.","Hay nhầm: Đó là quá trình đoạn nhiệt, không phải đẳng nhiệt."],"q":{"n":13,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":5}}},{"t":"Bài 10. Định luật Charles","m":[{"t":"Bài toán quá trình đẳng áp","w":"Đề cho khí biến đổi ở áp suất không đổi, cho nhiệt độ theo °C hoặc K và hỏi thể tích hay nhiệt độ.","s":["Đổi nhiệt độ sang kelvin: T = t + 273.","Viết V₁/T₁ = V₂/T₂.","Giải tìm đại lượng chưa biết.","Kiểm tra: nhiệt độ tăng thì thể tích tăng."],"n":["Phải dùng nhiệt độ tuyệt đối (K), không dùng °C.","T tăng gấp đôi thì V tăng gấp đôi.","Áp suất và khối lượng khí không đổi."]}],"sum":["Định luật Charles (đẳng áp): p không đổi thì V/T = hằng số, V₁/T₁ = V₂/T₂, với T là nhiệt độ Kelvin. Đồ thị V–T là đường thẳng qua gốc toạ độ; −273 °C là độ không tuyệt đối, không thể đạt tới.","Quá trình đẳng áp: Biến đổi trạng thái của một khối lượng khí xác định khi áp suất giữ không đổi.","Thí nghiệm của Charles: Áp suất không đổi: thể tích khí tăng thêm V₀/273 cho mỗi 1 °C tăng nhiệt độ.","Định luật Charles: Áp suất không đổi thì thể tích khí tỉ lệ thuận với nhiệt độ tuyệt đối:","Đồ thị V–T: Dùng nhiệt độ Kelvin: đường thẳng đi qua gốc toạ độ."],"d":["Bài toán quá trình đẳng áp"],"e":["Sai: Thay nhiệt độ Celsius trực tiếp vào V₁/T₁ = V₂/T₂. → Đúng: T phải là nhiệt độ Kelvin: T = t + 273.","Hay nhầm: Đó là quá trình đẳng tích.","Hay nhầm: Đó là quá trình đẳng nhiệt.","Hay nhầm: Khối lượng không đổi không đặc trưng cho đẳng áp.","Hay nhầm: V không tỉ lệ thuận với t Celsius vì có điểm gốc khác.","Hay nhầm: Áp suất không đổi nên không thể là đại lượng biến thiên."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":5}}},{"t":"Bài 11. Phương trình trạng thái của khí lí tưởng","m":[{"t":"Bài toán dùng phương trình trạng thái khí lí tưởng","w":"Đề cho khí biến đổi cả p, V, T (không đẳng quá trình) và hỏi một trong các đại lượng.","s":["Liệt kê trạng thái 1 (p₁, V₁, T₁) và trạng thái 2 (p₂, V₂, T₂), đổi T sang kelvin.","Viết p₁V₁/T₁ = p₂V₂/T₂.","Giải tìm đại lượng chưa biết.","Đối chiếu với trường hợp riêng: T không đổi (Boyle), p không đổi (Charles), V không đổi (p/T không đổi)."],"n":["Nhiệt độ luôn dùng kelvin.","Áp suất, thể tích ở hai vế cùng đơn vị.","Biến đổi đẳng tích: p₁/T₁ = p₂/T₂."]}],"sum":["Phương trình trạng thái: p₁V₁/T₁ = p₂V₂/T₂, tức pV/T = hằng số. Clapeyron: pV = nRT với R = 8,31 J/(mol·K), n = m/M. Điều kiện tiêu chuẩn: 1 mol có V = 22,4 L, p = 1,013·10⁵ Pa, T = 273 K.","Vì sao cần phương trình trạng thái: Định luật Boyle và Charles chỉ cho mối liên hệ giữa hai thông số.","Phương trình trạng thái khí lí tưởng: Độ lớn của hằng số phụ thuộc vào lượng khí đang xét.","Phương trình Clapeyron: Với n mol khí lí tưởng:","Điều kiện tiêu chuẩn"],"d":["Bài toán dùng phương trình trạng thái khí lí tưởng"],"e":["Sai: Dùng áp suất theo atm, thể tích theo L mà vẫn lấy R = 8,31. → Đúng: R = 8,31 J/(mol·K) dùng với p (Pa), V (m³), T (K).","Hay nhầm: Đây không phải tổ hợp đúng của các thông số.","Hay nhầm: Đây không phải tổ hợp đúng của các thông số.","Hay nhầm: Phương trình không có dạng cộng.","Hay nhầm: Cùng một trạng thái đầu và cuối, cách chuyển khác nhau cho cùng kết quả.","Hay nhầm: Màu sắc bình không ảnh hưởng."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":5}}},{"t":"Bài 12. Áp suất khí theo mô hình động học phân tử. Quan hệ giữa động năng phân tử và nhiệt độ","sum":["Áp suất khí: p = (1/3)·n·m·v̅² = (2/3)·n·Ē_đ. Động năng tịnh tiến trung bình: Ē_đ = (3/2)·k·T, tỉ lệ với nhiệt độ tuyệt đối, k = 1,38·10⁻²³ J/K. Khí khác nhau, cùng nhiệt độ thì Ē_đ bằng nhau.","Áp suất do va chạm: Mỗi phân tử va chạm đàn hồi với thành bình, truyền cho thành bình xung lượng 2mv.","Công thức áp suất khí: n: mật độ phân tử (số phân tử trong một đơn vị thể tích).","Động năng phân tử và nhiệt độ: Ē_đ tỉ lệ thuận với nhiệt độ tuyệt đối: nhiệt độ tuyệt đối là số đo động năng trung bình của phân tử.","Tốc độ căn quân phương: Là căn bậc hai của trung bình bình phương tốc độ."],"e":["Sai: Tốc độ căn quân phương bằng tốc độ trung bình của phân tử. → Đúng: Hai đại lượng khác nhau: tốc độ căn quân phương lớn hơn tốc độ trung bình một chút.","Hay nhầm: Khối lượng bình không đi vào công thức áp suất.","Hay nhầm: Vị trí bình không ảnh hưởng.","Hay nhầm: Nhiệt độ Celsius không tỉ lệ thuận với động năng vì có điểm gốc khác.","Hay nhầm: Thể tích không quyết định trực tiếp động năng.","Hay nhầm: Áp suất không quyết định trực tiếp động năng."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 13. Bài tập về khí lí tưởng","sum":["Giải bài khí lí tưởng: xác định lượng khí có đổi không, trạng thái đầu – cuối, quá trình; ghi p, V, T (đổi sang Kelvin), n. Đẳng nhiệt: p₁V₁ = p₂V₂; đẳng áp: V₁/T₁ = V₂/T₂; đẳng tích: p₁/T₁ = p₂/T₂.","Các bước giải: Xác định lượng khí có thay đổi hay không.","Công thức theo từng quá trình","Khi lượng khí thay đổi: Ví dụ lấy bớt khí khỏi bình: dùng phương trình Clapeyron với số mol n thay đổi.","Tính số mol ở điều kiện tiêu chuẩn"],"e":["Hay nhầm: Áp suất giảm khi nhiệt độ giảm, không phải khi tăng.","Hay nhầm: Áp suất thay đổi khi nhiệt độ thay đổi ở thể tích không đổi.","Hay nhầm: Áp suất không bằng 0 khi khí còn trong bình.","Hay nhầm: Hypebol là đồ thị của đẳng nhiệt trong hệ (p, V).","Hay nhầm: Đường nằm ngang là đồ thị của đẳng áp trong hệ (V, T).","Hay nhầm: Đường thẳng song song trục T là không đổi p, không đúng."],"q":{"n":8,"lv":{"Hiểu":4,"Biết":1,"Vận dụng":3}}}]},{"t":"Chương III. Từ trường","l":[{"t":"Bài 14. Từ trường","sum":["Từ trường do dòng điện hoặc nam châm gây ra, tác dụng lực từ. Cảm ứng từ B là vectơ đặc trưng cho từ trường. Đường sức từ là đường cong khép kín, chỗ mạnh vẽ dày hơn. Chiều đường sức của dòng điện…","Tương tác từ: Nam châm với nam châm, dòng điện với nam châm, dòng điện với dòng điện đều có tương tác từ; lực tương tác gọi là lực từ.","Từ trường: Trường lực gây ra bởi dòng điện hoặc nam châm.","Cảm ứng từ B: Phương của B: phương của nam châm thử cân bằng tại điểm đó.","Đường sức từ: Tại mỗi điểm chỉ vẽ được một đường sức từ.","Quy tắc nắm bàn tay phải: Ngón cái hướng theo chiều dòng điện."],"e":["Hay nhầm: Tương tác điện là tương tác giữa các điện tích.","Hay nhầm: Tương tác hấp dẫn là tương tác giữa các vật có khối lượng.","Hay nhầm: Tương tác yếu là tương tác trong hạt nhân.","Hay nhầm: Trọng trường là của các vật có khối lượng.","Hay nhầm: Trường hấp dẫn là của các vật có khối lượng.","Hay nhầm: Điện trường là của điện tích, không phải đặc trưng của dòng điện thẳng và nam châm."],"q":{"n":11,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":1}}},{"t":"Bài 15. Lực từ tác dụng lên dây dẫn mang dòng điện. Cảm ứng từ","m":[{"t":"Tính lực từ lên đoạn dây dẫn mang dòng điện","w":"Đề cho cảm ứng từ B, cường độ dòng điện I, chiều dài L, góc α và hỏi độ lớn lực từ, hoặc tìm B, I.","s":["Xác định B (T), I (A), L (m), góc α giữa dây dẫn và vectơ cảm ứng từ.","Áp dụng F = B·I·L·sinα.","Với α = 90° thì F = BIL; α = 0° thì F = 0.","Chiều lực từ theo quy tắc bàn tay trái."],"n":["Đổi chiều dài về mét.","Góc α là góc giữa dây và đường sức từ, không phải giữa dây và mặt phẳng.","Dây song song đường sức từ thì không chịu lực từ."]}],"sum":["Lực từ lên dây dẫn: F = B·I·L·sinα (định luật Ampe), α là góc giữa dây và B; F vuông góc với dây và với B, chiều theo quy tắc bàn tay trái. Đơn vị cảm ứng từ tesla: 1 T = 1 N/(A·m).","Lực từ lên đoạn dây mang dòng điện: Đoạn dây dẫn có dòng điện I đặt trong từ trường chịu lực từ F.","Quy tắc bàn tay trái: Vectơ B hướng vào lòng bàn tay.","Công thức Ampe: B: cảm ứng từ; I: cường độ dòng điện; L: chiều dài đoạn dây.","Đơn vị cảm ứng từ: tesla: 1 tesla là cảm ứng từ của từ trường đều mà dòng điện 1 A vuông góc với đường sức chịu lực 1 N trên mỗi mét dây."],"d":["Tính lực từ lên đoạn dây dẫn mang dòng điện"],"e":["Sai: α là góc giữa B và lực từ F. → Đúng: α là góc giữa dây dẫn và B. Dây song song B (α = 0) thì F = 0; dây vuông góc B thì F lớn nhất.","Hay nhầm: Lực từ không trùng với chiều dòng điện.","Hay nhầm: Lực từ không song song với đoạn dây.","Hay nhầm: Lực từ không song song với B.","Hay nhầm: Đường sức từ không được chỉ bởi ngón cái.","Hay nhầm: Chiều B là hướng vào lòng bàn tay."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":5}}},{"t":"Bài 16. Từ thông. Hiện tượng cảm ứng điện từ","m":[{"t":"Tính từ thông và suất điện động cảm ứng","w":"Đề cho B, S, góc α hoặc số vòng N, độ biến thiên từ thông và thời gian, hỏi từ thông hoặc suất điện động.","s":["Từ thông Φ = B·S·cosα (α là góc giữa vectơ pháp tuyến mặt phẳng và B).","Tính độ biến thiên ΔΦ = Φ₂ − Φ₁.","Suất điện động |e| = N·|ΔΦ/Δt|.","Cường độ dòng điện cảm ứng (nếu mạch kín): i = e/R."],"n":["α là góc giữa pháp tuyến và B, không phải giữa mặt phẳng và B.","Đổi diện tích về m², thời gian về giây.","N là số vòng dây của cuộn."]}],"sum":["Từ thông Φ = B·S·cosα (α giữa pháp tuyến và B), đơn vị Wb. Từ thông biến thiên thì có dòng điện cảm ứng; chiều theo định luật Lenz (chống lại sự biến thiên); độ lớn suất điện động theo Faraday: |e|…","Từ thông: α: góc giữa vectơ pháp tuyến của S và B.","Hiện tượng cảm ứng điện từ: Từ thông qua cuộn dây kín biến thiên thì trong cuộn dây xuất hiện dòng điện cảm ứng.","Định luật Lenz: Dòng điện cảm ứng có chiều sao cho từ trường do nó sinh ra chống lại sự biến thiên của từ thông ban đầu qua mạch kín.","Định luật Faraday"],"d":["Tính từ thông và suất điện động cảm ứng"],"e":["Sai: α là góc giữa mặt phẳng khung và B. → Đúng: α là góc giữa pháp tuyến của khung và B. Khung vuông góc đường sức thì pháp tuyến song song B, α = 0, Φ lớn…","Hay nhầm: Tesla là đơn vị cảm ứng từ.","Hay nhầm: Ampe là đơn vị cường độ dòng điện.","Hay nhầm: Khi α = 0°, cosα = 1 nên Φ = BS > 0.","Hay nhầm: Từ thông phụ thuộc vào góc α, không phải chuyển động bất kì.","Hay nhầm: B khác 0 thì Φ có thể khác 0."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 17. Máy phát điện xoay chiều","m":[{"t":"Tính suất điện động cực đại, chu kì, tần số của máy phát điện","w":"Đề cho N, B, S, tốc độ góc ω (hoặc tần số quay) và hỏi E₀, chu kì T, tần số f.","s":["Đổi đơn vị: B (T), S (m²), ω (rad/s).","E₀ = N·B·S·ω.","Chu kì T = 2π/ω; tần số f = ω/(2π) = 1/T.","Nếu cho vòng/phút: ω = 2π·n/60."],"n":["ω tính bằng rad/s, không phải vòng/phút.","Tần số dòng điện xoay chiều chuẩn là 50 Hz.","T và f nghịch đảo nhau."]}],"sum":["Khung quay đều trong từ trường: e = E₀·cos(ωt + φ₀) với E₀ = N·B·S·ω. T = 2π/ω, f = ω/(2π). Giá trị hiệu dụng: I = I₀/√2, U = U₀/√2. Máy phát gồm phần cảm (tạo từ trường) và phần ứng (sinh suất điện…","Suất điện động xoay chiều: Khung dây quay đều với tốc độ góc ω trong từ trường đều B: từ thông biến thiên điều hoà, trong khung có suất điện động xoay chiều.","Chu kì và tần số","Giá trị hiệu dụng: Dòng điện xoay chiều có cường độ biến thiên điều hoà: i = I₀cos(ωt + φ).","Cấu tạo máy phát điện xoay chiều: Phần cảm: tạo ra từ trường."],"d":["Tính suất điện động cực đại, chu kì, tần số của máy phát điện"],"e":["Sai: Giá trị hiệu dụng bằng giá trị cực đại. → Đúng: Hiệu dụng nhỏ hơn cực đại √2 lần: I = I₀/√2.","Hay nhầm: Hiện tượng nhiệt điện không liên quan.","Hay nhầm: Hiện tượng phóng xạ không tạo dòng điện xoay chiều.","Hay nhầm: Hiện tượng quang điện không tạo suất điện động xoay chiều trong khung.","Hay nhầm: Chia cho ω làm sai thứ nguyên.","Hay nhầm: E₀ tỉ lệ thuận với N, B, S và ω, không tỉ lệ nghịch."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 18. Ứng dụng hiện tượng cảm ứng điện từ","sum":["Máy biến áp (hai cuộn trên lõi kín) hoạt động nhờ cảm ứng điện từ: U₁/U₂ = N₁/N₂. Lõi ghép bằng lá thép silicon mỏng để giảm dòng Foucault. Dòng Foucault được dùng trong bếp từ và phanh điện từ.","Máy biến áp: Gồm hai cuộn dây có số vòng khác nhau quấn trên lõi kín.","Công thức máy biến áp","Lõi biến áp: Ghép từ các lá thép silicon mỏng, cách điện với nhau.","Dòng điện Foucault: Ứng dụng: bếp từ, phanh điện từ.","Đàn ghi ta điện: Cuộn dây cảm ứng đặt dưới dây thép."],"e":["Hay nhầm: Phóng xạ không liên quan.","Hay nhầm: Hiện tượng quang điện không dùng trong máy biến áp.","Hay nhầm: Hiện tượng nhiệt điện không dùng trong máy biến áp.","Hay nhầm: Số vòng không quyết định tên gọi sơ cấp.","Hay nhầm: Lõi thép là đặc điểm chung, không phải định nghĩa.","Hay nhầm: Điện trở cuộn dây không được tăng bằng cách này."],"q":{"n":10,"lv":{"Biết":2,"Vận dụng":3,"Hiểu":5}}},{"t":"Bài 19. Điện từ trường. Mô hình sóng điện từ","sum":["Từ trường biến thiên sinh điện trường xoáy; điện trường biến thiên sinh từ trường. Sóng điện từ là sóng ngang, truyền được trong chân không, E và B đồng pha, vuông góc nhau và với phương truyền.…","Điện trường xoáy: Từ trường biến thiên theo thời gian sinh ra điện trường xoáy.","Từ trường do điện trường biến thiên: Điện trường biến thiên theo thời gian sinh ra từ trường biến thiên.","Điện từ trường: Điện trường biến thiên và từ trường biến thiên cùng tồn tại, chuyển hoá lẫn nhau, tạo thành điện từ trường thống nhất.","Sóng điện từ: Là sóng ngang; truyền được trong chân không.","Bước sóng: c là tốc độ ánh sáng trong chân không (≈ 3·10⁸ m/s); sóng điện từ truyền với tốc độ đó."],"e":["Sai: Sóng điện từ là sóng dọc và cần môi trường truyền. → Đúng: Sóng điện từ là sóng ngang và truyền được cả trong chân không.","Hay nhầm: Dòng điện không đổi không tạo điện trường xoáy.","Hay nhầm: Nam châm đứng yên không sinh điện trường xoáy.","Hay nhầm: Điện tích đứng yên tạo điện trường tĩnh, không phải điện trường xoáy.","Hay nhầm: Đây là đặc điểm của điện trường tĩnh.","Hay nhầm: Đây là đặc điểm của điện trường tĩnh."],"q":{"n":11,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":1}}},{"t":"Bài 20. Bài tập về từ trường","sum":["Bốn công thức chính: F = B·I·L·sinα; Φ = B·S·cosα; E₀ = N·B·S·ω; U₁/U₂ = N₁/N₂. Bài định tính: xác định phương chiều của B, lực từ, dòng cảm ứng. Bài định lượng: chọn đúng công thức theo hiện tượng.","Phần từ trường gồm: Mô tả từ trường.","Công thức theo hiện tượng","Mẹo giải: Bài định tính: xác định phương và chiều của B, của lực từ và của dòng điện cảm ứng (quy tắc bàn tay, định luật Lenz)."],"e":["Hay nhầm: Dòng cảm ứng không làm tăng biến thiên từ thông.","Hay nhầm: Từ thông không bằng 0 ngay lập tức.","Hay nhầm: Dòng cảm ứng luôn có tác dụng theo định luật Lenz.","Hay nhầm: Nhiệt độ không phải đại lượng đo trực tiếp.","Hay nhầm: Thời gian đo không liên quan.","Hay nhầm: Điện áp nguồn không quyết định trực tiếp lực từ đo được."],"q":{"n":8,"lv":{"Vận dụng":5,"Biết":2,"Hiểu":1}}}]},{"t":"Chương IV. Vật lí hạt nhân","l":[{"t":"Bài 21. Cấu trúc hạt nhân","m":[{"t":"Xác định cấu tạo hạt nhân","w":"Đề cho kí hiệu hạt nhân ᴬ_Z X và hỏi số proton, neutron, số nucleon, hoặc so sánh các hạt nhân.","s":["Đọc kí hiệu ᴬ_Z X: A là số khối (số nucleon), Z là số proton.","Số proton = Z; số neutron N = A − Z.","Số electron của nguyên tử trung hòa bằng Z.","Đồng vị: cùng Z, khác A."],"n":["A viết ở góc trên, Z ở góc dưới.","Số nucleon bằng tổng proton và neutron.","Đồng vị có cùng số proton, khác số neutron."]}],"sum":["Hạt nhân gồm nucleon: proton (+e) và neutron (không mang điện). Kí hiệu ᴬ_Z X: A là số khối, Z là số proton, N = A − Z. Đồng vị: cùng Z, khác N. Bán kính R ≈ 1,2·10⁻¹⁵·A^(1/3) m.","Thí nghiệm Rutherford (1911): Phần lớn hạt đi thẳng; một số ít bị lệch; rất ít hạt bật ngược lại.","Nucleon","Kí hiệu hạt nhân: X: kí hiệu hoá học.","Bán kính hạt nhân","Đồng vị: Các hạt nhân có cùng Z nhưng khác N (khác số khối A). Có thể bền hoặc phóng xạ."],"d":["Xác định cấu tạo hạt nhân"],"e":["Sai: Đồng vị là các hạt nhân có cùng số khối A. → Đúng: Đồng vị cùng số proton Z, khác số neutron nên khác A.","Hay nhầm: Electron không rải đều như vậy trong mô hình Rutherford.","Hay nhầm: Hạt nhân nhỏ hơn rất nhiều so với nguyên tử.","Hay nhầm: Nếu nguyên tử đặc đồng nhất thì hạt alpha đã bị lệch nhiều hơn.","Hay nhầm: Electron không đứng yên trong hạt nhân.","Hay nhầm: Electron không nằm trong proton."],"q":{"n":15,"lv":{"Biết":8,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 22. Phản ứng hạt nhân và năng lượng liên kết","m":[{"t":"Viết phương trình phản ứng hạt nhân và tính năng lượng liên kết","w":"Đề cho phản ứng hạt nhân thiếu một hạt, hoặc cho độ hụt khối và hỏi năng lượng liên kết.","s":["Viết phản ứng dưới dạng tổng ᴬ_Z trước = tổng ᴬ_Z sau.","Bảo toàn số khối: tổng A trước = tổng A sau; bảo toàn điện tích: tổng Z trước = tổng Z sau.","Giải tìm A, Z của hạt chưa biết, đối chiếu bảng tuần hoàn để gọi tên hạt nhân.","Năng lượng liên kết E_lk = Δm·c²; với Δm tính bằng u thì E_lk = Δm·931,5 MeV."],"n":["Hạt α là ⁴₂He; β⁻ là ⁰₋₁e; neutron là ¹₀n; proton là ¹₁p.","Bảo toàn cả số khối và điện tích, không bảo toàn khối lượng.","Độ hụt khối luôn dương cho hạt nhân bền."]}],"sum":["Phản ứng hạt nhân bảo toàn số khối A và điện tích Z. Năng lượng liên kết E_lk = Δm·c²; E_lk/A càng lớn thì hạt nhân càng bền. Phân hạch: hạt nhân nặng vỡ thành hai hạt nhẹ (~200 MeV). Tổng hợp: hạt…","Phản ứng hạt nhân: Quá trình biến đổi hạt nhân này thành hạt nhân khác.","Phản ứng tự phát và kích thích: Tự phát: hạt nhân không bền phân rã thành hạt nhân mới (ví dụ phân rã alpha của ²³⁸₉₂U).","Năng lượng liên kết: Năng lượng liên kết riêng E_lk/A càng lớn thì hạt nhân càng bền vững.","Phản ứng phân hạch: Hạt nhân nặng (như ²³⁵U) hấp thụ neutron, vỡ thành hai hạt nhân nhẹ hơn.","Phản ứng tổng hợp hạt nhân: Hai hay nhiều hạt nhân nhẹ hợp lại thành hạt nhân nặng hơn."],"d":["Viết phương trình phản ứng hạt nhân và tính năng lượng liên kết"],"e":["Sai: E_lk càng lớn thì hạt nhân càng bền. → Đúng: Độ bền do năng lượng liên kết riêng E_lk/A quyết định, không phải E_lk.","Hay nhầm: Thay đổi electron là phản ứng hoá học.","Hay nhầm: Thay đổi trạng thái phân tử không phải phản ứng hạt nhân.","Hay nhầm: Trao đổi electron là phản ứng hoá học.","Hay nhầm: Số neutron có thể thay đổi trong phản ứng.","Hay nhầm: Khối lượng nghỉ không bảo toàn tuyệt đối vì có sự chuyển hoá năng lượng."],"q":{"n":19,"lv":{"Biết":4,"Hiểu":8,"Vận dụng":7}}},{"t":"Bài 23. Phóng xạ","m":[{"t":"Bài toán chu kì bán rã","w":"Đề cho chu kì bán rã T, thời gian t, số hạt ban đầu N₀ hoặc khối lượng m₀ và hỏi số hạt còn lại, số hạt đã phân rã, tỉ lệ.","s":["Tính tỉ số t/T = k.","Số hạt còn lại N = N₀·2⁻ᵏ (khi k nguyên: giảm một nửa k lần).","Số hạt đã phân rã = N₀ − N.","Cùng quy luật cho khối lượng chất phóng xạ: m = m₀·2⁻ᵏ."],"n":["t và T phải cùng đơn vị.","Sau mỗi chu kì còn một nửa: 1, 1/2, 1/4, 1/8,...","Phần trăm còn lại sau k chu kì là 100%/2ᵏ."]}],"sum":["Phóng xạ: hạt nhân không bền tự phân rã, phát tia α, β, γ; mang tính ngẫu nhiên. Định luật: N = N₀·2^(−t/T), λ = ln2/T. Độ phóng xạ H = λN, đơn vị Bq.","Hiện tượng phóng xạ: Hạt nhân không bền tự biến đổi thành hạt nhân khác và phát ra tia phóng xạ.","Ba loại tia phóng xạ","Phương trình phân rã","Định luật phóng xạ: Sau mỗi chu kì bán rã T, một nửa số hạt nhân đã phân rã.","Độ phóng xạ: Đơn vị becquerel (Bq): 1 Bq = 1 phân rã/s."],"d":["Bài toán chu kì bán rã"],"e":["Sai: Sau hai chu kì bán rã thì chất phóng xạ phân rã hết. → Đúng: Sau 2T còn lại 1/4, không phải hết; sau mỗi T chỉ giảm một nửa.","Hay nhầm: Đây là hiện tượng quang điện, không phải phóng xạ.","Hay nhầm: Không phải mọi hạt nhân đều phân rã ngay lập tức.","Hay nhầm: Thời điểm phân rã không điều khiển được bằng áp suất.","Hay nhầm: Phóng xạ không phụ thuộc vào nhiệt độ hay áp suất.","Hay nhầm: Tia α bị một tờ giấy chặn lại."],"q":{"n":19,"lv":{"Biết":4,"Hiểu":8,"Vận dụng":7}}},{"t":"Bài 24. Công nghiệp hạt nhân","sum":["Nhà máy điện hạt nhân: lò phản ứng → tua bin → máy phát; thanh điều khiển giữ hệ số nhân k = 1. Ứng dụng trong y học, sinh học, bảo quản thực phẩm. An toàn: giữ khoảng cách, dùng tấm chắn, giảm thời…","Điện hạt nhân: Năng lượng phản ứng hạt nhân chuyển thành điện nhờ lò phản ứng, tua bin và máy phát.","Lò phản ứng: Thanh điều khiển chứa bo hoặc cadimi hấp thụ neutron để giữ hệ số nhân k = 1.","Y học và sinh học: Dược chất phóng xạ để chụp ảnh cắt lớp (PET, SPECT).","An toàn phóng xạ: Giữ khoảng cách đủ xa nguồn.","Liều hiệu dụng: D: liều hấp thụ (Gy); W: trọng số bức xạ; D_hd tính bằng sievert (Sv)."],"e":["Hay nhầm: Nhà máy điện hạt nhân vẫn cần nhiên liệu hạt nhân.","Hay nhầm: Nhà máy điện hạt nhân vẫn tạo chất thải phóng xạ phải xử lí.","Hay nhầm: Nhà máy điện hạt nhân vẫn cần hệ thống làm mát.","Hay nhầm: Thanh điều khiển không làm chậm electron.","Hay nhầm: Thanh điều khiển hấp thụ neutron chứ không tạo thêm.","Hay nhầm: Thanh điều khiển không trực tiếp làm tăng nhiệt độ."],"q":{"n":9,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":1}}},{"t":"Bài 25. Bài tập về vật lí hạt nhân","sum":["Bốn nội dung: cấu trúc hạt nhân, phản ứng hạt nhân, phóng xạ, công nghiệp hạt nhân. Chọn công thức: bảo toàn A, Z khi viết phản ứng; N = N₀·2^(−t/T) và H = λN khi xét phóng xạ.","Chọn công thức theo nội dung","Mẹo giải: Viết phương trình phản ứng: cân bằng số khối và điện tích hai vế."],"e":["Hay nhầm: Lực hấp dẫn không đáng kể giữa các hạt vi mô.","Hay nhầm: Lực hạt nhân chỉ có tác dụng ở khoảng cách rất ngắn, không đẩy hạt alpha ra xa.","Hay nhầm: Electron mang điện âm nên không hút hạt alpha; đây không phải lực chính.","Hay nhầm: 2,65 năm là nửa chu kì bán rã.","Hay nhầm: 6 tháng không phải chu kì bán rã của ⁶⁰Co (5,3 năm).","Hay nhầm: 10,6 năm là hai chu kì bán rã."],"q":{"n":8,"lv":{"Biết":3,"Vận dụng":3,"Hiểu":2}}}]}]}]},{"id":"hoa","name":"Hoá học","b":[{"t":"Hóa học 12","c":[{"t":"Chương 1. Ester – Lipid","l":[{"t":"Bài 1. Ester – Lipid","sum":["Khi thay nhóm –OH trong nhóm carboxyl (–COOH) của carboxylic acid bằng nhóm –OR′ thì được ester.","Khái niệm: Khi thay nhóm –OH trong nhóm carboxyl (–COOH) của carboxylic acid bằng nhóm –OR′ thì được ester.","Danh pháp: Tên gốc R′ + tên gốc acid (đổi đuôi “ic” thành “ate”).","Tính chất vật lí: Các phân tử ester không tạo được liên kết hydrogen với nhau nên nhiệt độ sôi của ester thấp hơn nhiều so với alcohol và carboxylic acid có phân tử…","Tính chất hóa học: Ester bị thủy phân.","Điều chế: Ester thường được điều chế bằng phản ứng ester hóa giữa carboxylic acid và alcohol, xúc tác H₂SO₄ đặc, đun nóng: RCOOH + R′OH ⇌ RCOOR′ + H₂O (thuận…"],"e":["Hay nhầm: Đây là công thức của carboxylic acid.","Hay nhầm: Đây là công thức của ether.","Hay nhầm: Đây là công thức của aldehyde.","Hay nhầm: Gốc alcohol là CH₃– (methyl), không phải ethyl.","Hay nhầm: Gốc acid là HCOO– (formate), không phải acetate.","Hay nhầm: Cả gốc acid và gốc alcohol đều khác."],"q":{"n":16,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 2. Xà phòng và chất giặt rửa","sum":["Xà phòng là hỗn hợp muối sodium hoặc potassium của các acid béo và các chất phụ gia; thành phần chủ yếu thường là sodium palmitate hoặc sodium stearate.","Khái niệm: Xà phòng là hỗn hợp muối sodium hoặc potassium của các acid béo và các chất phụ gia; thành phần chủ yếu thường là sodium palmitate hoặc sodium…","Cấu tạo chung gồm hai phần: Đầu phân cực ưa nước (nhóm carboxylate –COONa của xà phòng, nhóm sulfate –OSO₃Na hoặc sulfonate –SO₃Na của chất giặt rửa tổng hợp) và đuôi không…","Tính chất giặt rửa: Đuôi kị nước thâm nhập vào vết bẩn (dầu mỡ), đầu ưa nước quay ra ngoài; vết bẩn bị chia thành các hạt nhỏ phân tán vào nước và bị rửa trôi.","Sản xuất xà phòng: Đun chất béo với dung dịch NaOH (hoặc KOH) đặc, đó là phản ứng xà phòng hóa.","Chất giặt rửa tổng hợp được sản…: Chất giặt rửa tổng hợp được sản xuất từ dầu mỏ (qua các giai đoạn tạo alkylbenzene, sulfonate hóa, trung hòa) rồi trộn với phụ gia."],"e":["Hay nhầm: Đây là chất giặt rửa tổng hợp.","Hay nhầm: Đó là chất béo, nguyên liệu để làm xà phòng.","Hay nhầm: Đây chỉ là phần đuôi kị nước.","Hay nhầm: Đây là xà phòng (muối của stearic acid).","Hay nhầm: Đây là xà phòng (muối potassium của palmitic acid).","Hay nhầm: Đây là xà phòng (muối của oleic acid)."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}},{"t":"Bài 3. Ôn tập chương 1","e":["Hay nhầm: Gốc alcohol là C₂H₅– (ethyl).","Hay nhầm: Gốc acid là HCOO– (formate).","Hay nhầm: Gốc acid là formate, không phải acetate.","Hay nhầm: Phản ứng xà phòng hóa là một chiều.","Hay nhầm: Phản ứng xà phòng hóa chất béo là một chiều.","Hay nhầm: Phản ứng cộng H₂ xảy ra theo một chiều."],"q":{"n":11,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}}]},{"t":"Chương 2. Carbohydrate","l":[{"t":"Bài 4. Giới thiệu về carbohydrate. Glucose và fructose","sum":["Carbohydrate (saccharide, glucide) là những hợp chất hữu cơ tạp chức, thường có công thức chung Cₙ(H₂O)ₘ.","Khái niệm: Carbohydrate (saccharide, glucide) là những hợp chất hữu cơ tạp chức, thường có công thức chung Cₙ(H₂O)ₘ.","Glucose có công thức phân tử C₆H₁₂O₆…: Glucose có công thức phân tử C₆H₁₂O₆, dạng mạch hở có 5 nhóm hydroxy và 1 nhóm aldehyde: CH₂OH[CHOH]₄CH=O.","Fructose có công thức phân tử C₆H₁₂O₆…: Fructose có công thức phân tử C₆H₁₂O₆, dạng mạch hở có 5 nhóm hydroxy và 1 nhóm ketone: CH₂OH[CHOH]₃COCH₂OH; tồn tại đồng thời dạng mạch hở và mạch…","Tính chất polyalcohol: Glucose và fructose có nhiều nhóm –OH liền kề nên hòa tan Cu(OH)₂ trong môi trường kiềm tạo dung dịch màu xanh lam: 2C₆H₁₂O₆ + Cu(OH)₂ →…","Tính chất aldehyde của glucose: Bị oxi hóa bởi Cu(OH)₂/NaOH khi đun nóng (tạo kết tủa đỏ gạch Cu₂O), bởi thuốc thử Tollens (tạo kết tủa bạc) và bởi nước bromine (làm mất màu nước…"],"e":["Hay nhầm: Đây là công thức của saccharose và maltose.","Hay nhầm: Đây là công thức của tinh bột và cellulose.","Hay nhầm: Đây không phải công thức của glucose.","Hay nhầm: Disaccharide khi thủy phân tạo hai phân tử monosaccharide.","Hay nhầm: Polysaccharide thủy phân tạo nhiều phân tử monosaccharide.","Hay nhầm: Glucose là carbohydrate, không phải lipid."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 5. Saccharose và maltose","sum":["Saccharose có công thức phân tử C₁₂H₂₂O₁₁, cấu tạo từ một đơn vị α-glucose và một đơn vị β-fructose qua liên kết α-1,2-glycoside.","Khái niệm: Saccharose có công thức phân tử C₁₂H₂₂O₁₁, cấu tạo từ một đơn vị α-glucose và một đơn vị β-fructose qua liên kết α-1,2-glycoside.","Maltose có công thức phân tử C₁₂H₂₂O₁₁…: Maltose có công thức phân tử C₁₂H₂₂O₁₁, cấu tạo từ hai đơn vị glucose qua liên kết α-1,4-glycoside.","Tính chất của saccharose: Polyalcohol: hòa tan Cu(OH)₂ trong môi trường kiềm tạo dung dịch xanh lam: 2C₁₂H₂₂O₁₁ + Cu(OH)₂ → (C₁₂H₂₁O₁₁)₂Cu + 2H₂O.","Maltose bị thủy phân tạo hai phân tử glucose: Saccharose có nhiều trong cây mía, củ cải đường, hoa thốt nốt, dùng làm chất tạo ngọt (bánh, kẹo, nước giải khát)."],"e":["Hay nhầm: Đây là cấu tạo của maltose.","Hay nhầm: Saccharose có một gốc glucose.","Hay nhầm: Đây là cấu tạo của tinh bột.","Hay nhầm: Liên kết α-1,2-glycoside là của saccharose.","Hay nhầm: Maltose không chứa fructose.","Hay nhầm: Liên kết β-1,4 có trong cellulose."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}},{"t":"Bài 6. Tinh bột và cellulose","sum":["Tinh bột là polymer thiên nhiên có công thức phân tử (C₆H₁₀O₅)ₙ, gồm amylose và amylopectin.","Khái niệm: Tinh bột là polymer thiên nhiên có công thức phân tử (C₆H₁₀O₅)ₙ, gồm amylose và amylopectin.","Cellulose là polymer thiên nhiên có công…: Cellulose là polymer thiên nhiên có công thức (C₆H₁₀O₅)ₙ, cấu tạo từ nhiều đơn vị β-glucose liên kết qua liên kết β-1,4-glycoside, tạo chuỗi không…","Tính chất hóa học của tinh bột: Bị thủy phân nhờ enzyme hoặc acid (không hoàn toàn tạo dextrin, maltose, glucose; hoàn toàn tạo glucose): (C₆H₁₀O₅)ₙ + nH₂O → nC₆H₁₂O₆.","Tính chất hóa học của cellulose: Thủy phân hoàn toàn tạo glucose (xúc tác acid hoặc enzyme); tác dụng với hỗn hợp HNO₃ đặc và H₂SO₄ đặc tạo cellulose nitrate: [C₆H₇O₂(OH)₃]ₙ +…","Tinh bột là chất rắn màu trắng…: Tinh bột là chất rắn màu trắng, không tan trong nước lạnh, trong nước nóng tạo dung dịch keo gọi là hồ tinh bột."],"e":["Hay nhầm: Đây là công thức của glucose và fructose.","Hay nhầm: Đây là công thức của saccharose và maltose.","Hay nhầm: Không đúng với tinh bột và cellulose.","Hay nhầm: Tinh bột không có phản ứng tráng bạc.","Hay nhầm: Tinh bột không hòa tan Cu(OH)₂ tạo xanh lam.","Hay nhầm: Tinh bột không làm mất màu nước bromine."],"q":{"n":13,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 7. Ôn tập chương 2","e":["Hay nhầm: Cả glucose và fructose đều là monosaccharide.","Hay nhầm: Chỉ có glucose và fructose là monosaccharide.","Hay nhầm: Saccharose, maltose là disaccharide.","Hay nhầm: Saccharose thủy phân tạo glucose và fructose.","Hay nhầm: Tinh bột thủy phân tạo glucose.","Hay nhầm: Cellulose thủy phân tạo glucose."],"q":{"n":12,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương 3. Hợp chất chứa nitrogen","l":[{"t":"Bài 8. Amine","sum":["Amine là dẫn xuất của ammonia, trong đó nguyên tử hydrogen trong phân tử ammonia được thay thế bằng gốc hydrocarbon.","Khái niệm: Amine là dẫn xuất của ammonia, trong đó nguyên tử hydrogen trong phân tử ammonia được thay thế bằng gốc hydrocarbon.","Phân loại: Theo bậc (số gốc hydrocarbon liên kết trực tiếp với nguyên tử N): amine bậc một RNH₂, bậc hai R–NH–R′, bậc ba R₃N.","Đồng phân: Amine từ hai nguyên tử carbon trở lên có đồng phân bậc amine, mạch carbon và vị trí nhóm amine.","Danh pháp: Danh pháp gốc – chức = tên gốc hydrocarbon + amine (CH₃CH₂NH₂: ethylamine); danh pháp thay thế = tên hydrocarbon (bỏ e) + vị trí + amine…","Tính chất vật lí: Methylamine, dimethylamine, trimethylamine, ethylamine là chất khí mùi tanh của cá hoặc khai (giống ammonia); amine ít carbon tan tốt trong nước nhờ…"],"e":["Hay nhầm: Bậc amine tính theo số gốc hydrocarbon gắn với N, không theo số nhóm –NH₂.","Hay nhầm: Aniline có tính base rất yếu, không làm đổi màu quỳ tím.","Hay nhầm: Phân tử khối amine không nhỏ hơn đáng kể.","Hay nhầm: Amine là hợp chất phân cực.","Hay nhầm: Amine ít carbon tan tốt trong nước.","Hay nhầm: Acetic acid không làm tăng sự bay hơi."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 9. Amino acid và peptide","sum":["Amino acid là hợp chất hữu cơ tạp chức, trong phân tử chứa đồng thời nhóm amino (–NH₂) và nhóm carboxyl (–COOH).","Khái niệm: Amino acid là hợp chất hữu cơ tạp chức, trong phân tử chứa đồng thời nhóm amino (–NH₂) và nhóm carboxyl (–COOH).","Một số amino acid: Glycine (Gly) H₂NCH₂COOH, M = 75; alanine (Ala) H₂NCH(CH₃)COOH, M = 89; valine (Val), M = 117; lysine (Lys) có 2 nhóm –NH₂ và 1 nhóm –COOH, M = 146;…","Cấu tạo và tính chất vật lí: Amino acid tồn tại chủ yếu ở dạng ion lưỡng cực H₃N⁺–CH(R)–COO⁻ nên là chất rắn kết tinh, không màu, nhiệt độ nóng chảy cao, thường tan tốt trong…","Tính chất hóa học: Phản ứng ester hóa với alcohol (xúc tác H₂SO₄ đặc), ví dụ H₂NCH₂COOH + C₂H₅OH ⇌ H₂NCH₂COOC₂H₅ + H₂O.","Peptide là hợp chất hữu cơ cấu…: Peptide là hợp chất hữu cơ cấu tạo từ các đơn vị α-amino acid liên kết với nhau qua liên kết peptide (–CO–NH–)."],"e":["Hay nhầm: Nhóm –OH và –NH₂ không phải đặc điểm của amino acid.","Hay nhầm: Đó không phải amino acid.","Hay nhầm: Không phải liên kết peptide.","Hay nhầm: Đó là hiện tượng ở pH < 6 khi Gly thành cation.","Hay nhầm: Đó là hiện tượng ở pH > 6 khi Gly thành anion.","Hay nhầm: Amino acid không có liên kết peptide."],"q":{"n":15,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 10. Protein và enzyme","sum":["Protein là hợp chất cao phân tử được cấu tạo từ một hay nhiều chuỗi polypeptide; mỗi chuỗi gồm các đơn vị α-amino acid liên kết với nhau qua liên kết peptide theo một trật tự nhất định.","Khái niệm: Protein là hợp chất cao phân tử được cấu tạo từ một hay nhiều chuỗi polypeptide; mỗi chuỗi gồm các đơn vị α-amino acid liên kết với nhau qua liên…","Tính chất vật lí: Protein dạng hình sợi (keratin ở tóc và móng, collagen ở da, myosin ở cơ) không tan trong nước và dung môi thông thường; protein dạng hình cầu…","Tính chất hóa học: Thủy phân nhờ acid, base hoặc enzyme, hoàn toàn tạo các α-amino acid","Vai trò: Protein tham gia xây dựng tế bào, vận chuyển chất, điều hòa trao đổi chất, xúc tác phản ứng sinh hóa, chống tác nhân có hại và là nguồn cung cấp…","Enzyme: Phần lớn enzyme là protein xúc tác cho các phản ứng hóa học và sinh hóa; enzyme có tính chọn lọc cao (mỗi enzyme xúc tác cho một hoặc một số phản…"],"e":["Hay nhầm: Protein tạo từ amino acid, không phải glucose.","Hay nhầm: Glucose thu được khi thủy phân carbohydrate.","Hay nhầm: Đó là sản phẩm thủy phân chất béo.","Hay nhầm: Keratin là protein hình sợi, không tan.","Hay nhầm: Collagen là protein hình sợi, không tan.","Hay nhầm: Myosin là protein hình sợi."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 11. Ôn tập chương 3","e":["Hay nhầm: Có ba phát biểu đúng: (2), (3), (4).","Hay nhầm: Có nhiều hơn một phát biểu đúng.","Hay nhầm: Có 3 dipeptide và 2 tripeptide.","Hay nhầm: Chỉ có 5 peptide như vậy.","Hay nhầm: Glycine không có liên kết peptide.","Hay nhầm: Dipeptide không có phản ứng biuret."],"q":{"n":12,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương 4. Polymer","l":[{"t":"Bài 12. Đại cương về polymer","sum":["Polymer là những hợp chất có phân tử khối lớn do nhiều đơn vị nhỏ (gọi là mắt xích) liên kết với nhau tạo nên.","Khái niệm: Polymer là những hợp chất có phân tử khối lớn do nhiều đơn vị nhỏ (gọi là mắt xích) liên kết với nhau tạo nên.","Danh pháp: Các polymer đơn giản được gọi theo \"poly\" + tên monomer (đặt trong ngoặc đơn nếu tên monomer gồm hai cụm từ): polyethylene (PE), polypropylene (PP),…","Tính chất vật lí: Hầu hết polymer là chất rắn, không bay hơi, không nóng chảy hoặc nóng chảy ở khoảng nhiệt độ rộng.","Tính chất hóa học: Cắt mạch: polystyrene nhiệt phân thành styrene; polyamide (capron, nylon-6,6), tinh bột, cellulose bị thủy phân (acid, base hoặc enzyme).","Phương pháp tổng hợp: Trùng hợp là quá trình kết hợp nhiều phân tử nhỏ giống nhau hoặc tương tự nhau thành polymer; monomer thường có liên kết đôi (CH₂=CHR) hoặc vòng kém…"],"e":["Hay nhầm: Polymer có phân tử khối lớn gồm nhiều mắt xích.","Hay nhầm: Đó là dimer, không phải polymer.","Hay nhầm: Polymer chứa liên kết cộng hóa trị.","Hay nhầm: PVC điều chế bằng trùng hợp.","Hay nhầm: PE điều chế bằng trùng hợp.","Hay nhầm: PS điều chế bằng trùng hợp."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 13. Vật liệu polymer","sum":["Chất dẻo là vật liệu polymer có tính dẻo (bị biến dạng khi chịu tác dụng của nhiệt, áp lực và vẫn giữ biến dạng khi thôi tác dụng).","Khái niệm: Chất dẻo là vật liệu polymer có tính dẻo (bị biến dạng khi chịu tác dụng của nhiệt, áp lực và vẫn giữ biến dạng khi thôi tác dụng).","Ứng dụng: PE (túi nylon, màng bọc thực phẩm, chai lọ), PP (bao gói, hộp, ống nước), PVC (ống nước, vỏ cáp điện, khung cửa, sàn nhựa, giày ủng), PS (hộp xốp,…","Vật liệu composite được tổ hợp từ…: Vật liệu composite được tổ hợp từ hai hay nhiều vật liệu khác nhau, có tính chất vượt trội so với vật liệu ban đầu; gồm vật liệu cốt (sợi thủy tinh,…","Tơ là vật liệu polymer dạng sợi mảnh, có độ bền nhất định: Phân loại: tơ tự nhiên (bông – cellulose; len, tơ tằm – protein), tơ bán tổng hợp (visco, cellulose acetate – chế biến từ cellulose), tơ tổng hợp…","Cao su là vật liệu polymer có tính đàn hồi: Cao su thiên nhiên gồm các mắt xích isoprene (liên kết đôi dạng cis), có tính đàn hồi, không dẫn điện, không thấm khí và nước, tan trong xăng,…"],"e":["Hay nhầm: Vật liệu có tính đàn hồi là cao su.","Hay nhầm: Vật liệu dạng sợi mảnh là tơ.","Hay nhầm: Vật liệu kết dính là keo dán.","Hay nhầm: Ống nước dùng PVC hoặc PP.","Hay nhầm: Lưu huỳnh dùng để lưu hóa, không phải monomer.","Hay nhầm: Isoprene tạo cao su isoprene."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 14. Ôn tập chương 4","e":["Hay nhầm: Lưu huỳnh dùng để lưu hóa.","Hay nhầm: Buta-1,3-diene (hai liên kết đôi) mới là monomer.","Hay nhầm: Keo 502 trùng hợp nhờ hơi ẩm.","Hay nhầm: Không phải điều kiện chính.","Hay nhầm: Nylon-6,6 điều chế bằng trùng ngưng.","Hay nhầm: PPF điều chế bằng trùng ngưng."],"q":{"n":12,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương 5. Pin điện và điện phân","l":[{"t":"Bài 15. Thế điện cực và nguồn điện hóa học","sum":["Cặp oxi hóa – khử của kim loại gồm dạng oxi hóa (Mⁿ⁺) và dạng khử (M) của cùng một nguyên tố: Mⁿ⁺ + ne ⇌ M, ví dụ Zn²⁺/Zn, Cu²⁺/Cu, Ag⁺/Ag.","Khái niệm: Cặp oxi hóa – khử của kim loại gồm dạng oxi hóa (Mⁿ⁺) và dạng khử (M) của cùng một nguyên tố: Mⁿ⁺ + ne ⇌ M, ví dụ Zn²⁺/Zn, Cu²⁺/Cu, Ag⁺/Ag.","Thế điện cực chuẩn E° là đại…: Thế điện cực chuẩn E° là đại lượng đặc trưng cho điện cực ở điều kiện chuẩn (nồng độ ion 1 M, 25 °C); quy ước E°(2H⁺/H₂) = 0 V.","Ý nghĩa: E° càng nhỏ thì dạng khử có tính khử càng mạnh và dạng oxi hóa có tính oxi hóa càng yếu;","Chiều phản ứng: Chất khử của cặp có E° nhỏ hơn tác dụng với chất oxi hóa của cặp có E° lớn hơn (quy tắc α).","Pin Galvani gồm hai điện cực nối…: Pin Galvani gồm hai điện cực nối với nhau bằng dây dẫn và cầu muối."],"e":["Hay nhầm: Đó là thế điện cực chuẩn của cặp Cu²⁺/Cu.","Hay nhầm: Không phải quá trình tại điện cực.","Hay nhầm: Không phải quá trình điện cực chính.","Hay nhầm: Ag có E° lớn nhất nên khử yếu nhất.","Hay nhầm: Các kim loại này có E° > 0.","Hay nhầm: Cu và Ag có E° > 0 nên không khử được H⁺."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 16. Điện phân","sum":["Điện phân là quá trình oxi hóa – khử xảy ra tại các điện cực khi có dòng điện một chiều đi qua chất điện li nóng chảy hoặc dung dịch chất điện li.","Khái niệm: Điện phân là quá trình oxi hóa – khử xảy ra tại các điện cực khi có dòng điện một chiều đi qua chất điện li nóng chảy hoặc dung dịch chất điện li.","Nước có thể tham gia điện phân: Là chất oxi hóa ở cathode (2H₂O + 2e → H₂ + 2OH⁻) hoặc chất khử ở anode (2H₂O → O₂ + 4H⁺ + 4e).","Thứ tự điện phân: Tại cathode, chất oxi hóa mạnh hơn bị khử trước (Au³⁺ > Ag⁺ > Hg²⁺ > Cu²⁺ > H⁺ > H₂O; các ion kim loại mạnh như Na⁺, K⁺, Ca²⁺, Mg²⁺, Al³⁺ không bị…","Nếu không có màng ngăn, Cl₂ phản ứng với NaOH tạo nước Javel: Cl₂ + 2NaOH → NaCl + NaClO + H₂O.","Ứng dụng: Sản xuất kim loại — kim loại mạnh (Na, K, Mg, Ca, Al) bằng điện phân nóng chảy; Zn, Cu,… bằng điện phân dung dịch. Nhôm: điện phân Al₂O₃ nóng chảy…"],"e":["Hay nhầm: Không phải quá trình tại điện cực.","Hay nhầm: Không phải quá trình tại điện cực.","Hay nhầm: Cu được điều chế bằng điện phân dung dịch hoặc các phương pháp khác.","Hay nhầm: Ag được điều chế bằng thủy luyện hoặc điện phân dung dịch.","Hay nhầm: Fe được điều chế bằng nhiệt luyện.","Hay nhầm: Nước bị khử trước Al³⁺ nên không thu được Al."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 17. Ôn tập chương 5","e":["Hay nhầm: Có ba kim loại có E° < 0.","Hay nhầm: Có ba kim loại có E° < 0.","Hay nhầm: Ag có E° > 0 nên không khử được H⁺.","Hay nhầm: Có nhiều hơn một kim loại có E° nhỏ hơn Ag.","Hay nhầm: Có ba kim loại: Al, Mg, Fe.","Hay nhầm: Không có cầu muối trong bình mạ điện."],"q":{"n":12,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương 6. Đại cương về kim loại","l":[{"t":"Bài 18. Cấu tạo và liên kết trong tinh thể kim loại","sum":["Đặc điểm cấu tạo nguyên tử kim loại: các nguyên tố khối s, d, f hầu hết là kim loại (nhóm IA, IIA và nhóm B).","Đặc điểm cấu tạo nguyên tử kim loại: Các nguyên tố khối s, d, f hầu hết là kim loại (nhóm IA, IIA và nhóm B).","Ví dụ cấu hình electron: Sc (Z = 21): 1s²2s²2p⁶3s²3p⁶3d¹4s²;","Tinh thể kim loại: Ở nhiệt độ phòng, đơn chất kim loại ở thể rắn và có cấu tạo tinh thể (trừ thủy ngân là chất lỏng).","Liên kết kim loại: Hình thành do lực hút tĩnh điện giữa các electron hóa trị tự do với các ion dương kim loại ở các nút mạng."],"e":["Hay nhầm: Phi kim thường có 5–7 electron lớp ngoài.","Hay nhầm: Phi kim thường có 5–7 electron lớp ngoài.","Hay nhầm: Cấu hình bền của khí hiếm.","Hay nhầm: Đó là liên kết cộng hóa trị.","Hay nhầm: Đây là đặc điểm của phi kim.","Hay nhầm: Kim loại có điện tích hạt nhân nhỏ hơn."],"q":{"n":13,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 19. Tính chất vật lí và tính chất hóa học của kim loại","sum":["Tính chất vật lí chung: kim loại có tính dẻo (dễ rèn, dát mỏng, kéo sợi), dẫn điện, dẫn nhiệt và ánh kim; các tính chất này do electron tự do trong mạng tinh thể gây ra.","Tính chất vật lí chung: Kim loại có tính dẻo (dễ rèn, dát mỏng, kéo sợi), dẫn điện, dẫn nhiệt và ánh kim; các tính chất này do electron tự do trong mạng tinh thể gây ra.","Tính chất vật lí khác: Khối lượng riêng (Li nhẹ nhất 0,534 g/cm³;","Tính chất hóa học chung của kim loại là tính khử: M → Mⁿ⁺ + ne.","Tác dụng với phi kim: Với O₂ tạo oxide (4Al + 3O₂ → 2Al₂O₃; trừ Au, Ag, Pt); với Cl₂ tạo muối chloride (2Fe + 3Cl₂ → 2FeCl₃); với S tạo sulfide (Fe + S → FeS;","Tác dụng với nước: Kim loại nhóm IA, IIA mạnh (E° < −0,414 V) khử được nước ở nhiệt độ thường: 2Na + 2H₂O → 2NaOH + H₂."],"e":["Hay nhầm: Al dẫn điện kém hơn Ag, Cu, Au.","Hay nhầm: Hg là kim loại lỏng ở điều kiện thường.","Hay nhầm: Na nóng chảy ở nhiệt độ thấp.","Hay nhầm: Al nóng chảy ở nhiệt độ thấp hơn W rất nhiều.","Hay nhầm: Kim loại dễ nhường electron.","Hay nhầm: Kim loại không có tính acid chung."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 20. Kim loại trong tự nhiên và phương pháp tách kim loại","sum":["Trong tự nhiên, hầu hết kim loại tồn tại ở dạng hợp chất (oxide, muối,…) trong quặng; chỉ các kim loại kém hoạt động (Au, Ag, Pt,…) có dạng đơn chất.","Khái niệm: Trong tự nhiên, hầu hết kim loại tồn tại ở dạng hợp chất (oxide, muối,…) trong quặng; chỉ các kim loại kém hoạt động (Au, Ag, Pt,…) có dạng đơn chất.","Nguyên tắc điều chế kim loại: Khử ion kim loại thành nguyên tử: Mⁿ⁺ + ne → M.","Kim loại hoạt động mạnh (K, Na, Ca, Mg, Al,…): Điện phân nóng chảy hợp chất (oxide hoặc chloride).","Kim loại hoạt động trung bình, yếu (Zn, Fe, Sn, Pb, Cu,…): Nhiệt luyện — khử oxide ở nhiệt độ cao bằng C, CO,…: Fe₂O₃ + 3CO → 2Fe + 3CO₂; ZnO + C → Zn + CO","Tái chế kim loại (sắt, nhôm, đồng)…: Tái chế kim loại (sắt, nhôm, đồng) vừa bảo đảm nguồn cung, tiết kiệm năng lượng, vừa bảo vệ môi trường và phát triển bền vững; quy trình gồm thu…"],"e":["Hay nhầm: Fe có trong quặng hematite, pyrite.","Hay nhầm: Đó là quá trình ngược lại.","Hay nhầm: Không phải nguyên tắc điều chế.","Hay nhầm: Không phải nguyên tắc điều chế.","Hay nhầm: Fe được điều chế bằng nhiệt luyện.","Hay nhầm: Cu điều chế bằng điện phân dung dịch, thủy luyện."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 21. Hợp kim","sum":["Hợp kim là vật liệu kim loại chứa một kim loại cơ bản và một số kim loại khác hoặc phi kim.","Khái niệm: Hợp kim là vật liệu kim loại chứa một kim loại cơ bản và một số kim loại khác hoặc phi kim.","Tính chất: Tính chất hóa học của hợp kim thường tương tự các kim loại thành phần, nhưng tính chất vật lí thường khác nhiều.","Gang: Hợp kim chứa khoảng 95% sắt, 2–4% carbon cùng Mn, Si, P, S,…; cứng, giòn; dùng làm nguyên liệu luyện thép, dụng cụ đun nấu, chi tiết máy.","Thép: Hợp kim của sắt chứa dưới 2,0% carbon và một số nguyên tố như Cr, Mn, Si,…; là vật liệu chủ yếu trong chế tạo máy, xây dựng.","Duralumin: Hợp kim chứa trên 90% nhôm, khoảng 4% đồng và một ít Mn, Mg, Si; nhẹ, cứng, bền; dùng rộng rãi trong chế tạo máy bay."],"e":["Hay nhầm: Đó là kim loại nguyên chất.","Hay nhầm: Hợp kim là vật liệu kim loại.","Hay nhầm: Hợp kim không phải hợp chất ion.","Hay nhầm: Thép chứa một lượng nhỏ carbon.","Hay nhầm: Không phải thành phần của duralumin.","Hay nhầm: Không phải thành phần của duralumin."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 22. Sự ăn mòn kim loại","sum":["Ăn mòn kim loại là sự phá hủy kim loại hoặc hợp kim dưới tác dụng của các chất trong môi trường, trong đó kim loại bị oxi hóa: M → Mⁿ⁺ + ne.","Khái niệm: Ăn mòn kim loại là sự phá hủy kim loại hoặc hợp kim dưới tác dụng của các chất trong môi trường, trong đó kim loại bị oxi hóa: M → Mⁿ⁺ + ne.","Ăn mòn hóa học: Xảy ra phản ứng oxi hóa – khử trực tiếp giữa kim loại với chất oxi hóa trong môi trường (không phát sinh dòng điện).","Ăn mòn điện hóa: Xảy ra khi có sự tạo thành pin điện.","Điều kiện ăn mòn điện hóa: Có hai điện cực khác nhau (hai kim loại khác nhau, hoặc kim loại và phi kim); các điện cực tiếp xúc nhau trực tiếp hoặc qua dây dẫn; cùng tiếp xúc…","Chống ăn mòn: Phương pháp điện hóa — gắn kim loại cần bảo vệ với kim loại hoạt động mạnh hơn (ví dụ gắn tấm Zn vào vỏ tàu thép; Zn bị ăn mòn thay cho Fe)"],"e":["Hay nhầm: Ăn mòn do phản ứng hóa học với môi trường.","Hay nhầm: Ăn mòn liên quan tới phản ứng oxi hóa.","Hay nhầm: Không phải nguyên nhân chính.","Hay nhầm: Đó là phương pháp phủ bề mặt.","Hay nhầm: Đó là phương pháp phủ bề mặt.","Hay nhầm: Đó là phương pháp phủ bề mặt."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 23. Ôn tập chương 6","e":["Hay nhầm: Ca phản ứng mạnh với HCl.","Hay nhầm: Fe²⁺/Fe có E° nhỏ hơn Cu²⁺/Cu.","Hay nhầm: Cốc 1 chỉ có Zn tiếp xúc với dung dịch acid.","Hay nhầm: Cốc 2 xuất hiện Cu bám lên Zn tạo pin Zn–Cu.","Hay nhầm: Zn vẫn bị ăn mòn nhanh hơn.","Hay nhầm: Các nguyên tố nhóm B đều là kim loại."],"q":{"n":12,"lv":{"Biết":1,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương 7. Nguyên tố nhóm IA và nhóm IIA","l":[{"t":"Bài 24. Nguyên tố nhóm IA","sum":["Nguyên tố nhóm IA (kim loại kiềm: Li, Na, K, Rb, Cs) là các nguyên tố s, có 1 electron hóa trị ở phân lớp ns¹ và đứng đầu mỗi chu kì.","Nguyên tố nhóm IA (kim loại kiềm: Li, Na, K, Rb, Cs) là các nguyên tố s, có 1 electron hóa trị ở phân lớp ns¹ và đứng đầu mỗi chu kì.","Trạng thái tự nhiên: Chỉ tồn tại ở dạng hợp chất (chủ yếu là muối).","Tính chất vật lí: Nhiệt độ nóng chảy, nhiệt độ sôi thấp và giảm dần từ Li đến Cs; khối lượng riêng nhỏ (kim loại nhẹ) do bán kính nguyên tử lớn và mạng tinh thể kém…","Tính chất hóa học: Tính khử mạnh; phản ứng với nước ở điều kiện thường (2Na + 2H₂O → 2NaOH + H₂), với O₂ (4Na + O₂ → 2Na₂O) và Cl₂ (2Na + Cl₂ → 2NaCl); mức độ phản ứng…","Bảo quản: Ngâm trong dầu hỏa khan (Na, K), hoặc trong chân không, khí hiếm (Rb, Cs trong ống thủy tinh hàn kín)."],"e":["Hay nhầm: Nhóm IIA mới có 2 electron hóa trị.","Hay nhầm: Không phải kim loại kiềm.","Hay nhầm: Đó là số oxi hóa của nhóm IIA.","Hay nhầm: Kim loại không có số oxi hóa âm trong hợp chất.","Hay nhầm: Kim loại kiềm tác dụng mạnh với nước.","Hay nhầm: Kim loại kiềm tác dụng với ethanol."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 25. Nguyên tố nhóm IIA","sum":["Nguyên tố nhóm IIA (Be, Mg, Ca, Sr, Ba, Ra) là nguyên tố s, có 2 electron hóa trị (ns²), đứng ngay sau kim loại kiềm ở mỗi chu kì.","Khái niệm: Nguyên tố nhóm IIA (Be, Mg, Ca, Sr, Ba, Ra) là nguyên tố s, có 2 electron hóa trị (ns²), đứng ngay sau kim loại kiềm ở mỗi chu kì.","Tính chất vật lí: Nhiệt độ nóng chảy cao hơn kim loại nhóm IA nhưng tương đối thấp so với nhiều kim loại khác;","Tính chất hóa học: Tác dụng với O₂ (Be bền nhờ màng oxide bảo vệ, Mg bị oxi hóa chậm, các kim loại còn lại bị oxi hóa nhanh): 2Mg + O₂ → 2MgO; với nước: Be không phản…","Độ tan của muối: Nitrate đều dễ tan; carbonate ít tan hoặc không tan; sulfate: MgSO₄ dễ tan, CaSO₄ ít tan, BaSO₄ không tan (độ tan giảm dần từ MgSO₄ đến BaSO₄).","Muối carbonate: Tác dụng với acid giải phóng CO₂ (CaCO₃ + 2HCl → CaCl₂ + CO₂ + H₂O); tan dần trong nước có hòa tan CO₂ (CaCO₃ + CO₂ + H₂O → Ca(HCO₃)₂); bị nhiệt…"],"e":["Hay nhầm: Các ion này không gây tính cứng.","Hay nhầm: Là anion, không phải cation gây cứng.","Hay nhầm: Không phải ion gây tính cứng chủ yếu.","Hay nhầm: Biến thiên enthalpy tăng nên độ bền nhiệt tăng.","Hay nhầm: Các muối khác nhau về độ bền nhiệt.","Hay nhầm: Muối nitrate thường không nêu trong phân loại."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 26. Ôn tập chương 7","e":["Hay nhầm: NaCl còn trong dung dịch.","Hay nhầm: Không phải sản phẩm tách ra.","Hay nhầm: Không phải ion gây tính cứng.","Hay nhầm: Không phải cation gây tính cứng.","Hay nhầm: Có màu ngọn lửa khác nhau."],"q":{"n":12,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương 8. Sơ lược về dãy kim loại chuyển tiếp thứ nhất và phức chất","l":[{"t":"Bài 27. Đại cương về kim loại chuyển tiếp dãy thứ nhất","sum":["Kim loại chuyển tiếp dãy thứ nhất gồm 9 nguyên tố chu kì 4 từ Sc (Z = 21) đến Cu (Z = 29), thuộc khối d (nhóm B).","Khái niệm: Kim loại chuyển tiếp dãy thứ nhất gồm 9 nguyên tố chu kì 4 từ Sc (Z = 21) đến Cu (Z = 29), thuộc khối d (nhóm B).","Tính chất vật lí: Nhiệt độ nóng chảy cao (đặc biệt V, Cr, Co), độ cứng cao (Cr cứng nhất), khối lượng riêng lớn (Sc, Ti tương đối nhẹ, các kim loại khác là kim loại…","Số oxi hóa: Do có nhiều electron hóa trị ở 4s và 3d nên các nguyên tố chuyển tiếp thể hiện nhiều trạng thái oxi hóa.","Màu sắc: Ion kim loại chuyển tiếp thường có màu phong phú trong dung dịch (Cu²⁺ xanh lam;","Chuẩn độ Fe²⁺ bằng KMnO₄ trong môi trường H₂SO₄: 10FeSO₄ + 2KMnO₄ + 8H₂SO₄ → 5Fe₂(SO₄)₃ + K₂SO₄ + 2MnSO₄ + 8H₂O."],"e":["Hay nhầm: K, Ca không phải kim loại chuyển tiếp.","Hay nhầm: Dãy gồm 9 nguyên tố, dừng ở Cu.","Hay nhầm: Chưa đủ các nguyên tố của dãy.","Hay nhầm: Phần lớn có 2 electron ở 4s.","Hay nhầm: Hầu hết có electron ở 4s.","Hay nhầm: Không phải nguyên nhân chính."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 28. Sơ lược về phức chất","sum":["Phức chất là hợp chất chứa nguyên tử trung tâm (cation kim loại hoặc nguyên tử kim loại, kí hiệu M) liên kết với các phối tử (L; là anion hoặc phân tử).","Khái niệm: Phức chất là hợp chất chứa nguyên tử trung tâm (cation kim loại hoặc nguyên tử kim loại, kí hiệu M) liên kết với các phối tử (L; là anion hoặc phân…","Dạng hình học phổ biến của phức chất [MLₙ]: Tứ diện (4 phối tử), vuông phẳng (4 phối tử) và bát diện (6 phối tử).","Liên kết giữa nguyên tử trung tâm…: Liên kết giữa nguyên tử trung tâm M và phối tử L là liên kết cho – nhận: phối tử cho cặp electron chưa liên kết vào orbital trống của nguyên tử…","Phức chất aqua: Trong dung dịch nước, ion kim loại chuyển tiếp Mⁿ⁺ nhận cặp electron của H₂O tạo phức [M(H₂O)ₓ]ⁿ⁺, hầu hết có dạng bát diện: [Fe(H₂O)₆]²⁺,…"],"e":["Hay nhầm: N là nguyên tử cho cặp electron, không phải nguyên tử trung tâm.","Hay nhầm: H không phải nguyên tử trung tâm.","Hay nhầm: Zn²⁺ là nguyên tử trung tâm.","Hay nhầm: Phức chất này không chứa H₂O.","Hay nhầm: Zn²⁺ là nguyên tử trung tâm.","Hay nhầm: Không phải liên kết ion thuần túy."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 29. Một số tính chất và ứng dụng của phức chất","sum":["Dấu hiệu của phản ứng tạo phức chất trong dung dịch: xuất hiện kết tủa, hòa tan kết tủa, thay đổi màu sắc.","Dấu hiệu của phản ứng tạo phức chất trong dung dịch: Xuất hiện kết tủa, hòa tan kết tủa, thay đổi màu sắc. Ví dụ:","Phức chất mang điện (như [Co(NH₃)₆]³⁺, [Zn(OH)₄]²⁻)…: Phức chất mang điện (như [Co(NH₃)₆]³⁺, [Zn(OH)₄]²⁻) thường tan tốt trong nước; phức chất trung hòa như [Fe(CO)₅], [PtCl₂(NH₃)₂] thường ít tan.","Phản ứng thế phối tử: Phối tử trong phức chất có thể bị thế bởi phối tử khác, thuận lợi khi phức mới bền hơn.","Ứng dụng: Y học (cisplatin [PtCl₂(NH₃)₂] chữa ung thư); công nghiệp hóa chất (phức chất làm xúc tác tổng hợp, ví dụ [Pd(P(C₆H₅)₃)₄]); hóa học phân tích (nhận…"],"e":["Hay nhầm: Không phải ứng dụng chính.","Hay nhầm: Insulin không chứa phức Fe.","Hay nhầm: Kết tủa tan nhờ tạo phức.","Hay nhầm: Có tạo phức [Cu(NH₃)₄(H₂O)₂]²⁺.","Hay nhầm: Có tạo phức [CuCl₄]²⁻ màu vàng.","Hay nhầm: Phản ứng không thuận lợi."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 30. Ôn tập chương 8","e":["Hay nhầm: Đây là cấu hình nguyên tử Fe.","Hay nhầm: Zn (3d¹⁰4s²) không được tính trong dãy này.","Hay nhầm: Sc và Ti tương đối nhẹ (D < 5).","Hay nhầm: Nhiều hợp chất không màu.","Hay nhầm: Có nhiệt độ nóng chảy cao hơn.","Hay nhầm: Có 2 phối tử Cl⁻ còn lại."],"q":{"n":12,"lv":{"Biết":1,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}}]}]}]},{"id":"sinh","name":"Sinh học","b":[{"t":"Sinh học 12","c":[{"t":"Chương I. Di truyền phân tử","l":[{"t":"Bài 1. DNA và cơ chế tái bản DNA","sum":["Chức năng của DNA: mang, bảo quản và truyền đạt thông tin di truyền. DNA cấu trúc theo nguyên tắc đa phân gồm 4 loại nucleotide A, T, G, C (như “chữ cái” ghi mã thông tin); cấu trúc xoắn kép bền…","Chức năng của DNA: Mang, bảo quản và truyền đạt thông tin di truyền.","Tái bản DNA bắt đầu từ điểm…: Tái bản DNA bắt đầu từ điểm khởi đầu sao chép (Ori), tiến hành theo hai hướng ngược nhau tạo đơn vị tái bản và chạc sao chép hình chữ Y.","Kết quả: Từ một phân tử DNA mẹ tạo ra hai phân tử DNA con giống nhau và giống mẹ, mỗi phân tử có một mạch cũ và một mạch mới (nguyên tắc bán bảo toàn)."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: DNA là vật chất di truyền.","Hay nhầm: Chưa đúng với nội dung bài học: DNA là vật chất di truyền.","Hay nhầm: Chưa đúng với nội dung bài học: DNA là vật chất di truyền.","Hay nhầm: Chưa đúng với nội dung bài học: U có trong RNA.","Hay nhầm: Chưa đúng với nội dung bài học: U có trong RNA.","Hay nhầm: Chưa đúng với nội dung bài học: U có trong RNA."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 2. Gene, quá trình truyền đạt thông tin di truyền và hệ gene","sum":["Gene là một đoạn của phân tử DNA mang thông tin quy định một sản phẩm (chuỗi polypeptide hoặc RNA).","Khái niệm: Gene là một đoạn của phân tử DNA mang thông tin quy định một sản phẩm (chuỗi polypeptide hoặc RNA).","Hệ gene là tập hợp tất cả…: Hệ gene là tập hợp tất cả vật chất di truyền (DNA) trong tế bào của một sinh vật.","Phiên mã là tổng hợp RNA dựa trên mạch khuôn của gene: Khởi đầu (RNA polymerase liên kết promoter), kéo dài (tổng hợp mRNA theo chiều 5’ → 3’, NTBS A – U, T – A, G – C, C – G), kết thúc (gặp tín hiệu kết…","Mã di truyền là bộ các bộ…: Mã di truyền là bộ các bộ ba nucleotide (codon) trên mRNA quy định amino acid: 61 bộ ba mã hoá amino acid và 3 bộ ba kết thúc (UAA, UAG, UGA);"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Ba vùng.","Hay nhầm: Chưa đúng với nội dung bài học: Ba vùng.","Hay nhầm: Chưa đúng với nội dung bài học: Ba vùng.","Hay nhầm: Chưa đúng với nội dung bài học: Khởi đầu phiên mã.","Hay nhầm: Chưa đúng với nội dung bài học: Khởi đầu phiên mã.","Hay nhầm: Chưa đúng với nội dung bài học: Khởi đầu phiên mã."],"q":{"n":20,"lv":{"Biết":6,"Hiểu":8,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 3. Điều hòa biểu hiện gene","sum":["Thí nghiệm của Monod và Jacob (thập niên 1950) trên E. coli: nuôi vi khuẩn trong môi trường có và không có lactose cùng amino acid đánh dấu phóng xạ.","Khái niệm: Thí nghiệm của Monod và Jacob (thập niên 1950) trên E. coli: nuôi vi khuẩn trong môi trường có và không có lactose cùng amino acid đánh dấu phóng xạ.","Cấu trúc operon lac: Vùng điều hoà gồm promoter (P, nơi RNA polymerase khởi động phiên mã) và operator (O, nơi protein ức chế liên kết); ba gene cấu trúc lacZ…","Ý nghĩa điều hoà biểu hiện gene: Tiết kiệm năng lượng (E. coli dùng tới 90% ATP để tổng hợp protein), giúp tế bào thích nghi môi trường (gene chống sốc nhiệt, kháng thể), và là cơ…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Thí nghiệm trên E. coli.","Hay nhầm: Chưa đúng với nội dung bài học: Thí nghiệm trên E. coli.","Hay nhầm: Chưa đúng với nội dung bài học: Thí nghiệm trên E. coli.","Hay nhầm: Chưa đúng với nội dung bài học: lacZ, lacY, lacA.","Hay nhầm: Chưa đúng với nội dung bài học: lacZ, lacY, lacA.","Hay nhầm: Chưa đúng với nội dung bài học: lacZ, lacY, lacA."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":3,"Nâng cao":2}}},{"t":"Bài 4. Đột biến gene","sum":["Đột biến gene là sự thay đổi trình tự nucleotide trong gene. Đột biến làm thay đổi một cặp nucleotide gọi là đột biến điểm.","Đột biến gene là sự thay đổi trình tự nucleotide trong gene: Đột biến làm thay đổi một cặp nucleotide gọi là đột biến điểm.","Nguyên nhân: Tự phát (phần nhiều do sai sót trong nhân đôi DNA) hoặc do tác nhân vật lí (tia UV, tia X, tia gamma), hóa học (5-bromouracil, HNO₃, EMS, acridine…","Vai trò: Trong nghiên cứu di truyền (tạo dòng đột biến, xác định tính trội/lặn, các gene; ví dụ bố mẹ cùng điếc bẩm sinh nhưng con bình thường chứng tỏ hai…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Thay thế, thêm hoặc mất một cặp.","Hay nhầm: Chưa đúng với nội dung bài học: Thay thế, thêm hoặc mất một cặp.","Hay nhầm: Chưa đúng với nội dung bài học: Thay thế, thêm hoặc mất một cặp."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 5. Công nghệ gene","sum":["Công nghệ gene là quy trình kĩ thuật sử dụng công nghệ DNA tái tổ hợp để thay đổi kiểu gene và kiểu hình của sinh vật, tạo ra các sản phẩm protein ứng dụng thực tiễn; gồm công nghệ DNA tái tổ hợp và…","Khái niệm: Công nghệ gene là quy trình kĩ thuật sử dụng công nghệ DNA tái tổ hợp để thay đổi kiểu gene và kiểu hình của sinh vật, tạo ra các sản phẩm protein…","Thành tựu của công nghệ DNA tái tổ hợp: Dược phẩm (năm 1979 công ty Eli Lilly bán insulin người sản xuất từ vi khuẩn: gene insulin người đã loại intron, gắn vào plasmid, chuyển vào vi…","Sinh vật biến đổi gene (chuyển gene)…: Sinh vật biến đổi gene (chuyển gene) là sinh vật có hệ gene được biến đổi, chủ yếu có thêm gene mới từ loài khác."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Gồm gene chuyển và vector.","Hay nhầm: Chưa đúng với nội dung bài học: Gồm gene chuyển và vector.","Hay nhầm: Chưa đúng với nội dung bài học: Gồm gene chuyển và vector.","Hay nhầm: Chưa đúng với nội dung bài học: Vector phải tái bản được.","Hay nhầm: Chưa đúng với nội dung bài học: Vector phải tái bản được.","Hay nhầm: Chưa đúng với nội dung bài học: Vector phải tái bản được."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 6. Thực hành: Tách chiết DNA","sum":["Mục tiêu: tách chiết DNA từ mẫu vật sống (gan gà, mô động vật, thực vật tươi). Nguyên liệu: gan gà (khoảng 5 g; mô thực vật khoảng 50 g), dứa tươi 1/4 quả, nước rửa chén 500 mL, cồn ethanol lạnh 70…","Mục tiêu: Tách chiết DNA từ mẫu vật sống (gan gà, mô động vật, thực vật tươi).","Nguyên lí: DNA ở trong nhân tế bào; nghiền mẫu để phá mô và thành tế bào; dung dịch tẩy rửa hòa tan lipid, phá màng tế bào, màng nhân; enzyme protease trong…","Cách tiến hành: B1: nghiền khoảng 5 g gan gà (xay 30 – 60 giây), thêm 150 mL nước lạnh, khuấy;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Dễ nghiền, giàu DNA.","Hay nhầm: Chưa đúng với nội dung bài học: Dễ nghiền, giàu DNA.","Hay nhầm: Chưa đúng với nội dung bài học: Dễ nghiền, giàu DNA.","Hay nhầm: Chưa đúng với nội dung bài học: DNA kết tụ thành khối trắng đục.","Hay nhầm: Chưa đúng với nội dung bài học: DNA kết tụ thành khối trắng đục.","Hay nhầm: Chưa đúng với nội dung bài học: DNA kết tụ thành khối trắng đục."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}}]},{"t":"Chương II. Di truyền nhiễm sắc thể","l":[{"t":"Bài 7. Cấu trúc và chức năng của nhiễm sắc thể","sum":["NST là cấu trúc trong nhân tế bào, dễ bắt màu thuốc nhuộm đặc hiệu với DNA; quan sát rõ nhất ở kì giữa, chia thành dạng tâm mút, tâm lệch, tâm giữa tùy vị trí tâm động.","Khái niệm: NST là cấu trúc trong nhân tế bào, dễ bắt màu thuốc nhuộm đặc hiệu với DNA; quan sát rõ nhất ở kì giữa, chia thành dạng tâm mút, tâm lệch, tâm giữa…","Chức năng: Mang thông tin di truyền."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Sợi cơ bản 10 nm.","Hay nhầm: Chưa đúng với nội dung bài học: Sợi cơ bản 10 nm.","Hay nhầm: Chưa đúng với nội dung bài học: Sợi cơ bản 10 nm.","Hay nhầm: Chưa đúng với nội dung bài học: Cùng locus trên cặp tương đồng có thể chứa các allele khác nhau.","Hay nhầm: Chưa đúng với nội dung bài học: Cùng locus trên cặp tương đồng có thể chứa các allele khác nhau.","Hay nhầm: Chưa đúng với nội dung bài học: Cùng locus trên cặp tương đồng có thể chứa các allele khác nhau."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 8. Học thuyết di truyền Mendel","sum":["Mendel (1822 – 1884) chọn đậu Hà Lan (Pisum sativum): tự thụ phấn, thế hệ ngắn, nhiều dòng thuần chủng, dễ lai, nhiều hạt.","Mendel (1822 – 1884) chọn đậu Hà Lan (Pisum sativum): Tự thụ phấn, thế hệ ngắn, nhiều dòng thuần chủng, dễ lai, nhiều hạt.","Quy luật phân li: Mỗi tính trạng do một cặp nhân tố di truyền quy định, một từ bố và một từ mẹ; khi hình thành giao tử, các nhân tố phân li về giao tử nên mỗi giao tử…","Lai hai tính trạng (vàng, trơn × xanh, nhăn): F1 100% vàng, trơn;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Pisum sativum.","Hay nhầm: Chưa đúng với nội dung bài học: Pisum sativum.","Hay nhầm: Chưa đúng với nội dung bài học: Pisum sativum.","Hay nhầm: Chưa đúng với nội dung bài học: Quy luật phân li.","Hay nhầm: Chưa đúng với nội dung bài học: Quy luật phân li.","Hay nhầm: Chưa đúng với nội dung bài học: Quy luật phân li."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":2}}},{"t":"Bài 9. Mở rộng học thuyết Mendel","sum":["Một gene có thể có nhiều hơn hai allele và quy định nhiều tính trạng; một tính trạng cũng có thể do nhiều gene quy định.","Khái niệm: Một gene có thể có nhiều hơn hai allele và quy định nhiều tính trạng; một tính trạng cũng có thể do nhiều gene quy định.","Tương tác giữa các gene khác nhau: Tương tác gián tiếp theo kiểu át chế (ví dụ hai gene quy định enzyme trong con đường chuyển hóa tạo màu vỏ ốc nâu; chỉ cần một gene mất chức năng…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Ví dụ hoa mõm chó.","Hay nhầm: Chưa đúng với nội dung bài học: Ví dụ hoa mõm chó.","Hay nhầm: Chưa đúng với nội dung bài học: Ví dụ hoa mõm chó.","Hay nhầm: Chưa đúng với nội dung bài học: Biểu hiện cả hai kháng nguyên A và B.","Hay nhầm: Chưa đúng với nội dung bài học: Biểu hiện cả hai kháng nguyên A và B.","Hay nhầm: Chưa đúng với nội dung bài học: Biểu hiện cả hai kháng nguyên A và B."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 10. Di truyền giới tính và di truyền liên kết với giới tính","sum":["NST giới tính là NST mang gene quy định giới tính (và cả gene không quy định giới tính); có thể tồn tại thành cặp tương đồng hoặc không tương đồng.","Khái niệm: NST giới tính là NST mang gene quy định giới tính (và cả gene không quy định giới tính); có thể tồn tại thành cặp tương đồng hoặc không tương đồng.","Di truyền liên kết với giới tính…: Di truyền liên kết với giới tính là sự di truyền tính trạng do gene nằm trên NST giới tính.","Ứng dụng: Phân biệt sớm giới tính vật nuôi nhờ tính trạng liên kết giới tính (màu trứng tằm để chọn tằm đực cho nhiều tơ), chuyển gene kháng thuốc sang NST Y…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Nữ là XX.","Hay nhầm: Chưa đúng với nội dung bài học: Nữ là XX.","Hay nhầm: Chưa đúng với nội dung bài học: Nữ là XX.","Hay nhầm: Chưa đúng với nội dung bài học: Nằm trên Y.","Hay nhầm: Chưa đúng với nội dung bài học: Nằm trên Y.","Hay nhầm: Chưa đúng với nội dung bài học: Nằm trên Y."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 11. Liên kết gene và hoán vị gene","sum":["Năm 1905 Bateson, Saunders và Punnett nghiên cứu đậu ngọt thu được tỉ lệ F2 khác 9 : 3 : 3 : 1.","Khái niệm: Năm 1905 Bateson, Saunders và Punnett nghiên cứu đậu ngọt thu được tỉ lệ F2 khác 9 : 3 : 3 : 1.","Hoán vị gene: Lai phân tích F1 dị hợp (thân xám, cánh dài) cho đời con có 41,5% xám, dài;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Phát hiện bởi Morgan.","Hay nhầm: Chưa đúng với nội dung bài học: Phát hiện bởi Morgan.","Hay nhầm: Chưa đúng với nội dung bài học: Phát hiện bởi Morgan.","Hay nhầm: Chưa đúng với nội dung bài học: Thân xám/đen, cánh dài/cụt.","Hay nhầm: Chưa đúng với nội dung bài học: Thân xám/đen, cánh dài/cụt.","Hay nhầm: Chưa đúng với nội dung bài học: Thân xám/đen, cánh dài/cụt."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 12. Đột biến nhiễm sắc thể","sum":["Đột biến NST là những biến đổi về cấu trúc hoặc số lượng NST. Đột biến cấu trúc: mất đoạn, lặp đoạn, đảo đoạn, chuyển đoạn.","Đột biến NST là những biến đổi về cấu trúc hoặc số lượng NST: Đột biến cấu trúc: mất đoạn, lặp đoạn, đảo đoạn, chuyển đoạn.","Đột biến cấu trúc: Do tác nhân vật lí, hóa học (tia X, tia gamma làm đứt gãy hai mạch DNA rồi nối lại bất thường hoặc không nối) hoặc trao đổi chéo giữa các đoạn tương…","Đột biến lệch bội: Do rối loạn phân li của một hoặc vài cặp NST trong giảm phân tạo giao tử lệch bội (n+1, n−1); tạo thể ba (2n+1), thể một (2n−1), thể không (2n−2).","Vai trò: Trong tiến hóa (lặp đoạn tạo họ gene hemoglobin; chuyển đoạn dung hợp hai NST tạo NST số 2 người nên người 46 NST còn tinh tinh 48 NST;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Hai nhóm.","Hay nhầm: Chưa đúng với nội dung bài học: Hai nhóm.","Hay nhầm: Chưa đúng với nội dung bài học: Hai nhóm.","Hay nhầm: Chưa đúng với nội dung bài học: Dạng cấu trúc.","Hay nhầm: Chưa đúng với nội dung bài học: Dạng cấu trúc.","Hay nhầm: Chưa đúng với nội dung bài học: Dạng cấu trúc."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 13. Di truyền học người và di truyền y học","sum":["Di truyền học người nghiên cứu sự di truyền và biến dị ở người; di truyền y học nghiên cứu cơ chế phát sinh và di truyền của các bệnh, đề xuất biện pháp phòng tránh và chữa trị bệnh di truyền.","Khái niệm: Di truyền học người nghiên cứu sự di truyền và biến dị ở người; di truyền y học nghiên cứu cơ chế phát sinh và di truyền của các bệnh, đề xuất biện…","Phương pháp di truyền tế bào: Nghiên cứu số lượng, hình dạng, kích thước NST; nuôi cấy bạch cầu, dùng colchicine làm tế bào dừng ở kì giữa, làm tiêu bản quan sát và lập NST đồ;…","Y học tư vấn (di truyền học…: Y học tư vấn (di truyền học tư vấn) cung cấp thông tin cho người có nguy cơ mắc hoặc sinh con mắc bệnh di truyền.","Liệu pháp gene là chữa bệnh di…: Liệu pháp gene là chữa bệnh di truyền bằng cách thay gene bệnh bằng gene bình thường hoặc chỉnh sửa gene bệnh."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Phả hệ là sơ đồ lai tự nhiên.","Hay nhầm: Chưa đúng với nội dung bài học: Phả hệ là sơ đồ lai tự nhiên.","Hay nhầm: Chưa đúng với nội dung bài học: Phả hệ là sơ đồ lai tự nhiên.","Hay nhầm: Chưa đúng với nội dung bài học: Nữ là hình tròn.","Hay nhầm: Chưa đúng với nội dung bài học: Nữ là hình tròn.","Hay nhầm: Chưa đúng với nội dung bài học: Nữ là hình tròn."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 14. Thực hành: Quan sát một số dạng đột biến nhiễm sắc thể","sum":["Mục tiêu: quan sát đột biến NST trên tiêu bản cố định. Dụng cụ: kính hiển vi, dầu soi kính, giấy lau, ảnh bộ NST bình thường và đột biến.","Mục tiêu: Quan sát đột biến NST trên tiêu bản cố định.","Các bước: B1 đặt tiêu bản, đưa vùng có mẫu vào giữa trường;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Vật kính dầu.","Hay nhầm: Chưa đúng với nội dung bài học: Vật kính dầu.","Hay nhầm: Chưa đúng với nội dung bài học: Vật kính dầu.","Hay nhầm: Chưa đúng với nội dung bài học: Bước 2.","Hay nhầm: Chưa đúng với nội dung bài học: Bước 2.","Hay nhầm: Chưa đúng với nội dung bài học: Bước 2."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương III. Mở rộng học thuyết di truyền nhiễm sắc thể","l":[{"t":"Bài 15. Di truyền gene ngoài nhân","sum":["Năm 1900 De Vries, Tschermak và Correns độc lập xác nhận kết quả của Mendel. Năm 1909 Correns phát hiện ở cây hoa bốn giờ (Mirabilis jalapa) có ba loại cành: lá xanh, lá trắng, lá khảm.","Khái niệm: Năm 1900 De Vries, Tschermak và Correns độc lập xác nhận kết quả của Mendel.","Đặc điểm: Kết quả lai thuận nghịch khác nhau, di truyền theo dòng mẹ, biểu hiện ở cả hai giới; vai trò chủ yếu thuộc tế bào chất của giao tử cái; gene nằm…","Ứng dụng: Y học (bệnh cơ ti thể, tiểu đường, tim mạch, Alzheimer, Leigh do gene ti thể; năm 2016 ở Mexico kĩ thuật loại trừ gene bệnh ti thể giúp người mẹ…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Mirabilis jalapa.","Hay nhầm: Chưa đúng với nội dung bài học: Mirabilis jalapa.","Hay nhầm: Chưa đúng với nội dung bài học: Mirabilis jalapa.","Hay nhầm: Chưa đúng với nội dung bài học: DNA vòng nhỏ.","Hay nhầm: Chưa đúng với nội dung bài học: DNA vòng nhỏ.","Hay nhầm: Chưa đúng với nội dung bài học: DNA vòng nhỏ."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 16. Tương tác giữa kiểu gene với môi trường và thành tựu chọn giống","sum":["Kiểu gene tương tác với môi trường quy định kiểu hình: gene chỉ dẫn tạo protein, môi trường cung cấp nguyên liệu, năng lượng và tín hiệu điều hòa biểu hiện gene.","Kiểu gene tương tác với môi trường quy định kiểu hình: Gene chỉ dẫn tạo protein, môi trường cung cấp nguyên liệu, năng lượng và tín hiệu điều hòa biểu hiện gene.","Vận dụng mức phản ứng: Y học (phenylketone niệu do gene lặn trên NST thường, kiêng phenylalanine từ sớm thì giảm triệu chứng); nông nghiệp (kiểu gene = giống, môi trường =…","Chọn, tạo giống bằng lai hữu tính: Giống cây trồng là quần thể phân biệt được, đồng nhất, ổn định, có giá trị canh tác và sử dụng; giống vật nuôi là quần thể cùng loài, cùng nguồn…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Không di truyền.","Hay nhầm: Chưa đúng với nội dung bài học: Không di truyền.","Hay nhầm: Chưa đúng với nội dung bài học: Không di truyền."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 17. Thực hành: Thí nghiệm về thường biến ở cây trồng","sum":["Thường biến là biến đổi kiểu hình dưới tác động trực tiếp của môi trường mà không đổi kiểu gene.","Khái niệm: Thường biến là biến đổi kiểu hình dưới tác động trực tiếp của môi trường mà không đổi kiểu gene.","Cách tiến hành với rau muống: Chuẩn bị 2 luống (đối chứng và thực nghiệm) cao 20 – 30 cm, rộng 1 m, dài 1,5 m, cách nhau 1 m, bón lót 7 – 10 ngày trước trồng."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Không di truyền.","Hay nhầm: Chưa đúng với nội dung bài học: Không di truyền.","Hay nhầm: Chưa đúng với nội dung bài học: Không di truyền.","Hay nhầm: Chưa đúng với nội dung bài học: Nhân giống vô tính.","Hay nhầm: Chưa đúng với nội dung bài học: Nhân giống vô tính.","Hay nhầm: Chưa đúng với nội dung bài học: Nhân giống vô tính."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương IV. Di truyền quần thể","l":[{"t":"Bài 18. Di truyền học quần thể","sum":["Quần thể (góc độ di truyền học) là tập hợp các cá thể cùng loài, có khả năng giao phối với nhau, sống trong cùng khu vực địa lí ở cùng một thời điểm.","Khái niệm: Quần thể (góc độ di truyền học) là tập hợp các cá thể cùng loài, có khả năng giao phối với nhau, sống trong cùng khu vực địa lí ở cùng một thời điểm.","Ví dụ: Quần thể ruồi giấm 200 con, 80 BB, 70 Bb, 50 bb: tổng allele 400; tần số B = (80×2 + 70)/400 = 0,575; b = (50×2 + 70)/400 = 0,425; tần số kiểu gene…","Quần thể ngẫu phối: Các cá thể giao phối hoàn toàn ngẫu nhiên, đa dạng di truyền cao; gene lặn có hại ít trở về đồng hợp.","Quần thể tự thụ phấn, giao phối gần: Nhiều cá thể đồng hợp, ít dị hợp, kém đa dạng."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Với p + q = 1.","Hay nhầm: Chưa đúng với nội dung bài học: Với p + q = 1.","Hay nhầm: Chưa đúng với nội dung bài học: Với p + q = 1."],"q":{"n":20,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":8,"Nâng cao":1}}}]},{"t":"Chương V. Bằng chứng và các học thuyết tiến hóa","l":[{"t":"Bài 19. Các bằng chứng tiến hóa","sum":["Bằng chứng tiến hóa là chứng cứ thu được từ nghiên cứu về sự phát sinh, phát triển của các loài trên Trái Đất.","Khái niệm: Bằng chứng tiến hóa là chứng cứ thu được từ nghiên cứu về sự phát sinh, phát triển của các loài trên Trái Đất.","Bằng chứng giải phẫu so sánh: Cấu trúc tương đồng (cùng thừa hưởng gene từ tổ tiên chung, như xương chi trước của người, mèo, cá voi, ngựa, dơi, chim; hươu cao cổ cũng có 7 đốt…","Bằng chứng tế bào học: Mọi sinh vật cấu tạo từ tế bào, có màng tế bào, nhân/vùng nhân, tế bào chất, chuyển hóa cơ bản giống nhau."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Cho thấy tiến hóa theo thời gian.","Hay nhầm: Chưa đúng với nội dung bài học: Cho thấy tiến hóa theo thời gian.","Hay nhầm: Chưa đúng với nội dung bài học: Cho thấy tiến hóa theo thời gian.","Hay nhầm: Chưa đúng với nội dung bài học: Trong hóa thạch hoặc đá bao quanh.","Hay nhầm: Chưa đúng với nội dung bài học: Trong hóa thạch hoặc đá bao quanh.","Hay nhầm: Chưa đúng với nội dung bài học: Trong hóa thạch hoặc đá bao quanh."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 20. Quan niệm của Darwin về chọn lọc tự nhiên và hình thành loài","sum":["Phương pháp Darwin: quan sát thu thập dữ liệu, hình thành giả thuyết giải thích dữ liệu, kiểm chứng giả thuyết bằng thực nghiệm.","Phương pháp Darwin: Quan sát thu thập dữ liệu, hình thành giả thuyết giải thích dữ liệu, kiểm chứng giả thuyết bằng thực nghiệm.","Quan sát chọn lọc nhân tạo: Con người giữ lại biến dị ưa thích, nhân giống riêng, qua một số thế hệ tạo giống mới (các giống bồ câu từ bồ câu núi; bắp cải, su hào, súp lơ,...…","Kiểm chứng: Darwin ngâm hạt trong nước biển lâu ngày vẫn nảy mầm, chứng tỏ cây đảo phát tán từ đất liền; thí nghiệm với cây nắp ấm cho thấy chỉ tiêu thụ…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Rời nước Anh năm 1831.","Hay nhầm: Chưa đúng với nội dung bài học: Rời nước Anh năm 1831.","Hay nhầm: Chưa đúng với nội dung bài học: Rời nước Anh năm 1831.","Hay nhầm: Chưa đúng với nội dung bài học: Mô hình nghiên cứu hiện đại.","Hay nhầm: Chưa đúng với nội dung bài học: Mô hình nghiên cứu hiện đại.","Hay nhầm: Chưa đúng với nội dung bài học: Mô hình nghiên cứu hiện đại."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 21. Học thuyết tiến hóa tổng hợp hiện đại","sum":["Thuyết tiến hóa tổng hợp ra đời vào những năm 1930 khi kết hợp thuyết chọn lọc tự nhiên của Darwin với di truyền học hiện đại.","Khái niệm: Thuyết tiến hóa tổng hợp ra đời vào những năm 1930 khi kết hợp thuyết chọn lọc tự nhiên của Darwin với di truyền học hiện đại.","Đột biến: Tạo allele mới, làm phong phú vốn gene, nguyên liệu tiến hóa (tần số đột biến thấp).","Đặc điểm thích nghi: Đặc điểm di truyền làm tăng khả năng sống sót và sinh sản trong môi trường nhất định; mức thích nghi đo bằng giá trị thích nghi (số con sống sót đến…","Loài sinh học (Ernst Mayr): Một hoặc nhóm quần thể gồm các cá thể giao phối với nhau trong tự nhiên sinh con hữu thụ nhưng cách li sinh sản với nhóm quần thể khác."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Tần số allele thay đổi ở quy mô quần thể.","Hay nhầm: Chưa đúng với nội dung bài học: Tần số allele thay đổi ở quy mô quần thể.","Hay nhầm: Chưa đúng với nội dung bài học: Tần số allele thay đổi ở quy mô quần thể.","Hay nhầm: Chưa đúng với nội dung bài học: Tăng đồng hợp.","Hay nhầm: Chưa đúng với nội dung bài học: Tăng đồng hợp.","Hay nhầm: Chưa đúng với nội dung bài học: Tăng đồng hợp."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 22. Tiến hóa lớn và quá trình phát sinh chủng loại","sum":["Tiến hóa lớn là quá trình hình thành các loài và các đơn vị phân loại trên loài ở quy mô lớn, dẫn đến hình thành toàn bộ sinh giới; khác với tiến hóa nhỏ (quy mô quần thể, thay đổi tần số allele).","Khái niệm: Tiến hóa lớn là quá trình hình thành các loài và các đơn vị phân loại trên loài ở quy mô lớn, dẫn đến hình thành toàn bộ sinh giới; khác với tiến…","Tiến hóa hóa học: Hình thành hợp chất hữu cơ từ chất vô cơ cách đây hơn bốn tỉ năm.","Tiến hóa tiền sinh học (4,2 – 3,8 tỉ năm trước): Hình thành tế bào sơ khai; phospholipid tạo màng bao các phân tử hữu cơ thành protobiont (siêu giọt), nếu tăng kích thước, chuyển hóa, phân đôi thì…","Các đại địa chất: Proterozoic (Nguyên sinh, 2500 – 541 triệu năm; nhân thực xuất hiện, tích lũy oxygen từ quang hợp cách đây 2,5 tỉ năm), Cambrian (541 – 485: bùng nổ…","Phát sinh loài người: Giai đoạn Ardipithecus (Ardipithecus ramidus phát hiện năm 1994 ở Ethiopia, khoảng 4,4 triệu năm, đi thẳng, leo trèo giỏi); giai đoạn…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Theo trình tự thời gian.","Hay nhầm: Chưa đúng với nội dung bài học: Theo trình tự thời gian.","Hay nhầm: Chưa đúng với nội dung bài học: Theo trình tự thời gian.","Hay nhầm: Chưa đúng với nội dung bài học: Những năm 1950.","Hay nhầm: Chưa đúng với nội dung bài học: Những năm 1950.","Hay nhầm: Chưa đúng với nội dung bài học: Những năm 1950."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}}]},{"t":"Chương VI. Môi trường và sinh thái học quần thể","l":[{"t":"Bài 23. Môi trường và các nhân tố sinh thái","sum":["Môi trường sống là tất cả các nhân tố xung quanh sinh vật, ảnh hưởng đến sự tồn tại, sinh trưởng, phát triển của sinh vật; là nơi sinh vật thu nhận nguồn sống và chứa chất thải.","Khái niệm: Môi trường sống là tất cả các nhân tố xung quanh sinh vật, ảnh hưởng đến sự tồn tại, sinh trưởng, phát triển của sinh vật; là nơi sinh vật thu nhận…","Nhân tố sinh thái là nhân tố…: Nhân tố sinh thái là nhân tố môi trường tác động trực tiếp hoặc gián tiếp đến sinh vật.","Các quy luật sinh thái: Quy luật giới hạn sinh thái (khoảng giá trị của nhân tố sinh thái mà sinh vật tồn tại và phát triển ổn định, gồm khoảng thuận lợi và khoảng ức chế,…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Khái niệm.","Hay nhầm: Chưa đúng với nội dung bài học: Cộng sinh, kí sinh, vật ăn thịt – con mồi.","Hay nhầm: Chưa đúng với nội dung bài học: Cộng sinh, kí sinh, vật ăn thịt – con mồi.","Hay nhầm: Chưa đúng với nội dung bài học: Cộng sinh, kí sinh, vật ăn thịt – con mồi."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 24. Sinh thái học quần thể","sum":["Quần thể là tập hợp các cá thể cùng loài, cùng sống trong một khoảng không gian và thời gian xác định, có khả năng sinh sản tạo thế hệ mới.","Khái niệm: Quần thể là tập hợp các cá thể cùng loài, cùng sống trong một khoảng không gian và thời gian xác định, có khả năng sinh sản tạo thế hệ mới.","Đặc trưng cơ bản: Mật độ cá thể (số cá thể trên đơn vị diện tích hoặc thể tích); kích thước quần thể (số lượng cá thể, sinh khối hoặc năng lượng), có kích thước tối…","Tăng trưởng quần thể: Theo tiềm năng sinh học (điều kiện lí tưởng, đường cong chữ J) và trong môi trường có giới hạn (đường cong chữ S, dao động quanh sức chứa).","Biến động số lượng: Theo chu kì (thực vật nổi tăng ban ngày; mèo rừng và thỏ rừng Canada chu kì 9 – 10 năm;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Mỗi cá thể có thêm thuận lợi.","Hay nhầm: Chưa đúng với nội dung bài học: Mỗi cá thể có thêm thuận lợi.","Hay nhầm: Chưa đúng với nội dung bài học: Mỗi cá thể có thêm thuận lợi.","Hay nhầm: Chưa đúng với nội dung bài học: Nguồn sống vô hạn.","Hay nhầm: Chưa đúng với nội dung bài học: Nguồn sống vô hạn.","Hay nhầm: Chưa đúng với nội dung bài học: Nguồn sống vô hạn."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":1}}},{"t":"Bài 25. Thực hành: Xác định một số đặc trưng của quần thể","sum":["Mục tiêu: ước tính kích thước và mật độ quần thể ở loài thực vật hoặc động vật ít di chuyển (giun đất, ốc, cua, sò).","Mục tiêu: Ước tính kích thước và mật độ quần thể ở loài thực vật hoặc động vật ít di chuyển (giun đất, ốc, cua, sò).","Phương pháp ô vuông (quadrat): Xác định khu vực phân bố, lập bản đồ chia ô và đánh số, chọn ngẫu nhiên các vị trí lấy mẫu;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Đặt ô vuông ngẫu nhiên.","Hay nhầm: Chưa đúng với nội dung bài học: Đặt ô vuông ngẫu nhiên.","Hay nhầm: Chưa đúng với nội dung bài học: Đặt ô vuông ngẫu nhiên.","Hay nhầm: Chưa đúng với nội dung bài học: Kích thước phù hợp đối tượng.","Hay nhầm: Chưa đúng với nội dung bài học: Kích thước phù hợp đối tượng.","Hay nhầm: Chưa đúng với nội dung bài học: Kích thước phù hợp đối tượng."],"q":{"n":13,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":5,"Nâng cao":1}}}]},{"t":"Chương VII. Sinh thái học quần xã và hệ sinh thái","l":[{"t":"Bài 26. Quần xã sinh vật","sum":["Quần xã sinh vật gồm các quần thể của nhiều loài khác nhau, cùng sống trong một không gian, thời gian nhất định, gắn bó như một thể thống nhất qua quan hệ dinh dưỡng và nơi ở.","Khái niệm: Quần xã sinh vật gồm các quần thể của nhiều loài khác nhau, cùng sống trong một không gian, thời gian nhất định, gắn bó như một thể thống nhất qua…","Đặc trưng cơ bản: Thành phần loài (số loài, loài ưu thế có số lượng hoặc sinh khối lớn nhất; loài đặc trưng chỉ có hoặc tập trung ở một sinh cảnh, như đước, sú, vẹt;…","Quan hệ giữa các loài: Cộng sinh (cả hai có lợi, bắt buộc: địa y, vi khuẩn phân giải cellulose trong ruột động vật ăn cỏ); hợp tác (cả hai có lợi nhưng không bắt buộc:…","Tác động của con người: Thành lập vườn quốc gia, trồng rừng là tích cực."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Gắn bó quan hệ dinh dưỡng, nơi ở.","Hay nhầm: Chưa đúng với nội dung bài học: Gắn bó quan hệ dinh dưỡng, nơi ở.","Hay nhầm: Chưa đúng với nội dung bài học: Gắn bó quan hệ dinh dưỡng, nơi ở.","Hay nhầm: Chưa đúng với nội dung bài học: Ảnh hưởng lớn đến cấu trúc quần xã.","Hay nhầm: Chưa đúng với nội dung bài học: Ảnh hưởng lớn đến cấu trúc quần xã.","Hay nhầm: Chưa đúng với nội dung bài học: Ảnh hưởng lớn đến cấu trúc quần xã."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 27. Thực hành: Tìm hiểu một số đặc trưng cơ bản của quần xã","sum":["Yêu cầu: xác định các nhóm loài sinh vật trong quần xã và tìm hiểu cấu trúc dinh dưỡng. Dụng cụ: thước dây, xẻng, vợt thu mẫu động vật, máy ảnh hoặc điện thoại, giấy bút.","Yêu cầu: Xác định các nhóm loài sinh vật trong quần xã và tìm hiểu cấu trúc dinh dưỡng.","Cách tiến hành: B1 xác định quần xã;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Các quần xã tương đối ổn định.","Hay nhầm: Chưa đúng với nội dung bài học: Các quần xã tương đối ổn định.","Hay nhầm: Chưa đúng với nội dung bài học: Các quần xã tương đối ổn định.","Hay nhầm: Chưa đúng với nội dung bài học: Bảng 27.1.","Hay nhầm: Chưa đúng với nội dung bài học: Bảng 27.1.","Hay nhầm: Chưa đúng với nội dung bài học: Bảng 27.1."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 28. Hệ sinh thái","sum":["Hệ sinh thái là một cấp độ tổ chức sống gồm quần xã sinh vật và sinh cảnh, trong đó các thành phần tác động qua lại và gắn bó như một thể thống nhất tương đối ổn định.","Khái niệm: Hệ sinh thái là một cấp độ tổ chức sống gồm quần xã sinh vật và sinh cảnh, trong đó các thành phần tác động qua lại và gắn bó như một thể thống nhất…","Hệ sinh thái tự nhiên: Hình thành tự nhiên, ít hoặc không có can thiệp của con người (rừng mưa nhiệt đới, rừng ngập mặn, rạn san hô); số loài lớn, tính ổn định cao, dùng…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Tác động qua lại thành một thể thống nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Tác động qua lại thành một thể thống nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Tác động qua lại thành một thể thống nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Toàn bộ sự sống.","Hay nhầm: Chưa đúng với nội dung bài học: Toàn bộ sự sống.","Hay nhầm: Chưa đúng với nội dung bài học: Toàn bộ sự sống."],"q":{"n":14,"lv":{"Biết":5,"Hiểu":4,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 29. Trao đổi vật chất và chuyển hóa năng lượng trong hệ sinh thái","sum":["Năng lượng cung cấp cho sinh vật chủ yếu từ ánh sáng Mặt Trời. Trong hệ sinh thái, năng lượng chuyển hóa một chiều (đầu vào quang năng, đầu ra nhiệt năng), vật chất tuần hoàn (vô cơ → hữu cơ → vô cơ).","Khái niệm: Năng lượng cung cấp cho sinh vật chủ yếu từ ánh sáng Mặt Trời.","Chuỗi thức ăn là dãy loài có…: Chuỗi thức ăn là dãy loài có quan hệ dinh dưỡng, mỗi loài là một mắt xích; có hai loại: khởi đầu bằng sinh vật sản xuất và khởi đầu bằng sinh vật ăn…","Dòng năng lượng: Khoảng 50% bức xạ mặt trời bị mây, bụi hấp thụ, tán xạ, phản xạ; trong ánh sáng nhìn thấy chiếu xuống mặt đất chỉ khoảng 1% được sinh vật sản xuất…","Tháp sinh thái gồm các hình chữ…: Tháp sinh thái gồm các hình chữ nhật chồng lên nhau, đáy là bậc dinh dưỡng 1: tháp số lượng (có thể dạng ngược), tháp sinh khối (có thể ngược), tháp…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Còn vật chất tuần hoàn.","Hay nhầm: Chưa đúng với nội dung bài học: Còn vật chất tuần hoàn.","Hay nhầm: Chưa đúng với nội dung bài học: Còn vật chất tuần hoàn.","Hay nhầm: Chưa đúng với nội dung bài học: Mắt xích thứ nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Mắt xích thứ nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Mắt xích thứ nhất."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 30. Diễn thế sinh thái","sum":["Diễn thế sinh thái là quá trình thay đổi dần thành phần loài của quần xã theo thời gian, tương ứng với biến đổi của môi trường; gồm quần xã tiên phong (giai đoạn đầu), quần xã trung gian (giai đoạn…","Khái niệm: Diễn thế sinh thái là quá trình thay đổi dần thành phần loài của quần xã theo thời gian, tương ứng với biến đổi của môi trường; gồm quần xã tiên…","Hai loại diễn thế: Diễn thế nguyên sinh bắt đầu từ môi trường trống trơn, không có đất mùn và sinh vật (nham thạch nguội, đá sau tan băng), quần xã tiên phong là vi…","Nguyên nhân: Bên ngoài (núi lửa, cháy rừng, hạn hán, lũ lụt, khai thác mỏ, xả thải; ví dụ cháy rừng U Minh Thượng 2002, mỏ than Quảng Ninh) và bên trong (quan hệ…","Một số hiện tượng ảnh hưởng hệ sinh thái: Phì dưỡng (nước thừa nitrogen, phosphorus làm vi khuẩn lam, tảo phát triển quá mức, cạn oxygen, cá tôm chết; do phân bón dư, nước thải sinh hoạt,…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Gắn với biến đổi môi trường.","Hay nhầm: Chưa đúng với nội dung bài học: Gắn với biến đổi môi trường.","Hay nhầm: Chưa đúng với nội dung bài học: Gắn với biến đổi môi trường.","Hay nhầm: Chưa đúng với nội dung bài học: Giai đoạn cuối.","Hay nhầm: Chưa đúng với nội dung bài học: Giai đoạn cuối.","Hay nhầm: Chưa đúng với nội dung bài học: Giai đoạn cuối."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 31. Sinh quyển, khu sinh học và chu trình sinh – địa – hóa","sum":["Sinh quyển là cấp tổ chức sống lớn nhất, gồm toàn bộ các hệ sinh thái trên Trái Đất, gắn kết với nhau qua các nhân tố vô sinh; là hệ sinh thái lớn nhất có khả năng tự điều chỉnh, trạng thái cân bằng…","Khái niệm: Sinh quyển là cấp tổ chức sống lớn nhất, gồm toàn bộ các hệ sinh thái trên Trái Đất, gắn kết với nhau qua các nhân tố vô sinh; là hệ sinh thái lớn…","Rừng nhiệt đới: Nhiệt độ trung bình 25 – 29 °C; rừng mưa nhiệt đới mưa khoảng 2 000 – 4 000 mm/năm, nhiều tầng, cây lá rộng thường xanh, nhiều dây leo; rừng cận…","Bảo vệ sinh quyển: Giảm tác động có hại (giảm tiêu thụ nguyên liệu, tiết kiệm, tái chế, năng lượng tái tạo, giảm khí nhà kính, xử lí rác thải) và bảo tồn, cải tạo…","Chu trình sinh – địa – hóa…: Chu trình sinh – địa – hóa là sự tuần hoàn của các nguyên tố (C, N, P, Ca, S) giữa sinh vật và môi trường."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Gồm mọi hệ sinh thái.","Hay nhầm: Chưa đúng với nội dung bài học: Gồm mọi hệ sinh thái.","Hay nhầm: Chưa đúng với nội dung bài học: Gồm mọi hệ sinh thái.","Hay nhầm: Chưa đúng với nội dung bài học: Phân bố theo vĩ độ, độ khô hạn.","Hay nhầm: Chưa đúng với nội dung bài học: Phân bố theo vĩ độ, độ khô hạn.","Hay nhầm: Chưa đúng với nội dung bài học: Phân bố theo vĩ độ, độ khô hạn."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 32. Thực hành: Thiết kế một hệ sinh thái nhân tạo","sum":["Yêu cầu: thiết kế bể nuôi cá cảnh vận dụng hiểu biết về hệ sinh thái. Chuẩn bị: giấy A0, bút dạ, bể cá, xô, rổ rá rửa cát sỏi, cát, sỏi, vật trang trí, máy sục oxygen, máy lọc nước; mẫu vật: thực…","Yêu cầu: Thiết kế bể nuôi cá cảnh vận dụng hiểu biết về hệ sinh thái.","Quy trình 9 bước: Thiết kế cấu tạo bể; rửa sạch cát sỏi, rải làm nền; cho nước sạch; lắp sục oxygen và máy lọc nước; lắp vật trang trí; bố trí thực vật thủy sinh; thả…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Từ thiết kế đến theo dõi.","Hay nhầm: Chưa đúng với nội dung bài học: Từ thiết kế đến theo dõi.","Hay nhầm: Chưa đúng với nội dung bài học: Từ thiết kế đến theo dõi.","Hay nhầm: Chưa đúng với nội dung bài học: Quang hợp.","Hay nhầm: Chưa đúng với nội dung bài học: Quang hợp.","Hay nhầm: Chưa đúng với nội dung bài học: Quang hợp."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương VIII. Sinh thái học phục hồi, bảo tồn và phát triển bền vững","l":[{"t":"Bài 33. Sinh thái học phục hồi và bảo tồn đa dạng sinh vật","sum":["Sinh thái học phục hồi là khoa học ứng dụng nguyên lí sinh thái để đưa hệ sinh thái bị suy thoái về trạng thái gần nhất với tự nhiên; phục hồi là hoạt động có chủ đích khôi phục sức khỏe, tính toàn…","Khái niệm: Sinh thái học phục hồi là khoa học ứng dụng nguyên lí sinh thái để đưa hệ sinh thái bị suy thoái về trạng thái gần nhất với tự nhiên; phục hồi là…","Cần bảo tồn và phục hồi vì…: Cần bảo tồn và phục hồi vì giá trị rất lớn của hệ sinh thái (hàng nghìn tỉ đô la mỗi năm): giá trị trực tiếp (nước, dược liệu, nguồn gene, vật liệu,…","Phương pháp phục hồi: Cải tạo sinh học (loại bỏ yếu tố gây hại: chất thải, kim loại nặng, loài ngoại lai; ví dụ vi sinh Shewanella oneidensis hấp thụ uranium, bèo hoa dâu…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Khôi phục tính toàn vẹn.","Hay nhầm: Chưa đúng với nội dung bài học: Khôi phục tính toàn vẹn.","Hay nhầm: Chưa đúng với nội dung bài học: Khôi phục tính toàn vẹn.","Hay nhầm: Chưa đúng với nội dung bài học: Tại chỗ và ngoài nơi cư trú.","Hay nhầm: Chưa đúng với nội dung bài học: Tại chỗ và ngoài nơi cư trú.","Hay nhầm: Chưa đúng với nội dung bài học: Tại chỗ và ngoài nơi cư trú."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 34. Phát triển bền vững","sum":["Theo Liên hợp quốc (1987), phát triển bền vững là sự phát triển đáp ứng nhu cầu hiện tại mà không làm tổn hại khả năng đáp ứng nhu cầu của các thế hệ tương lai.","Khái niệm: Theo Liên hợp quốc (1987), phát triển bền vững là sự phát triển đáp ứng nhu cầu hiện tại mà không làm tổn hại khả năng đáp ứng nhu cầu của các thế…","Nông nghiệp bền vững: Canh tác đáp ứng nhu cầu lương thực, thực phẩm hiện tại mà không ảnh hưởng nhu cầu của thế hệ sau; tôn trọng môi trường, bảo đảm thu nhập công bằng…","Biện pháp hạn chế ô nhiễm: Giáo dục và khuyến khích (tiêu chuẩn VietGAP, ISO, nhãn sinh thái, truyền thông), ngăn ngừa (Luật Bảo vệ môi trường, quy chuẩn xả thải, đánh giá tác…","Chính sách dân số: Dân số tăng nhanh gây sức ép về việc làm, lương thực, y tế, giáo dục; ba nhóm chính sách là duy trì ổn định, gia tăng, hạn chế gia tăng; mức sinh…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Phát triển cân đối.","Hay nhầm: Chưa đúng với nội dung bài học: Phát triển cân đối.","Hay nhầm: Chưa đúng với nội dung bài học: Phát triển cân đối.","Hay nhầm: Chưa đúng với nội dung bài học: Do Liên hợp quốc phát động.","Hay nhầm: Chưa đúng với nội dung bài học: Do Liên hợp quốc phát động.","Hay nhầm: Chưa đúng với nội dung bài học: Do Liên hợp quốc phát động."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 35. Dự án: Tìm hiểu thực trạng bảo tồn và phục hồi hệ sinh thái tại địa phương","sum":["Mục tiêu: rèn kĩ năng làm việc nhóm, lập kế hoạch, quan sát, phỏng vấn hiện trường; viết và trình bày báo cáo; củng cố kiến thức bảo tồn và phục hồi sinh thái.","Mục tiêu: Rèn kĩ năng làm việc nhóm, lập kế hoạch, quan sát, phỏng vấn hiện trường; viết và trình bày báo cáo; củng cố kiến thức bảo tồn và phục hồi sinh thái.","Các bước: Lập kế hoạch (chọn chủ đề, phân công nhóm trưởng và thành viên, bảng kế hoạch gồm thời gian, hoạt động, địa điểm, người thực hiện, sản phẩm, công…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Công nhận Vườn Quốc gia năm 2003.","Hay nhầm: Chưa đúng với nội dung bài học: Công nhận Vườn Quốc gia năm 2003.","Hay nhầm: Chưa đúng với nội dung bài học: Công nhận Vườn Quốc gia năm 2003.","Hay nhầm: Chưa đúng với nội dung bài học: Theo cấu trúc bài.","Hay nhầm: Chưa đúng với nội dung bài học: Theo cấu trúc bài.","Hay nhầm: Chưa đúng với nội dung bài học: Theo cấu trúc bài."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3,"Nâng cao":1}}}]}]}]},{"id":"anh","name":"Tiếng Anh","b":[{"t":"Tiếng Anh 12","c":[{"t":"Chủ điểm 1. Our Lives (Cuộc sống của chúng ta)","l":[{"t":"Unit 1. Life stories we admire (Những câu chuyện cuộc đời đáng ngưỡng mộ)","req":["Phân biệt và dùng đúng thì quá khứ đơn và quá khứ tiếp diễn.","Hiểu và dùng từ vựng về tiểu sử, cuộc đời của những người nổi tiếng."],"sum":["Quá khứ đơn: việc đã xong, chuỗi việc nối tiếp. Quá khứ tiếp diễn: việc đang diễn ra, hoặc bị việc ngắn (quá khứ đơn) xen vào.","Quá khứ đơn: Diễn tả hành động đã xảy ra và kết thúc trong quá khứ, hoặc một chuỗi hành động nối tiếp nhau. Động từ có quy tắc thêm -ed; bất quy tắc dùng cột 2…","Quá khứ tiếp diễn: Diễn tả hành động đang diễn ra tại một thời điểm trong quá khứ, hoặc một hành động đang diễn ra thì bị hành động khác (quá khứ đơn) xen vào.","Hai việc dài song song và động từ trạng thái: Hai hành động dài song song dùng while + quá khứ tiếp diễn ở cả hai vế.","Phát âm nguyên âm đôi /eɪ/ và /əʊ/"],"e":["Sai: I was knowing the answer. → Đúng: I knew the answer. (Động từ trạng thái (know, like, want, believe) thường không dùng ở dạng tiếp diễn.)","Hay nhầm: Sự kiện có mốc rõ ràng không dùng tiếp diễn.","Hay nhầm: Hiện tại đơn không dùng cho sự kiện năm 1976.","Hay nhầm: Có mốc thời gian quá khứ thì không dùng hiện tại hoàn thành.","Hay nhầm: Sau while thường là hành động kéo dài, dùng tiếp diễn.","Hay nhầm: Không dùng hiện tại hoàn thành với while trong văn kể."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 2. A multicultural world (Một thế giới đa văn hoá)","req":["Dùng đúng mạo từ a, an, the và không dùng mạo từ (zero article).","Hiểu và dùng từ vựng về sự đa dạng văn hoá, toàn cầu hoá."],"sum":["a / an: lần đầu hoặc bất kỳ. the: đã xác định, duy nhất, so sánh nhất, sông biển… Không mạo từ: số nhiều / không đếm được nói chung.","A / an: Dùng trước danh từ đếm được số ít khi nhắc đến lần đầu, hoặc nói về một người, vật bất kì. An đứng trước âm nguyên âm, a đứng trước âm phụ âm.","The: Dùng khi người nghe biết rõ đối tượng.","Không dùng mạo từ (zero article): Với danh từ số nhiều hoặc không đếm được khi nói chung, tên bữa ăn, môn học, ngôn ngữ, môn thể thao, hầu hết tên nước, thành phố, đường phố.","Phát âm nguyên âm đôi /ɔɪ/, /aɪ/, /aʊ/"],"e":["Sai: The culture is important. → Đúng: Ø Culture is important. (Nói chung chung thì không dùng the.)","Hay nhầm: An dùng trước âm nguyên âm.","Hay nhầm: Chưa xác định trường nào.","Hay nhầm: Danh từ đếm được số ít cần mạo từ.","Hay nhầm: Không dùng a với vật duy nhất.","Hay nhầm: Không nói về một trường hợp cụ thể."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 3. Green living (Sống xanh)","req":["Dùng đúng động từ đi với giới từ (verbs with prepositions).","Dùng mệnh đề quan hệ với which thay cho cả câu.","Hiểu và dùng từ vựng về lối sống xanh, tái chế."],"sum":["Động từ + giới từ cố định + N / V-ing. Mệnh đề quan hệ , which chỉ cả câu trước: có dấu phẩy, không dùng that, động từ chia số ít.","Động từ đi với giới từ: Nhiều động từ đi cùng một giới từ cố định; sau giới từ là danh từ hoặc V-ing.","Which chỉ cả mệnh đề đứng trước: Which có thể bổ nghĩa cho toàn bộ mệnh đề đứng trước (không chỉ một danh từ). Luôn có dấu phẩy phía trước và which không thể thay bằng that.","Phát âm nguyên âm đôi /ɪə/, /eə/, /ʊə/"],"e":["Sai: We throw away plastic, that is terrible for the ocean. → Đúng: We throw away plastic, which is terrible for the ocean. (Which chỉ cả câu trước không thể thay bằng that; động từ sau which luôn chia số ít (is, was, has, makes) vì…)","Hay nhầm: Care for nghĩa là chăm sóc.","Hay nhầm: That không dùng sau dấu phẩy để chỉ cả câu.","Hay nhầm: It tạo hai câu không nối nhau.","Hay nhầm: What không dùng làm đại từ quan hệ.","Hay nhầm: Organic không đi với to the environment."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 2. Our Society (Xã hội của chúng ta)","l":[{"t":"Unit 4. Urbanisation (Đô thị hoá)","req":["Ôn tập và mở rộng thì hiện tại hoàn thành.","Dùng so sánh kép (double comparatives) để diễn tả sự thay đổi.","Hiểu và dùng từ vựng về đô thị hoá."],"sum":["Hiện tại hoàn thành: have / has + V3, thời gian chưa kết thúc. Quá khứ đơn: mốc đã kết thúc. So sánh kép: The + comparative, the + comparative.","Hiện tại hoàn thành: Diễn tả hành động bắt đầu trong quá khứ và còn tiếp tục hoặc còn kết quả ở hiện tại; sự thay đổi tính đến nay; trải nghiệm.","Phân biệt với quá khứ đơn: Quá khứ đơn khi có mốc thời gian đã kết thúc. Hiện tại hoàn thành khi thời gian chưa kết thúc hoặc không nói rõ.","So sánh kép: The … , the …: Diễn tả hai sự việc thay đổi cùng nhau. Tính từ ngắn dùng the + -er; tính từ dài dùng the more / less + tính từ.","So sánh hơn lặp lại: Cũng diễn tả sự thay đổi dần.","Từ không nhấn trọng âm: Trong lời nói liên tục, các từ như a, the, to, of, and thường được đọc lướt với âm /ə/."],"e":["Hay nhầm: Có since nên không dùng quá khứ đơn.","Hay nhầm: Leisure time là thời gian rảnh.","Hay nhầm: Unemployment là thất nghiệp.","Hay nhầm: Có in 2015 nên không dùng hiện tại hoàn thành.","Hay nhầm: Family là chủ ngữ số ít và cần quá khứ đơn.","Hay nhầm: Ever + trải nghiệm dùng hiện tại hoàn thành."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 5. The world of work (Thế giới công việc)","req":["Nhận biết và viết câu đơn, câu ghép, câu phức.","Hiểu và dùng từ vựng về việc làm, tuyển dụng."],"sum":["Câu đơn: 1 mệnh đề. Câu ghép: các mệnh đề độc lập nối bằng liên từ kết hợp, có dấu phẩy. Câu phức: có mệnh đề phụ thuộc.","Câu đơn: Có một mệnh đề độc lập, gồm một chủ ngữ và một động từ (có thể có chủ ngữ hoặc động từ kép).","Câu ghép: Có hai hoặc nhiều mệnh đề độc lập nối với nhau bằng liên từ kết hợp (and, but, or, so, yet, for, nor) có dấu phẩy phía trước, hoặc bằng dấu chấm phẩy.","Câu phức: Có một mệnh đề độc lập và ít nhất một mệnh đề phụ thuộc, bắt đầu bằng liên từ phụ thuộc (because, although, when, while, if, since, after, before,…","Phát âm trợ động từ: Trợ động từ và động từ khuyết thiếu (can, must, have, do) thường không mang trọng âm, nhưng được nhấn mạnh khi đứng cuối câu, ở dạng phủ định hoặc…"],"e":["Hay nhầm: But là liên từ kết hợp, không tạo mệnh đề phụ.","Hay nhầm: Although là liên từ phụ thuộc.","Hay nhầm: Giờ hành chính không cho phép học buổi sáng.","Hay nhầm: Repetitive là lặp đi lặp lại.","Hay nhầm: Because chỉ nguyên nhân, sai hướng.","Hay nhầm: So không đứng đầu câu phức."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 3. Our Environment (Môi trường của chúng ta)","l":[{"t":"Unit 6. Artificial intelligence (Trí tuệ nhân tạo)","req":["Dùng đúng cấu trúc sai khiến chủ động và bị động (active and passive causatives).","Hiểu và dùng từ vựng về khoa học, công nghệ và trí tuệ nhân tạo."],"sum":["Sai khiến chủ động: have + người + V, get + người + to V. Bị động: have / get + vật + V3.","Sai khiến chủ động: Nói ai đó làm việc gì cho mình, nêu rõ người thực hiện.","Sai khiến bị động: Nhấn mạnh việc được làm, không cần nêu người thực hiện. Cả have và get đều dùng với quá khứ phân từ.","Lưu ý: Cấu trúc bị động cũng diễn tả việc không may xảy ra.","Từ đồng âm (homophones): Phát âm giống nhau nhưng viết khác và nghĩa khác."],"e":["Hay nhầm: Have không đi với to V trong sai khiến chủ động.","Hay nhầm: V3 dùng khi tân ngữ là vật (bị động).","Hay nhầm: Tân ngữ là vật nên cần V3.","Hay nhầm: To V dùng khi tân ngữ là người.","Hay nhầm: Virtual reality là thực tế ảo.","Hay nhầm: Voice command là lệnh giọng nói."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 7. The world of mass media (Thế giới truyền thông đại chúng)","req":["Dùng mệnh đề trạng ngữ chỉ cách thức (as, as if, as though) và chỉ kết quả (so ... that, such ... that).","Hiểu và dùng từ vựng về truyền thông đại chúng."],"sum":["Cách thức: as, as if / as though (không có thật → quá khứ đơn, were). Kết quả: so … that, such … that.","Mệnh đề chỉ cách thức: Cho biết một việc được làm như thế nào, bắt đầu bằng as (như), as if / as though (như thể). Sau as if / as though, nếu điều không có thật ở hiện tại…","Mệnh đề chỉ kết quả: Cho biết hệ quả của một việc, dùng so … that hoặc such … that.","Phát âm: nối âm /r/: Nối âm /r/ giữa hai nguyên âm (linking /r/)."],"e":["Sai: She looks as though she was a famous TV presenter. → Đúng: She looks as though she were a famous TV presenter. (Điều không có thật ở hiện tại: dùng were cho mọi ngôi.)","Hay nhầm: So không đứng trước cụm danh từ có mạo từ.","Hay nhầm: Such không mở đầu mệnh đề.","Hay nhầm: Fact-check là kiểm chứng.","Hay nhầm: Publicity là sự quảng bá.","Hay nhầm: Billboard là bảng quảng cáo."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 8. Wildlife conservation (Bảo tồn động vật hoang dã)","req":["Dùng mệnh đề trạng ngữ chỉ điều kiện (if, unless, as long as, provided that) và chỉ sự so sánh (as ... as, than).","Hiểu và dùng từ vựng về bảo tồn động vật hoang dã."],"sum":["Điều kiện: if, unless, as long as, provided that, in case. So sánh: as … as, adj-er / more … than.","Mệnh đề chỉ điều kiện: Bắt đầu bằng if (nếu), unless (trừ khi = if not), as long as / so long as (miễn là), provided / providing (that) (với điều kiện là), in case (phòng…","Mệnh đề chỉ sự so sánh: So sánh bằng as + adj/adv + as; so sánh hơn adj-er / more + adj + than; so sánh kém less + adj + than, not as … as. Có thể thêm much, far, a lot, a…","Lược bỏ và trợ động từ: Trong mệnh đề so sánh có thể lược bỏ động từ lặp lại hoặc dùng trợ động từ.","Phát âm: đồng hoá âm (assimilation): Âm cuối của từ thay đổi khi đứng trước âm đầu của từ sau."],"e":["Hay nhầm: If we stop poaching ... will disappear sai nghĩa.","Hay nhầm: As big cần as, không dùng than.","Hay nhầm: Vulnerable là dễ tổn thương.","Hay nhầm: Không dùng will trong mệnh đề if.","Hay nhầm: Quá khứ dùng cho điều kiện không có thật.","Hay nhầm: Không dùng hiện tại hoàn thành ở đây."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 4. Our Future (Tương lai của chúng ta)","l":[{"t":"Unit 9. Career paths (Con đường sự nghiệp)","req":["Hiểu và dùng cụm động từ ba từ (three-word phrasal verbs).","Hiểu và dùng từ vựng về việc chọn nghề nghiệp."],"sum":["Cụm động từ ba từ = động từ + tiểu từ + giới từ. Tân ngữ luôn đứng sau cả cụm. Sau giới từ cuối là động từ → V-ing.","Cụm động từ ba từ: Gồm động từ + tiểu từ (trạng từ) + giới từ, có nghĩa riêng khác nghĩa từng từ. Tân ngữ luôn đứng sau cả cụm, không thể chen vào giữa.","Các cụm thường gặp","Lưu ý: Sau giới từ cuối cùng, nếu là động từ thì dùng V-ing. Nhiều cụm có nghĩa khác khi là hai từ: get on (lên xe) khác get on with (hoà hợp).","Trọng âm câu và nhịp điệu: Các từ mang nghĩa chính (danh từ, động từ chính, tính từ) được nhấn, các từ chức năng đọc lướt."],"e":["Sai: She looks her father up to. → Đúng: She looks up to her father. (Không chen tân ngữ vào giữa cụm ba từ.)","Sai: I look forward to work with you. → Đúng: I look forward to working with you. (to ở đây là giới từ nên theo sau là V-ing.)","Hay nhầm: Put up with là chịu đựng.","Hay nhầm: Look down on là coi thường.","Hay nhầm: Live up to là đáp ứng kì vọng.","Hay nhầm: In demand là được săn đón."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 10. Lifelong learning (Học tập suốt đời)","req":["Dùng câu tường thuật để thuật lại mệnh lệnh, yêu cầu, lời đề nghị và lời khuyên.","Hiểu và dùng từ vựng về học tập suốt đời."],"sum":["Tường thuật mệnh lệnh / yêu cầu: tell / ask / order + O + (not) to V. Đề nghị: offer + to V. Lời khuyên: advise + O + to V.","Mệnh lệnh và yêu cầu: Dùng tell / order / ask + tân ngữ + to V; phủ định dùng not to V.","Yêu cầu lịch sự: Can you … ? / Could you … ? / Please … → dùng ask + tân ngữ + to V.","Lời đề nghị (offer): Dùng offer + to V.","Lời khuyên (advice): Dùng advise + tân ngữ + to V hoặc advise + V-ing; “You should …” → He advised me to …; “If I were you, I would …” cũng thuật bằng advise.","Đổi đại từ và trạng từ"],"e":["Hay nhầm: Say không đi với O + to V.","Hay nhầm: Offer là đề nghị làm giúp.","Hay nhầm: Không giữ nguyên câu mệnh lệnh.","Hay nhầm: Night school là lớp buổi tối.","Hay nhầm: Adult education là giáo dục người lớn.","Hay nhầm: Learning community là cộng đồng học tập."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]}]}]},{"id":"lichsu","name":"Lịch sử","b":[{"t":"Lịch sử 12","c":[{"t":"Chủ đề 1. Thế giới trong và sau Chiến tranh lạnh","l":[{"t":"Bài 1. Liên hợp quốc","sum":["Bối cảnh: cuối Chiến tranh thế giới thứ hai, phe Đồng minh chống phát xít chiếm ưu thế; nhu cầu tổ chức lại thế giới và lập tổ chức quốc tế bảo vệ hòa bình thay cho Hội Quốc liên (giải thể năm 1946)…","Bối cảnh: Cuối Chiến tranh thế giới thứ hai, phe Đồng minh chống phát xít chiếm ưu thế; nhu cầu tổ chức lại thế giới và lập tổ chức quốc tế bảo vệ hòa bình…","Từ khoá cần ghi nhớ: Liên hợp quốc;","Mốc sự kiện cần nhớ: 1/1/1942: 26 nước kí Tuyên bố về Liên hợp quốc;","Quá trình hình thành: 1-1-1942, đại diện 26 nước kí Tuyên bố về Liên hợp quốc;","Mục tiêu (Điều 1 Hiến chương): Duy trì hòa bình và an ninh quốc tế; thúc đẩy quan hệ hữu nghị giữa các dân tộc trên cơ sở tôn trọng quyền bình đẳng, tự quyết; thúc đẩy hợp tác…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Có 51 nước thành viên ban đầu.","Hay nhầm: Chưa đúng với nội dung bài học: Có 51 nước thành viên ban đầu.","Hay nhầm: Chưa đúng với nội dung bài học: Có 51 nước thành viên ban đầu.","Hay nhầm: Chưa đúng với nội dung bài học: Từ 25-4 đến 26-6-1945.","Hay nhầm: Chưa đúng với nội dung bài học: Từ 25-4 đến 26-6-1945.","Hay nhầm: Chưa đúng với nội dung bài học: Từ 25-4 đến 26-6-1945."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 2. Trật tự thế giới trong Chiến tranh lạnh","sum":["Hội nghị I-an-ta (4 đến 12-2-1945), Liên Xô: nguyên thủ Liên Xô (Xta-lin), Mỹ (Ru-dơ-ven), Anh (Sớc-sin).","Hội nghị I-an-ta (4 đến 12-2-1945), Liên Xô: Nguyên thủ Liên Xô (Xta-lin), Mỹ (Ru-dơ-ven), Anh (Sớc-sin).","Từ khoá cần ghi nhớ: I-an-ta; trật tự hai cực;","Mốc sự kiện cần nhớ: 4–12/2/1945: Hội nghị I-an-ta","Quá trình tồn tại (1945 – 1991), hai giai đoạn: 1945 – đầu thập niên 70 thế kỉ XX: xác lập và phát triển, đối đầu Mỹ (đứng đầu tư bản chủ nghĩa) – Liên Xô (đứng đầu xã hội chủ nghĩa); NATO (1949),…","Nguyên nhân sụp đổ: Đối đầu căng thẳng gây tốn kém, suy giảm kinh tế cả hai cực"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Từ 4 đến 12-2-1945.","Hay nhầm: Chưa đúng với nội dung bài học: Từ 4 đến 12-2-1945.","Hay nhầm: Chưa đúng với nội dung bài học: Từ 4 đến 12-2-1945.","Hay nhầm: Chưa đúng với nội dung bài học: Ba cường quốc Đồng minh.","Hay nhầm: Chưa đúng với nội dung bài học: Ba cường quốc Đồng minh.","Hay nhầm: Chưa đúng với nội dung bài học: Ba cường quốc Đồng minh."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 3. Trật tự thế giới sau Chiến tranh lạnh","sum":["Xu thế chính sau Chiến tranh lạnh: kinh tế là trọng tâm (các nước điều chỉnh chiến lược phát triển tập trung vào kinh tế để tăng sức mạnh quốc gia và đời sống); toàn cầu hóa (gia tăng mạnh mẽ các…","Xu thế chính sau Chiến tranh lạnh: Kinh tế là trọng tâm (các nước điều chỉnh chiến lược phát triển tập trung vào kinh tế để tăng sức mạnh quốc gia và đời sống); toàn cầu hóa (gia tăng…","Từ khoá cần ghi nhớ: Trật tự thế giới đa cực; toàn cầu hoá; kinh tế là trọng tâm;","Mốc sự kiện cần nhớ: Xu thế chính sau Chiến tranh lạnh: kinh tế là trọng tâm, toàn cầu hoá, hợp tác thay đối đầu","Đa cực: Trật tự thế giới có sự tham gia của nhiều quốc gia, trung tâm, không quốc gia nào có quyền lực áp đảo, chi phối sự phát triển thế giới. Biểu hiện…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Mở ra thời kì mới.","Hay nhầm: Chưa đúng với nội dung bài học: Mở ra thời kì mới.","Hay nhầm: Chưa đúng với nội dung bài học: Mở ra thời kì mới.","Hay nhầm: Chưa đúng với nội dung bài học: Các nước điều chỉnh chiến lược.","Hay nhầm: Chưa đúng với nội dung bài học: Các nước điều chỉnh chiến lược.","Hay nhầm: Chưa đúng với nội dung bài học: Các nước điều chỉnh chiến lược."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":3,"Nâng cao":2}}}]},{"t":"Chủ đề 2. ASEAN: Những chặng đường lịch sử","l":[{"t":"Bài 4. Sự ra đời và phát triển của Hiệp hội các quốc gia Đông Nam Á (ASEAN)","sum":["Bối cảnh ra đời: sau Chiến tranh thế giới thứ hai xu hướng khu vực hóa xuất hiện; các nước Đông Nam Á cần hợp tác phát triển kinh tế, xã hội và tạo sức mạnh tập thể ứng phó sự tranh giành ảnh hưởng…","Bối cảnh ra đời: Sau Chiến tranh thế giới thứ hai xu hướng khu vực hóa xuất hiện; các nước Đông Nam Á cần hợp tác phát triển kinh tế, xã hội và tạo sức mạnh tập thể…","Từ khoá cần ghi nhớ: ASEAN; khu vực hoá;","Mốc sự kiện cần nhớ: 1961: Hiệp hội Đông Nam Á;","Mục đích: Thúc đẩy tăng trưởng kinh tế, tiến bộ xã hội, phát triển văn hóa; thúc đẩy hòa bình, ổn định khu vực bằng tôn trọng công lí, luật pháp và Hiến…","Từ ASEAN 5 đến ASEAN 10: Bru-nây gia nhập (1984, thành viên thứ 6);"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Tại Băng Cốc, Thái Lan.","Hay nhầm: Chưa đúng với nội dung bài học: Tại Băng Cốc, Thái Lan.","Hay nhầm: Chưa đúng với nội dung bài học: Tại Băng Cốc, Thái Lan.","Hay nhầm: Chưa đúng với nội dung bài học: Ngoại trưởng năm nước kí Tuyên bố Băng Cốc.","Hay nhầm: Chưa đúng với nội dung bài học: Ngoại trưởng năm nước kí Tuyên bố Băng Cốc.","Hay nhầm: Chưa đúng với nội dung bài học: Ngoại trưởng năm nước kí Tuyên bố Băng Cốc."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 5. Cộng đồng ASEAN: Từ ý tưởng đến hiện thực","sum":["Ý tưởng: khởi nguồn từ khi thành lập (Tuyên bố Băng Cốc nêu mục tiêu một cộng đồng thịnh vượng và hòa bình).","Ý tưởng: Khởi nguồn từ khi thành lập (Tuyên bố Băng Cốc nêu mục tiêu một cộng đồng thịnh vượng và hòa bình).","Từ khoá cần ghi nhớ: Cộng đồng ASEAN;","Mốc sự kiện cần nhớ: 1997: Tầm nhìn ASEAN 2020 được thông qua tại Ma-lai-xi-a","Kế hoạch: Lộ trình xây dựng Cộng đồng ASEAN (2009 – 2015), thông qua tại Hội nghị cấp cao ASEAN 14 (Thái Lan, 2009).","Ba trụ cột: Cộng đồng Chính trị – An ninh ASEAN (APSC): tạo dựng môi trường hòa bình, an ninh; ba nội dung: xây dựng cộng đồng dựa trên giá trị, chuẩn mực…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Sau Tuyên bố Cu-a-la Lăm-pơ.","Hay nhầm: Chưa đúng với nội dung bài học: Sau Tuyên bố Cu-a-la Lăm-pơ.","Hay nhầm: Chưa đúng với nội dung bài học: Sau Tuyên bố Cu-a-la Lăm-pơ.","Hay nhầm: Chưa đúng với nội dung bài học: APSC, AEC, ASCC.","Hay nhầm: Chưa đúng với nội dung bài học: APSC, AEC, ASCC.","Hay nhầm: Chưa đúng với nội dung bài học: APSC, AEC, ASCC."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chủ đề 3. Cách mạng tháng Tám năm 1945, chiến tranh giải phóng dân tộc và chiến tranh bảo vệ Tổ quốc trong lịch sử Việt Nam (từ tháng 8…","l":[{"t":"Bài 6. Cách mạng tháng Tám năm 1945","sum":["Bối cảnh: Hội nghị Pốt-xđam (17-7 đến 2-8-1945) giao cho quân Trung Hoa Dân quốc giải giáp quân Nhật ở phía Bắc vĩ tuyến 16 và quân Anh ở phía Nam;","Bối cảnh: Hội nghị Pốt-xđam (17-7 đến 2-8-1945) giao cho quân Trung Hoa Dân quốc giải giáp quân Nhật ở phía Bắc vĩ tuyến 16 và quân Anh ở phía Nam;","Từ khoá cần ghi nhớ: Hội nghị Pốt-xđam;","Mốc sự kiện cần nhớ: 17/7–2/8/1945: Hội nghị Pốt-xđam;","Chủ trương: 13-8-1945 Ủy ban Khởi nghĩa toàn quốc thành lập, ban bố Quân lệnh số 1;","Diễn biến: 16-8 một đơn vị Giải phóng quân do Võ Nguyên Giáp chỉ huy tiến về giải phóng Thái Nguyên;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Mở ra thời cơ khách quan.","Hay nhầm: Chưa đúng với nội dung bài học: Mở ra thời cơ khách quan.","Hay nhầm: Chưa đúng với nội dung bài học: Mở ra thời cơ khách quan.","Hay nhầm: Chưa đúng với nội dung bài học: Ngày 14, 15-8-1945.","Hay nhầm: Chưa đúng với nội dung bài học: Ngày 14, 15-8-1945.","Hay nhầm: Chưa đúng với nội dung bài học: Ngày 14, 15-8-1945."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 7. Cuộc kháng chiến chống thực dân Pháp (1945 - 1954)","sum":["Bối cảnh: thế giới có hệ thống xã hội chủ nghĩa hình thành, phong trào giải phóng dân tộc dâng cao, Trật tự hai cực I-an-ta và Chiến tranh lạnh tác động.","Bối cảnh: Thế giới có hệ thống xã hội chủ nghĩa hình thành, phong trào giải phóng dân tộc dâng cao, Trật tự hai cực I-an-ta và Chiến tranh lạnh tác động.","Từ khoá cần ghi nhớ: Ngàn cân treo sợi tóc; quân Trung Hoa Dân quốc; quân Anh;","Mốc sự kiện cần nhớ: Giai đoạn 1945–1954: kháng chiến chống thực dân Pháp trong bối cảnh chính quyền cách mạng non trẻ","Nam Bộ kháng chiến (1945): 2-9-1945 Pháp xả súng vào nhân dân Sài Gòn;","Các thắng lợi quân sự (1946 – 1950): Chiến đấu ở các đô thị phía Bắc vĩ tuyến 16 (19-12-1946 đến 17-2-1947), tiêu biểu ở Hà Nội;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Mở đầu kháng chiến toàn quốc.","Hay nhầm: Chưa đúng với nội dung bài học: Mở đầu kháng chiến toàn quốc.","Hay nhầm: Chưa đúng với nội dung bài học: Mở đầu kháng chiến toàn quốc.","Hay nhầm: Chưa đúng với nội dung bài học: Làm thất bại “đánh nhanh, thắng nhanh”.","Hay nhầm: Chưa đúng với nội dung bài học: Làm thất bại “đánh nhanh, thắng nhanh”.","Hay nhầm: Chưa đúng với nội dung bài học: Làm thất bại “đánh nhanh, thắng nhanh”."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 8. Cuộc kháng chiến chống Mỹ, cứu nước (1954 - 1975)","sum":["Bối cảnh: sau Hiệp định Giơ-ne-vơ, Mỹ thay chân Pháp, dựng chính quyền Ngô Đình Diệm ở miền Nam, âm mưu chia cắt Việt Nam, biến miền Nam thành thuộc địa kiểu mới và căn cứ quân sự, ngăn chặn chủ…","Bối cảnh: Sau Hiệp định Giơ-ne-vơ, Mỹ thay chân Pháp, dựng chính quyền Ngô Đình Diệm ở miền Nam, âm mưu chia cắt Việt Nam, biến miền Nam thành thuộc địa kiểu…","Từ khoá cần ghi nhớ: Hiệp định Giơ-ne-vơ;","Mốc sự kiện cần nhớ: Sau Hiệp định Giơ-ne-vơ (1954), Mỹ thay chân Pháp; kháng chiến chống Mỹ kéo dài đến năm 1975","Giai đoạn 1954 – 1960: Miền Bắc hoàn thành cải cách ruộng đất, khôi phục kinh tế, cải tạo quan hệ sản xuất; miền Nam đấu tranh đòi thi hành Hiệp định Giơ-ne-vơ, giữ gìn…","Giai đoạn 1961 – 1965: Đại hội III của Đảng (9-1960) xác định nhiệm vụ chiến lược; miền Bắc thực hiện kế hoạch 5 năm lần thứ nhất (1961 – 1965) và làm hậu phương lớn; miền…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Có “Đội quân tóc dài”.","Hay nhầm: Chưa đúng với nội dung bài học: Có “Đội quân tóc dài”.","Hay nhầm: Chưa đúng với nội dung bài học: Có “Đội quân tóc dài”.","Hay nhầm: Chưa đúng với nội dung bài học: Sau Đồng khởi.","Hay nhầm: Chưa đúng với nội dung bài học: Sau Đồng khởi.","Hay nhầm: Chưa đúng với nội dung bài học: Sau Đồng khởi."],"q":{"n":18,"lv":{"Biết":6,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 9. Cuộc đấu tranh bảo vệ Tổ quốc từ sau tháng 4 - 1975 đến nay. Một số bài học lịch sử của các cuộc kháng chiến…","sum":["Bối cảnh: sau 1975 đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội (Quốc hội khóa VI, 1976 thống nhất đất nước về mặt Nhà nước); hậu quả chiến tranh nặng nề, bị Mỹ bao vây, cấm vận; quan hệ…","Bối cảnh: Sau 1975 đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội (Quốc hội khóa VI, 1976 thống nhất đất nước về mặt Nhà nước); hậu quả chiến tranh…","Từ khoá cần ghi nhớ: Thống nhất đất nước;","Mốc sự kiện cần nhớ: Năm 1976: Quốc hội khoá VI thống nhất đất nước về mặt nhà nước; từ tháng 4/1975 đất nước độc lập, thống nhất","Biên giới Tây Nam: Sau khi lên nắm quyền (4-1975) chính quyền Pôn Pốt xâm phạm lãnh thổ (đánh chiếm Phú Quốc, Thổ Chu từ 5-1975);","Biên giới phía Bắc: Từ giữa 1975 quan hệ căng thẳng; sáng 17-2-1979 hàng chục vạn quân Trung Quốc tấn công dọc hơn 1 000 km biên giới từ Móng Cái (Quảng Ninh) đến Phong…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Mở cuộc tiến công 30-4-1977.","Hay nhầm: Chưa đúng với nội dung bài học: Mở cuộc tiến công 30-4-1977.","Hay nhầm: Chưa đúng với nội dung bài học: Mở cuộc tiến công 30-4-1977.","Hay nhầm: Chưa đúng với nội dung bài học: Quân tình nguyện Việt Nam cùng quân dân Cam-pu-chia.","Hay nhầm: Chưa đúng với nội dung bài học: Quân tình nguyện Việt Nam cùng quân dân Cam-pu-chia.","Hay nhầm: Chưa đúng với nội dung bài học: Quân tình nguyện Việt Nam cùng quân dân Cam-pu-chia."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chủ đề 4. Công cuộc Đổi mới ở Việt Nam từ năm 1986 đến nay","l":[{"t":"Bài 10. Khái quát về công cuộc Đổi mới từ năm 1986 đến nay","sum":["Đại hội đại biểu toàn quốc lần thứ VI của Đảng (12-1986) đánh dấu bước ngoặt, mở đầu thời kì Đổi mới toàn diện đất nước.","Khái niệm: Đại hội đại biểu toàn quốc lần thứ VI của Đảng (12-1986) đánh dấu bước ngoặt, mở đầu thời kì Đổi mới toàn diện đất nước.","Từ khoá cần ghi nhớ: Đổi mới;","Mốc sự kiện cần nhớ: 12/1986: Đại hội đại biểu toàn quốc lần thứ VI mở đầu công cuộc Đổi mới","Giai đoạn 1986 – 1995 (khởi đầu): Đường lối đổi mới toàn diện, đồng bộ, trọng tâm là đổi mới kinh tế: xóa bỏ cơ chế tập trung quan liêu, bao cấp, hình thành cơ chế thị trường có sự…","Giai đoạn 1996 – 2006: Đại hội VIII (1996) xác định chuyển sang thời kì đẩy mạnh công nghiệp hóa, hiện đại hóa; tiếp tục phát triển kinh tế thị trường định hướng xã hội…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Bước ngoặt cơ bản.","Hay nhầm: Chưa đúng với nội dung bài học: Bước ngoặt cơ bản.","Hay nhầm: Chưa đúng với nội dung bài học: Bước ngoặt cơ bản.","Hay nhầm: Chưa đúng với nội dung bài học: Gắn với đổi mới chính trị, văn hóa – xã hội.","Hay nhầm: Chưa đúng với nội dung bài học: Gắn với đổi mới chính trị, văn hóa – xã hội.","Hay nhầm: Chưa đúng với nội dung bài học: Gắn với đổi mới chính trị, văn hóa – xã hội."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 11. Thành tựu cơ bản và bài học của công cuộc Đổi mới ở Việt Nam từ năm 1986 đến nay","sum":["Kinh tế: chuyển từ cơ chế tập trung, bao cấp sang kinh tế thị trường định hướng xã hội chủ nghĩa (ngày 1-4-1989 bãi bỏ chế độ tem phiếu).","Kinh tế: Chuyển từ cơ chế tập trung, bao cấp sang kinh tế thị trường định hướng xã hội chủ nghĩa (ngày 1-4-1989 bãi bỏ chế độ tem phiếu).","Từ khoá cần ghi nhớ: Kinh tế thị trường định hướng xã hội chủ nghĩa; tăng trưởng GDP; tem phiếu; cơ cấu kinh tế; bài học đổi mới.","Mốc sự kiện cần nhớ: 1/4/1989: bãi bỏ chế độ tem phiếu; năm 2022: GDP tăng 8,02%","Chính trị, an ninh – quốc phòng: Xây dựng Nhà nước pháp quyền xã hội chủ nghĩa vững mạnh; bộ máy tinh gọn, hiệu quả; bảo vệ vững chắc độc lập, chủ quyền, thống nhất, toàn vẹn lãnh…","Hội nhập quốc tế: Thiết lập quan hệ ngoại giao với 189/193 quốc gia và vùng lãnh thổ; xây dựng quan hệ đối tác chiến lược, đối tác toàn diện; quan hệ với 247 chính…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Kết thúc thời kì bao cấp.","Hay nhầm: Chưa đúng với nội dung bài học: Kết thúc thời kì bao cấp.","Hay nhầm: Chưa đúng với nội dung bài học: Kết thúc thời kì bao cấp.","Hay nhầm: Chưa đúng với nội dung bài học: Cao hơn năm 2020, 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Cao hơn năm 2020, 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Cao hơn năm 2020, 2021."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}}]},{"t":"Chủ đề 5. Lịch sử đối ngoại của Việt Nam thời cận - hiện đại","l":[{"t":"Bài 12. Hoạt động đối ngoại của Việt Nam trong đấu tranh giành độc lập dân tộc (từ đầu thế kỉ XX đến Cách mạng tháng…","sum":["Phan Bội Châu: hoạt động đối ngoại ở Nhật Bản, Trung Quốc để tìm sự giúp đỡ chống Pháp. Đầu 1905 sang Nhật nhờ giúp khí giới, đào tạo nhân lực;","Phan Bội Châu: Hoạt động đối ngoại ở Nhật Bản, Trung Quốc để tìm sự giúp đỡ chống Pháp.","Từ khoá cần ghi nhớ: Đối ngoại;","Mốc sự kiện cần nhớ: Đầu năm 1905: Phan Bội Châu sang Nhật;","Nguyễn Ái Quốc (1911 – 1930): 1911 – 1922 đi qua nhiều nước, hoạt động chủ yếu ở Pháp;","Đảng Cộng sản Đông Dương (1930 – 1945): Là một phân bộ của Quốc tế Cộng sản; tổ chức ủng hộ Liên Xô, quyên góp giúp nạn nhân chiến tranh ở Trung Quốc; củng cố quan hệ với Đảng Cộng sản…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Tìm sự giúp đỡ chống Pháp.","Hay nhầm: Chưa đúng với nội dung bài học: Tìm sự giúp đỡ chống Pháp.","Hay nhầm: Chưa đúng với nội dung bài học: Tìm sự giúp đỡ chống Pháp.","Hay nhầm: Chưa đúng với nội dung bài học: Vận động cải cách.","Hay nhầm: Chưa đúng với nội dung bài học: Vận động cải cách.","Hay nhầm: Chưa đúng với nội dung bài học: Vận động cải cách."],"q":{"n":16,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 13. Hoạt động đối ngoại của Việt Nam trong kháng chiến chống Pháp (1945 - 1954) và kháng chiến chống Mỹ (1954 -…","sum":["Kháng chiến chống Pháp (1945 – 1954): mục đích bảo vệ chính quyền cách mạng, tranh thủ ủng hộ quốc tế, tránh đối đầu cùng lúc nhiều kẻ thù.","Kháng chiến chống Pháp (1945 – 1954): Mục đích bảo vệ chính quyền cách mạng, tranh thủ ủng hộ quốc tế, tránh đối đầu cùng lúc nhiều kẻ thù.","Từ khoá cần ghi nhớ: Ngoại giao;","Mốc sự kiện cần nhớ: 6/3/1946: Hiệp định Sơ bộ;","Kháng chiến chống Mỹ (1954 – 1975): Đấu tranh đòi thi hành Hiệp định Giơ-ne-vơ, củng cố quan hệ với các nước xã hội chủ nghĩa, mở rộng quan hệ ngoại giao; cân bằng quan hệ với Liên Xô,…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Pháp thay quân Trung Hoa Dân quốc giải giáp quân Nhật.","Hay nhầm: Chưa đúng với nội dung bài học: Pháp thay quân Trung Hoa Dân quốc giải giáp quân Nhật.","Hay nhầm: Chưa đúng với nội dung bài học: Pháp thay quân Trung Hoa Dân quốc giải giáp quân Nhật.","Hay nhầm: Chưa đúng với nội dung bài học: Kéo dài thời gian hòa bình.","Hay nhầm: Chưa đúng với nội dung bài học: Kéo dài thời gian hòa bình.","Hay nhầm: Chưa đúng với nội dung bài học: Kéo dài thời gian hòa bình."],"q":{"n":16,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 14. Hoạt động đối ngoại của Việt Nam từ năm 1975 đến nay","sum":["Ngày 20-9-1977, Việt Nam trở thành thành viên chính thức của Liên hợp quốc. Giai đoạn 1975 – 1985: hợp tác toàn diện với Liên Xô và các nước xã hội chủ nghĩa (1978 gia nhập Hội đồng tương trợ kinh…","Khái niệm: Ngày 20-9-1977, Việt Nam trở thành thành viên chính thức của Liên hợp quốc.","Từ khoá cần ghi nhớ: Liên hợp quốc;","Mốc sự kiện cần nhớ: 20/9/1977: Việt Nam trở thành thành viên chính thức của Liên hợp quốc;","Thời kì Đổi mới (từ 1986): Đại hội VII (1991) xác định “hợp tác, bình đẳng và cùng có lợi với tất cả các nước, không phân biệt chế độ chính trị – xã hội”.","Hội nhập khu vực và thế giới: Thành viên ASEAN, WTO,...; kí AFTA, Hiệp định Thương mại tự do Việt Nam – EU (EVFTA), RCEP; tổ chức thành công các hội nghị ASEAN, ASEM, APEC; hai…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Kì họp lần thứ 32 Đại hội đồng.","Hay nhầm: Chưa đúng với nội dung bài học: Kì họp lần thứ 32 Đại hội đồng.","Hay nhầm: Chưa đúng với nội dung bài học: Kì họp lần thứ 32 Đại hội đồng.","Hay nhầm: Chưa đúng với nội dung bài học: Hợp tác với Liên Xô và các nước xã hội chủ nghĩa.","Hay nhầm: Chưa đúng với nội dung bài học: Hợp tác với Liên Xô và các nước xã hội chủ nghĩa.","Hay nhầm: Chưa đúng với nội dung bài học: Hợp tác với Liên Xô và các nước xã hội chủ nghĩa."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chủ đề 6. Hồ Chí Minh trong lịch sử Việt Nam","l":[{"t":"Bài 15. Khái quát cuộc đời và sự nghiệp của Hồ Chí Minh","sum":["Yếu tố ảnh hưởng: hoàn cảnh đất nước (truyền thống yêu nước, đoàn kết, nhân nghĩa; từ giữa thế kỉ XIX Pháp xâm lược, các phong trào yêu nước thất bại, độc lập dân tộc là nhiệm vụ cấp bách); quê…","Yếu tố ảnh hưởng: Hoàn cảnh đất nước (truyền thống yêu nước, đoàn kết, nhân nghĩa; từ giữa thế kỉ XIX Pháp xâm lược, các phong trào yêu nước thất bại, độc lập dân tộc…","Từ khoá cần ghi nhớ: Hồ Chí Minh;","Mốc sự kiện cần nhớ: Từ giữa thế kỉ XIX, thực dân Pháp xâm lược; các phong trào yêu nước thất bại","Thời niên thiếu (1890 – 1911): Sinh ngày 19-5-1890, tên Nguyễn Sinh Cung, quê cha ở Làng Sen, quê mẹ ở làng Hoàng Trù (xã Kim Liên, Nam Đàn, Nghệ An); năm 1895 vào Huế; sau khi mẹ…","Hoạt động ở nước ngoài (1911 – 1941): 1911 – 1917 đến nhiều nước châu Á, Âu, Phi;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Tại Nam Đàn, Nghệ An.","Hay nhầm: Chưa đúng với nội dung bài học: Tại Nam Đàn, Nghệ An.","Hay nhầm: Chưa đúng với nội dung bài học: Tại Nam Đàn, Nghệ An.","Hay nhầm: Chưa đúng với nội dung bài học: Sau đổi thành Nguyễn Tất Thành.","Hay nhầm: Chưa đúng với nội dung bài học: Sau đổi thành Nguyễn Tất Thành.","Hay nhầm: Chưa đúng với nội dung bài học: Sau đổi thành Nguyễn Tất Thành."],"q":{"n":16,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 16. Hồ Chí Minh - Anh hùng giải phóng dân tộc","sum":["Hành trình tìm đường cứu nước: từ 5-6-1911, Nguyễn Tất Thành đi qua nhiều châu lục, tự học, thấu hiểu bản chất chủ nghĩa thực dân và các cuộc cách mạng tư sản.","Hành trình tìm đường cứu nước: Từ 5-6-1911, Nguyễn Tất Thành đi qua nhiều châu lục, tự học, thấu hiểu bản chất chủ nghĩa thực dân và các cuộc cách mạng tư sản.","Từ khoá cần ghi nhớ: Nguyễn Tất Thành; hành trình tìm đường cứu nước;","Mốc sự kiện cần nhớ: 5/6/1911: Nguyễn Tất Thành ra đi tìm đường cứu nước; tháng 7/1920: đọc Sơ thảo luận cương của Lê-nin","Sáng lập Đảng Cộng sản Việt Nam: Chuẩn bị chính trị, tư tưởng (tố cáo chủ nghĩa thực dân, thành lập Hội liên hiệp thuộc địa, báo Le Paria – Người cùng khổ; tác phẩm Đường Kách mệnh;…","Chuẩn bị và lãnh đạo Cách mạng tháng Tám: 28-1-1941 về nước;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Nêu vai trò của Đảng cách mạng.","Hay nhầm: Chưa đúng với nội dung bài học: Nêu vai trò của Đảng cách mạng.","Hay nhầm: Chưa đúng với nội dung bài học: Nêu vai trò của Đảng cách mạng.","Hay nhầm: Chưa đúng với nội dung bài học: Do Nguyễn Ái Quốc chủ trì.","Hay nhầm: Chưa đúng với nội dung bài học: Do Nguyễn Ái Quốc chủ trì.","Hay nhầm: Chưa đúng với nội dung bài học: Do Nguyễn Ái Quốc chủ trì."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 17. Dấu ấn Hồ Chí Minh trong lòng nhân dân thế giới và Việt Nam","sum":["Trong lòng nhân dân thế giới: UNESCO khóa họp lần thứ 24 tại Pa-ri (1987) thông qua Nghị quyết 24C/18.6.5 kỉ niệm 100 năm ngày sinh Hồ Chí Minh (1990), ghi nhận Người là “Anh hùng giải phóng dân tộc…","Trong lòng nhân dân thế giới: UNESCO khóa họp lần thứ 24 tại Pa-ri (1987) thông qua Nghị quyết 24C/18.6.5 kỉ niệm 100 năm ngày sinh Hồ Chí Minh (1990), ghi nhận Người là “Anh…","Từ khoá cần ghi nhớ: UNESCO;","Mốc sự kiện cần nhớ: 1987: UNESCO thông qua nghị quyết kỉ niệm 100 năm ngày sinh Hồ Chí Minh (1990)","Trong lòng nhân dân Việt Nam: Người cống hiến trọn đời cho độc lập dân tộc, tự do, hạnh phúc của nhân dân; là nhà cách mạng, nhà văn hóa lớn, tấm gương đạo đức."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Khóa họp lần thứ 24 tại Pa-ri.","Hay nhầm: Chưa đúng với nội dung bài học: Khóa họp lần thứ 24 tại Pa-ri.","Hay nhầm: Chưa đúng với nội dung bài học: Khóa họp lần thứ 24 tại Pa-ri.","Hay nhầm: Chưa đúng với nội dung bài học: Quốc hội khóa VI quyết định.","Hay nhầm: Chưa đúng với nội dung bài học: Quốc hội khóa VI quyết định.","Hay nhầm: Chưa đúng với nội dung bài học: Quốc hội khóa VI quyết định."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}}]}]}]},{"id":"diali","name":"Địa lí","b":[{"t":"Địa lí 12","c":[{"t":"Phần 1. Địa lí tự nhiên","l":[{"t":"Bài 1. Vị trí địa lí và phạm vi lãnh thổ","sum":["Vị trí địa lí: Việt Nam gần trung tâm Đông Nam Á, trên đất liền tiếp giáp Trung Quốc, Lào, Cam-pu-chia và có chung Biển Đông với nhiều quốc gia.","Vị trí địa lí: Việt Nam gần trung tâm Đông Nam Á, trên đất liền tiếp giáp Trung Quốc, Lào, Cam-pu-chia và có chung Biển Đông với nhiều quốc gia.","Từ khoá cần ghi nhớ: Vị trí địa lí;","Điểm nhấn ghi nhớ: Cực Bắc Lũng Cú (Hà Giang), cực Nam Đất Mũi (Cà Mau), cực Tây Sín Thầu (Điện Biên), cực Đông Vạn Thạnh (Khánh Hoà)","Việt Nam nằm hoàn toàn trong vòng…: Việt Nam nằm hoàn toàn trong vòng đai nóng nội chí tuyến bán cầu Bắc, thuộc khu vực khí hậu nhiệt đới gió mùa châu Á; tiếp giáp Biển Đông thông ra…","Phạm vi lãnh thổ gồm vùng đất, vùng biển, vùng trời: Vùng đất: tổng diện tích các đơn vị hành chính hơn 331 nghìn km² (đất liền và các đảo)."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Điểm cực Bắc ở xã Lũng Cú, huyện Đồng Văn, Hà Giang.","Hay nhầm: Chưa đúng với nội dung bài học: Điểm cực Bắc ở xã Lũng Cú, huyện Đồng Văn, Hà Giang.","Hay nhầm: Chưa đúng với nội dung bài học: Điểm cực Bắc ở xã Lũng Cú, huyện Đồng Văn, Hà Giang.","Hay nhầm: Chưa đúng với nội dung bài học: Điểm cực Nam ở xã Đất Mũi, huyện Ngọc Hiển, Cà Mau.","Hay nhầm: Chưa đúng với nội dung bài học: Điểm cực Nam ở xã Đất Mũi, huyện Ngọc Hiển, Cà Mau.","Hay nhầm: Chưa đúng với nội dung bài học: Điểm cực Nam ở xã Đất Mũi, huyện Ngọc Hiển, Cà Mau."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}},{"t":"Bài 2. Thiên nhiên nhiệt đới ẩm gió mùa","sum":["Khí hậu: bức xạ mặt trời lớn, cán cân bức xạ quanh năm dương; nhiệt độ trung bình năm trên 20 °C (trừ vùng núi cao), số giờ nắng 1400–3000 giờ/năm.","Khí hậu: Bức xạ mặt trời lớn, cán cân bức xạ quanh năm dương; nhiệt độ trung bình năm trên 20 °C (trừ vùng núi cao), số giờ nắng 1400–3000 giờ/năm.","Từ khoá cần ghi nhớ: Nhiệt đới ẩm; gió mùa; bức xạ; nhiệt độ; lượng mưa;","Điểm nhấn ghi nhớ: Nhiệt độ trung bình năm trên 20 °C; mưa 1 500–2 000 mm/năm;","Gió mùa: Tín phong hoạt động quanh năm và gió mùa châu Á.","Địa hình: Phong hóa mạnh, địa hình các-xtơ (Quảng Bình, Hà Giang, Ninh Bình); quá trình xâm thực – bồi tụ là chủ yếu: xâm thực mạnh ở miền đồi núi, bồi tụ ở…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Nhiệt độ trung bình năm trên cả nước đều trên 20 °C.","Hay nhầm: Chưa đúng với nội dung bài học: Nhiệt độ trung bình năm trên cả nước đều trên 20 °C.","Hay nhầm: Chưa đúng với nội dung bài học: Nhiệt độ trung bình năm trên cả nước đều trên 20 °C.","Hay nhầm: Chưa đúng với nội dung bài học: Khối khí lạnh từ áp cao Xi-bia thổi về theo hướng đông bắc.","Hay nhầm: Chưa đúng với nội dung bài học: Khối khí lạnh từ áp cao Xi-bia thổi về theo hướng đông bắc.","Hay nhầm: Chưa đúng với nội dung bài học: Khối khí lạnh từ áp cao Xi-bia thổi về theo hướng đông bắc."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}},{"t":"Bài 3. Sự phân hóa đa dạng của thiên nhiên","sum":["Phân hóa bắc – nam: phần lãnh thổ phía Bắc (từ dãy Bạch Mã trở ra) có khí hậu nhiệt đới ẩm gió mùa có mùa đông lạnh (nhiệt độ trung bình năm trên 20 °C, 2–3 tháng dưới 18 °C, biên độ nhiệt lớn),…","Phân hóa bắc – nam: Phần lãnh thổ phía Bắc (từ dãy Bạch Mã trở ra) có khí hậu nhiệt đới ẩm gió mùa có mùa đông lạnh (nhiệt độ trung bình năm trên 20 °C, 2–3 tháng dưới…","Từ khoá cần ghi nhớ: Phân hoá bắc – nam;","Điểm nhấn ghi nhớ: Ranh giới bắc – nam là dãy Bạch Mã; ba hướng phân hoá: bắc – nam, đông – tây, độ cao","Phân hóa đông – tây: Vùng biển và thềm lục địa (diện tích gấp 3 lần đất liền)","Phân hóa theo độ cao: Đai nhiệt đới gió mùa (miền Bắc dưới 600–700 m, miền Nam dưới 900–1000 m;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Phía Bắc là toàn bộ lãnh thổ tới dãy Bạch Mã.","Hay nhầm: Chưa đúng với nội dung bài học: Phía Bắc là toàn bộ lãnh thổ tới dãy Bạch Mã.","Hay nhầm: Chưa đúng với nội dung bài học: Phía Bắc là toàn bộ lãnh thổ tới dãy Bạch Mã.","Hay nhầm: Chưa đúng với nội dung bài học: Độ cao từ 2 600 m trở lên, chỉ có ở Hoàng Liên Sơn.","Hay nhầm: Chưa đúng với nội dung bài học: Độ cao từ 2 600 m trở lên, chỉ có ở Hoàng Liên Sơn.","Hay nhầm: Chưa đúng với nội dung bài học: Độ cao từ 2 600 m trở lên, chỉ có ở Hoàng Liên Sơn."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}},{"t":"Bài 4. Thực hành: Viết báo cáo về sự phân hóa tự nhiên Việt Nam","sum":["Nhiệm vụ: thu thập tài liệu (sách, báo, internet) về sự phân hóa tự nhiên Việt Nam; chọn một thành phần tự nhiên (địa hình, khí hậu hoặc sinh vật); viết và trình bày báo cáo về sự phân hóa của thành…","Nhiệm vụ: Thu thập tài liệu (sách, báo, internet) về sự phân hóa tự nhiên Việt Nam; chọn một thành phần tự nhiên (địa hình, khí hậu hoặc sinh vật); viết và…","Từ khoá cần ghi nhớ: Báo cáo; phân hoá tự nhiên;","Điểm nhấn ghi nhớ: Chọn một thành phần tự nhiên và phân tích theo bắc – nam, đông – tây hoặc độ cao","Cấu trúc báo cáo gợi ý: Mở đầu nêu mục tiêu và thành phần tự nhiên được chọn"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Cần xác định chủ đề, mục tiêu rồi thu thập tài liệu.","Hay nhầm: Chưa đúng với nội dung bài học: Cần xác định chủ đề, mục tiêu rồi thu thập tài liệu.","Hay nhầm: Chưa đúng với nội dung bài học: Cần xác định chủ đề, mục tiêu rồi thu thập tài liệu.","Hay nhầm: Chưa đúng với nội dung bài học: Cần dùng nguồn chính thống, có trích dẫn.","Hay nhầm: Chưa đúng với nội dung bài học: Cần dùng nguồn chính thống, có trích dẫn.","Hay nhầm: Chưa đúng với nội dung bài học: Cần dùng nguồn chính thống, có trích dẫn."],"q":{"n":10,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":3,"Nâng cao":1}}},{"t":"Bài 5. Vấn đề sử dụng hợp lí tài nguyên thiên nhiên và bảo vệ môi trường","sum":["Tài nguyên đất: năm 2021 tổng diện tích đất tự nhiên hơn 33,1 triệu ha, trong đó đất nông nghiệp 84,5%, đất phi nông nghiệp 11,9%, đất chưa sử dụng 3,6%.","Tài nguyên đất: Năm 2021 tổng diện tích đất tự nhiên hơn 33,1 triệu ha, trong đó đất nông nghiệp 84,5%, đất phi nông nghiệp 11,9%, đất chưa sử dụng 3,6%.","Từ khoá cần ghi nhớ: Tài nguyên đất; thoái hoá đất; tài nguyên rừng; tài nguyên nước; bảo vệ môi trường.","Điểm nhấn ghi nhớ: Năm 2021 đất nông nghiệp chiếm 84,5% diện tích đất tự nhiên;","Tài nguyên sinh vật: Suy giảm rừng và đa dạng sinh học (diện tích rừng tự nhiên giảm mạnh từ 1943 đến nay; nhiều loài có nguy cơ tuyệt chủng, rừng nguyên sinh còn rất ít).","Tài nguyên nước suy giảm và ô…: Tài nguyên nước suy giảm và ô nhiễm (nhất là đồng bằng sông Cửu Long thiếu nước ngọt mùa khô) do biến đổi khí hậu, khai thác quá mức, nước thải, lạm…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Đất nông nghiệp chiếm 84,5%.","Hay nhầm: Chưa đúng với nội dung bài học: Đất nông nghiệp chiếm 84,5%.","Hay nhầm: Chưa đúng với nội dung bài học: Đất nông nghiệp chiếm 84,5%.","Hay nhầm: Chưa đúng với nội dung bài học: Ruộng bậc thang, hố vảy cá hạn chế xói mòn.","Hay nhầm: Chưa đúng với nội dung bài học: Ruộng bậc thang, hố vảy cá hạn chế xói mòn.","Hay nhầm: Chưa đúng với nội dung bài học: Ruộng bậc thang, hố vảy cá hạn chế xói mòn."],"q":{"n":13,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Phần 2. Địa lí dân cư","l":[{"t":"Bài 6. Dân số Việt Nam","sum":["Quy mô và gia tăng: năm 2021 Việt Nam có 98,5 triệu người, đứng thứ 3 Đông Nam Á, thứ 8 châu Á, thứ 15 thế giới.","Quy mô và gia tăng: Năm 2021 Việt Nam có 98,5 triệu người, đứng thứ 3 Đông Nam Á, thứ 8 châu Á, thứ 15 thế giới.","Từ khoá cần ghi nhớ: Quy mô dân số; gia tăng; cơ cấu giới tính; cơ cấu tuổi; già hoá; mất cân bằng giới tính khi sinh.","Điểm nhấn ghi nhớ: Năm 2021 có 98,5 triệu người, đứng thứ 3 Đông Nam Á, thứ 15 thế giới","Cơ cấu giới tính khá cân bằng: Năm 2021 nam 49,84%, nữ 50,16% (100 nữ có khoảng 99,4 nam); song mất cân bằng giới tính khi sinh (100 bé gái tương ứng 112 bé trai năm 2021).","Phân bố dân cư: Mật độ dân số năm 2021 là 297 người/km², cao gấp 5 lần mức trung bình thế giới, chênh lệch giữa các vùng (đồng bằng sông Hồng 1 091 người/km², Tây…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Việt Nam có 98,5 triệu người năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Việt Nam có 98,5 triệu người năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Việt Nam có 98,5 triệu người năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Đứng thứ 3 khu vực Đông Nam Á.","Hay nhầm: Chưa đúng với nội dung bài học: Đứng thứ 3 khu vực Đông Nam Á.","Hay nhầm: Chưa đúng với nội dung bài học: Đứng thứ 3 khu vực Đông Nam Á."],"q":{"n":16,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 7. Lao động và việc làm","sum":["Nguồn lao động: năm 2021 lực lượng lao động (từ 15 tuổi trở lên) khoảng 50,6 triệu người, chiếm hơn 51% dân số; mỗi năm tăng thêm khoảng 1 triệu người.","Nguồn lao động: Năm 2021 lực lượng lao động (từ 15 tuổi trở lên) khoảng 50,6 triệu người, chiếm hơn 51% dân số; mỗi năm tăng thêm khoảng 1 triệu người.","Từ khoá cần ghi nhớ: Lực lượng lao động; chất lượng lao động; việc làm; tuổi nghỉ hưu; chuyển dịch lao động.","Điểm nhấn ghi nhớ: Năm 2021 lực lượng lao động khoảng 50,6 triệu người; tuổi nghỉ hưu nam 62 (2028), nữ 60 (2035)","Chất lượng lao động: Cần cù, sáng tạo, năng động, dễ tiếp thu khoa học công nghệ; còn hạn chế về thể lực, trình độ chuyên môn kĩ thuật và tác phong công nghiệp.","Sử dụng lao động: Theo ngành, giảm tỉ lệ nông – lâm – thủy sản (65,1% năm 2000 xuống 29,1% năm 2021), tăng công nghiệp và xây dựng (13,1% lên 33,1%), dịch vụ (21,8%…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Quy định độ tuổi lao động tối thiểu là đủ 15 tuổi.","Hay nhầm: Chưa đúng với nội dung bài học: Quy định độ tuổi lao động tối thiểu là đủ 15 tuổi.","Hay nhầm: Chưa đúng với nội dung bài học: Quy định độ tuổi lao động tối thiểu là đủ 15 tuổi.","Hay nhầm: Chưa đúng với nội dung bài học: Chiếm 22,5% tổng số lao động cả nước.","Hay nhầm: Chưa đúng với nội dung bài học: Chiếm 22,5% tổng số lao động cả nước.","Hay nhầm: Chưa đúng với nội dung bài học: Chiếm 22,5% tổng số lao động cả nước."],"q":{"n":14,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 8. Đô thị hóa","sum":["Đặc điểm đô thị hóa: thế kỉ II TCN có đô thị đầu tiên là Thành Cổ Loa; trước 1975 đô thị hóa chậm; từ Đổi mới (1986) đô thị hóa nhanh hơn.","Đặc điểm đô thị hóa: Thế kỉ II TCN có đô thị đầu tiên là Thành Cổ Loa; trước 1975 đô thị hóa chậm; từ Đổi mới (1986) đô thị hóa nhanh hơn.","Từ khoá cần ghi nhớ: Đô thị hoá;","Điểm nhấn ghi nhớ: Đô thị đầu tiên là Thành Cổ Loa (thế kỉ II TCN); tỉ lệ dân thành thị tăng từ 18,3% (1970) lên 37,1% (2021)","Số đô thị: 652 (2001), 732 (2011), 749 (2021); số thành phố tăng nhanh nhất (25 lên 87).","Ảnh hưởng tích cực: Chuyển dịch lao động từ nông nghiệp sang công nghiệp, dịch vụ năng suất cao;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Thế kỉ II TCN, Cổ Loa là kinh đô nước Âu Lạc.","Hay nhầm: Chưa đúng với nội dung bài học: Thế kỉ II TCN, Cổ Loa là kinh đô nước Âu Lạc.","Hay nhầm: Chưa đúng với nội dung bài học: Thế kỉ II TCN, Cổ Loa là kinh đô nước Âu Lạc.","Hay nhầm: Chưa đúng với nội dung bài học: Hai đô thị đặc biệt là Hà Nội và TP. Hồ Chí Minh.","Hay nhầm: Chưa đúng với nội dung bài học: Hai đô thị đặc biệt là Hà Nội và TP. Hồ Chí Minh.","Hay nhầm: Chưa đúng với nội dung bài học: Hai đô thị đặc biệt là Hà Nội và TP. Hồ Chí Minh."],"q":{"n":14,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 9. Thực hành: Viết báo cáo về một chủ đề dân cư ở Việt Nam","sum":["Nội dung: sưu tầm thông tin và viết báo cáo về một chủ đề dân cư: chiến lược dân số qua các thời kì; thực trạng sử dụng lao động và giải pháp nâng cao chất lượng lao động; tác động của đô thị hóa…","Nội dung: Sưu tầm thông tin và viết báo cáo về một chủ đề dân cư: chiến lược dân số qua các thời kì; thực trạng sử dụng lao động và giải pháp nâng cao chất…","Từ khoá cần ghi nhớ: Báo cáo; chiến lược dân số; chất lượng lao động;","Điểm nhấn ghi nhớ: Nguồn tư liệu: bài 6, 7, 8 và số liệu của Tổng cục Thống kê","Nguồn tư liệu: Nội dung bài 6, 7, 8; website Tổng cục Thống kê (gso.gov.vn); cổng thông tin Bộ Xây dựng; trang lưu trữ văn bản Chính phủ."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Chọn chủ đề rồi xây dựng đề cương.","Hay nhầm: Chưa đúng với nội dung bài học: Chọn chủ đề rồi xây dựng đề cương.","Hay nhầm: Chưa đúng với nội dung bài học: Chọn chủ đề rồi xây dựng đề cương.","Hay nhầm: Chưa đúng với nội dung bài học: Số liệu chính thống từ Tổng cục Thống kê.","Hay nhầm: Chưa đúng với nội dung bài học: Số liệu chính thống từ Tổng cục Thống kê.","Hay nhầm: Chưa đúng với nội dung bài học: Số liệu chính thống từ Tổng cục Thống kê."],"q":{"n":10,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":3,"Nâng cao":1}}}]},{"t":"Phần 3. Địa lí các ngành kinh tế","l":[{"t":"Bài 10. Chuyển dịch cơ cấu kinh tế","sum":["Ý nghĩa: phát huy lợi thế so sánh, khai thác hợp lí nguồn lực, tái cơ cấu kinh tế hiệu quả hơn;","Ý nghĩa: Phát huy lợi thế so sánh, khai thác hợp lí nguồn lực, tái cơ cấu kinh tế hiệu quả hơn;","Từ khoá cần ghi nhớ: Chuyển dịch cơ cấu kinh tế; lợi thế so sánh; tái cơ cấu; chuỗi giá trị toàn cầu; hội nhập.","Điểm nhấn ghi nhớ: Chuyển dịch cơ cấu kinh tế nhằm khai thác hợp lí nguồn lực và tăng năng lực cạnh tranh","Chuyển dịch theo hướng công nghiệp hóa, hiện đại hóa: Tỉ trọng công nghiệp và dịch vụ ngày càng tăng, cơ cấu lao động chuyển dịch theo hướng gia tăng lao động có kĩ thuật;","Theo ngành: Giảm tỉ trọng nông, lâm, thủy sản; tăng công nghiệp – xây dựng và dịch vụ; công nghiệp là động lực chính tăng trưởng."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Phù hợp với công nghiệp hóa, hiện đại hóa.","Hay nhầm: Chưa đúng với nội dung bài học: Phù hợp với công nghiệp hóa, hiện đại hóa.","Hay nhầm: Chưa đúng với nội dung bài học: Phù hợp với công nghiệp hóa, hiện đại hóa.","Hay nhầm: Chưa đúng với nội dung bài học: Hình thành 6 vùng kinh tế – xã hội.","Hay nhầm: Chưa đúng với nội dung bài học: Hình thành 6 vùng kinh tế – xã hội.","Hay nhầm: Chưa đúng với nội dung bài học: Hình thành 6 vùng kinh tế – xã hội."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 11. Vấn đề phát triển ngành nông nghiệp","sum":["Thế mạnh tự nhiên: 3/4 diện tích là đồi núi (đất feralit, thuận lợi cây công nghiệp, cây ăn quả, đồng cỏ chăn nuôi gia súc lớn);","Thế mạnh tự nhiên: 3/4 diện tích là đồi núi (đất feralit, thuận lợi cây công nghiệp, cây ăn quả, đồng cỏ chăn nuôi gia súc lớn);","Từ khoá cần ghi nhớ: Nông nghiệp;","Điểm nhấn ghi nhớ: 3/4 diện tích là đồi núi, 1/4 là đồng bằng phù sa màu mỡ","Kinh tế – xã hội: Dân đông là thị trường lớn; lao động dồi dào, có kinh nghiệm; khoa học công nghệ, cơ sở vật chất kĩ thuật (thủy lợi, chế biến, dịch vụ) ngày càng…","Chuyển dịch cơ cấu nông nghiệp: Giảm tỉ trọng trồng trọt, tăng chăn nuôi và dịch vụ nông nghiệp."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Chiếm 53,8% diện tích và 55,5% sản lượng lúa.","Hay nhầm: Chưa đúng với nội dung bài học: Chiếm 53,8% diện tích và 55,5% sản lượng lúa.","Hay nhầm: Chưa đúng với nội dung bài học: Chiếm 53,8% diện tích và 55,5% sản lượng lúa.","Hay nhầm: Chưa đúng với nội dung bài học: Tây Nguyên là vùng cà phê lớn nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Tây Nguyên là vùng cà phê lớn nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Tây Nguyên là vùng cà phê lớn nhất."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 12. Vấn đề phát triển lâm nghiệp và thủy sản","sum":["Lâm nghiệp: năm 2021 diện tích rừng 14 745,2 nghìn ha (rừng tự nhiên 69,0%, còn lại là rừng trồng), độ che phủ 42,0%.","Lâm nghiệp: Năm 2021 diện tích rừng 14 745,2 nghìn ha (rừng tự nhiên 69,0%, còn lại là rừng trồng), độ che phủ 42,0%.","Từ khoá cần ghi nhớ: Lâm nghiệp; thuỷ sản;","Điểm nhấn ghi nhớ: Năm 2021 diện tích rừng khoảng 14 745,2 nghìn ha;","Hiện trạng: Giá trị lâm nghiệp ~3% giá trị sản xuất nông – lâm – thủy sản, tăng trưởng 6,5%/năm (2010–2021).","Thủy sản – thế mạnh: Trữ lượng hải sản ~4 triệu tấn, khai thác bền vững ~1,5 triệu tấn/năm; hơn 2 000 loài cá, 130 loài cá và 100 loài tôm có giá trị;"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Tỉ lệ che phủ rừng đạt 42,0%.","Hay nhầm: Chưa đúng với nội dung bài học: Tỉ lệ che phủ rừng đạt 42,0%.","Hay nhầm: Chưa đúng với nội dung bài học: Tỉ lệ che phủ rừng đạt 42,0%.","Hay nhầm: Chưa đúng với nội dung bài học: Tiếp theo là Trung du và miền núi Bắc Bộ, Tây Nguyên.","Hay nhầm: Chưa đúng với nội dung bài học: Tiếp theo là Trung du và miền núi Bắc Bộ, Tây Nguyên.","Hay nhầm: Chưa đúng với nội dung bài học: Tiếp theo là Trung du và miền núi Bắc Bộ, Tây Nguyên."],"q":{"n":14,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 13. Tổ chức lãnh thổ nông nghiệp","sum":["Tổ chức lãnh thổ nông nghiệp là các lãnh thổ sản xuất nông nghiệp hình thành để khai thác hợp lí thế mạnh tự nhiên, kinh tế – xã hội.","Khái niệm: Tổ chức lãnh thổ nông nghiệp là các lãnh thổ sản xuất nông nghiệp hình thành để khai thác hợp lí thế mạnh tự nhiên, kinh tế – xã hội.","Từ khoá cần ghi nhớ: Tổ chức lãnh thổ nông nghiệp; trang trại; vùng chuyên canh; vùng nông nghiệp.","Điểm nhấn ghi nhớ: Ba hình thức nổi bật: trang trại, vùng chuyên canh, vùng nông nghiệp","Trang trại: Hình thức tổ chức sản xuất (nông, lâm, thủy sản) có tư liệu sản xuất thuộc quyền sở hữu (trừ đất đai) hoặc quyền sử dụng của một chủ độc lập, quy mô…","Vùng chuyên canh (vùng sản xuất nông nghiệp trọng điểm): Tập trung một hoặc vài loại cây, con phù hợp điều kiện sinh thái và kinh tế – xã hội, tạo khối lượng hàng hóa lớn, gắn với chế biến."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Vùng nông nghiệp là hình thức cao nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Vùng nông nghiệp là hình thức cao nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Vùng nông nghiệp là hình thức cao nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Phương án 7 vùng sinh thái nông nghiệp.","Hay nhầm: Chưa đúng với nội dung bài học: Phương án 7 vùng sinh thái nông nghiệp.","Hay nhầm: Chưa đúng với nội dung bài học: Phương án 7 vùng sinh thái nông nghiệp."],"q":{"n":14,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 14. Thực hành: Vai trò ngành nông, lâm, thủy sản; vẽ biểu đồ và nhận xét","sum":["Nội dung 1: viết báo cáo về vai trò của ngành nông nghiệp, lâm nghiệp, thủy sản đối với các ngành kinh tế khác (cung cấp nguyên liệu cho công nghiệp chế biến, xuất khẩu), đối với xã hội (an ninh…","Nội dung 1: Viết báo cáo về vai trò của ngành nông nghiệp, lâm nghiệp, thủy sản đối với các ngành kinh tế khác (cung cấp nguyên liệu cho công nghiệp chế biến,…","Từ khoá cần ghi nhớ: Vai trò nông nghiệp; lâm nghiệp; thuỷ sản; an ninh lương thực; biểu đồ; nông thôn mới.","Điểm nhấn ghi nhớ: Vai trò: cung cấp nguyên liệu cho công nghiệp, bảo đảm an ninh lương thực, xây dựng nông thôn mới","Nội dung 2: Vẽ biểu đồ quy mô và cơ cấu giá trị sản xuất năm 2010 và 2021 (nghìn tỉ đồng): 2010 tổng 875,9 (nông nghiệp 675,4; lâm nghiệp 22,8; thủy sản 177,7);"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Biểu đồ tròn thể hiện cơ cấu.","Hay nhầm: Chưa đúng với nội dung bài học: Biểu đồ tròn thể hiện cơ cấu.","Hay nhầm: Chưa đúng với nội dung bài học: Biểu đồ tròn thể hiện cơ cấu.","Hay nhầm: Chưa đúng với nội dung bài học: Bán kính thể hiện quy mô.","Hay nhầm: Chưa đúng với nội dung bài học: Bán kính thể hiện quy mô.","Hay nhầm: Chưa đúng với nội dung bài học: Bán kính thể hiện quy mô."],"q":{"n":11,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 15. Chuyển dịch cơ cấu ngành công nghiệp","sum":["Theo ngành: công nghiệp (cấp 1) gồm 4 nhóm với 34 ngành (khai khoáng 5; chế biến, chế tạo 24; sản xuất và phân phối điện, khí đốt, nước nóng, hơi nước, điều hòa không khí 1; cung cấp nước, quản lí…","Theo ngành: Công nghiệp (cấp 1) gồm 4 nhóm với 34 ngành (khai khoáng 5; chế biến, chế tạo 24; sản xuất và phân phối điện, khí đốt, nước nóng, hơi nước, điều hòa…","Từ khoá cần ghi nhớ: Cơ cấu ngành công nghiệp; khai khoáng; chế biến, chế tạo; sản xuất điện; cung cấp nước; cơ cấu giá trị.","Điểm nhấn ghi nhớ: Công nghiệp (cấp 1) gồm 4 nhóm với 34 ngành, theo Quyết định 27/2018/QĐ-TTg","Theo thành phần kinh tế: Giảm tỉ trọng khu vực Nhà nước, tăng ngoài Nhà nước, nhất là khu vực có vốn đầu tư nước ngoài; phù hợp chính sách kinh tế mở, kinh tế thị trường…","Theo lãnh thổ: Thay đổi giá trị sản xuất công nghiệp giữa các vùng và hình thành khu công nghiệp, khu chế xuất, khu công nghệ cao mới."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Chiếm 93,0% năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Chiếm 93,0% năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Chiếm 93,0% năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Phù hợp công nghiệp hóa, hiện đại hóa.","Hay nhầm: Chưa đúng với nội dung bài học: Phù hợp công nghiệp hóa, hiện đại hóa.","Hay nhầm: Chưa đúng với nội dung bài học: Phù hợp công nghiệp hóa, hiện đại hóa."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}},{"t":"Bài 16. Một số ngành công nghiệp","sum":["Công nghiệp khai thác than: khai thác từ đầu thế kỉ XIX; than trên đất liền ở 6 bể (Đông Bắc, An Châu, Lạng Sơn, Nông Sơn, sông Cửu Long, sông Hồng); bể Đông Bắc trữ lượng lớn, bể sông Hồng trữ…","Công nghiệp khai thác than: Khai thác từ đầu thế kỉ XIX; than trên đất liền ở 6 bể (Đông Bắc, An Châu, Lạng Sơn, Nông Sơn, sông Cửu Long, sông Hồng); bể Đông Bắc trữ lượng lớn,…","Từ khoá cần ghi nhớ: Khai thác than; bể than; dầu khí;","Điểm nhấn ghi nhớ: Sản lượng than (triệu tấn): 11,6 (2000), 44,8 (2010), 41,7 (2015), 48,3 (2021)","Dầu mỏ, khí tự nhiên: Phát triển muộn hơn than; dầu thô khai thác chủ yếu ở thềm lục địa phía nam (mỏ Rồng, Bạch Hổ, Rạng Đông, Hồng Ngọc); khí tự nhiên ở các bể Cửu…","Sản xuất điện: Sản lượng năm 2021 đạt 244,9 tỉ kWh; cơ cấu nguồn gồm thủy điện, nhiệt điện (than, khí, dầu), điện mặt trời, điện gió và nguồn khác."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Quảng Ninh là vùng khai thác than lớn nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Quảng Ninh là vùng khai thác than lớn nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Quảng Ninh là vùng khai thác than lớn nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Sơn La trên sông Đà, vận hành từ 2012.","Hay nhầm: Chưa đúng với nội dung bài học: Sơn La trên sông Đà, vận hành từ 2012.","Hay nhầm: Chưa đúng với nội dung bài học: Sơn La trên sông Đà, vận hành từ 2012."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 17. Tổ chức lãnh thổ công nghiệp","sum":["Khu công nghiệp: khu vực có ranh giới xác định, chuyên sản xuất công nghiệp hoặc dịch vụ hỗ trợ; gồm khu chế xuất, khu công nghiệp hỗ trợ, khu công nghiệp sinh thái.","Khu công nghiệp: Khu vực có ranh giới xác định, chuyên sản xuất công nghiệp hoặc dịch vụ hỗ trợ; gồm khu chế xuất, khu công nghiệp hỗ trợ, khu công nghiệp sinh thái.","Từ khoá cần ghi nhớ: Khu công nghiệp; khu chế xuất; khu công nghiệp hỗ trợ; khu công nghiệp sinh thái; hạ tầng.","Điểm nhấn ghi nhớ: Ba loại khu công nghiệp chính: khu chế xuất, khu công nghiệp hỗ trợ, khu công nghiệp sinh thái","Khu công nghệ cao: Nơi tập trung, liên kết nghiên cứu, ứng dụng, ươm tạo và sản xuất công nghệ cao, đào tạo nhân lực công nghệ cao; là động lực phát triển kinh tế, thu…","Trung tâm công nghiệp: Khu vực tập trung công nghiệp, thường gắn với đô thị lớn và vừa; mỗi trung tâm có thể gồm một số khu công nghiệp và xí nghiệp hạt nhân có sức thu…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Khu chế xuất Tân Thuận, TP. Hồ Chí Minh, năm 1991.","Hay nhầm: Chưa đúng với nội dung bài học: Khu chế xuất Tân Thuận, TP. Hồ Chí Minh, năm 1991.","Hay nhầm: Chưa đúng với nội dung bài học: Khu chế xuất Tân Thuận, TP. Hồ Chí Minh, năm 1991.","Hay nhầm: Chưa đúng với nội dung bài học: Nơi có vị trí, hạ tầng và lao động thuận lợi.","Hay nhầm: Chưa đúng với nội dung bài học: Nơi có vị trí, hạ tầng và lao động thuận lợi.","Hay nhầm: Chưa đúng với nội dung bài học: Nơi có vị trí, hạ tầng và lao động thuận lợi."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":2,"Nâng cao":1}}},{"t":"Bài 18. Thực hành: Vẽ biểu đồ, nhận xét và giải thích tình hình phát triển ngành công nghiệp","sum":["Nội dung 1: dựa vào bảng giá trị sản xuất công nghiệp (nghìn tỉ đồng): 2010: 3 045,6; 2020: 11 880,4;","Nội dung 1: Dựa vào bảng giá trị sản xuất công nghiệp (nghìn tỉ đồng): 2010: 3 045,6;","Từ khoá cần ghi nhớ: Biểu đồ cột; giá trị sản xuất công nghiệp; nhận xét; giải thích;","Điểm nhấn ghi nhớ: Giá trị sản xuất công nghiệp tăng từ 3 045,6 nghìn tỉ (2010) lên 13 026,8 nghìn tỉ (2021)","Nội dung 2: Nhận xét sự thay đổi sản lượng và cơ cấu nguồn điện năm 2010 và 2021 (sản lượng tăng mạnh; thủy điện, nhiệt điện chiếm tỉ trọng lớn nhưng cơ cấu…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Thể hiện sự thay đổi theo thời gian.","Hay nhầm: Chưa đúng với nội dung bài học: Thể hiện sự thay đổi theo thời gian.","Hay nhầm: Chưa đúng với nội dung bài học: Thể hiện sự thay đổi theo thời gian.","Hay nhầm: Chưa đúng với nội dung bài học: Đó là các nhân tố chính.","Hay nhầm: Chưa đúng với nội dung bài học: Đó là các nhân tố chính.","Hay nhầm: Chưa đúng với nội dung bài học: Đó là các nhân tố chính."],"q":{"n":8,"lv":{"Biết":1,"Hiểu":3,"Vận dụng":3,"Nâng cao":1}}},{"t":"Bài 19. Vai trò, các nhân tố ảnh hưởng đến phát triển và phân bố ngành dịch vụ","sum":["Vai trò: dịch vụ chiếm tỉ trọng cao trong GDP (41,2% năm 2021), góp phần công nghiệp hóa, hiện đại hóa; nâng cao trình độ sản xuất, kết nối các ngành, các vùng, tăng hội nhập; thúc đẩy đổi mới,…","Vai trò: Dịch vụ chiếm tỉ trọng cao trong GDP (41,2% năm 2021), góp phần công nghiệp hóa, hiện đại hóa; nâng cao trình độ sản xuất, kết nối các ngành, các…","Từ khoá cần ghi nhớ: Dịch vụ; tỉ trọng GDP; nhân tố ảnh hưởng; chuyển đổi số; kinh tế số; xoá đói giảm nghèo.","Điểm nhấn ghi nhớ: Dịch vụ chiếm 41,2% GDP năm 2021","Các nhân tố: Trình độ phát triển kinh tế – sản xuất vật chất phát triển thì dịch vụ mở rộng (giao thông, xuất nhập khẩu, bưu chính viễn thông theo vùng kinh tế…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Dịch vụ chiếm 41,2% GDP năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Dịch vụ chiếm 41,2% GDP năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Dịch vụ chiếm 41,2% GDP năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Nơi dân cư đông, đô thị lớn.","Hay nhầm: Chưa đúng với nội dung bài học: Nơi dân cư đông, đô thị lớn.","Hay nhầm: Chưa đúng với nội dung bài học: Nơi dân cư đông, đô thị lớn."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":2,"Nâng cao":1}}},{"t":"Bài 20. Giao thông vận tải và bưu chính viễn thông","sum":["Giao thông vận tải: đủ loại hình (ô tô, sắt, sông, biển, hàng không, ống); kết nối đường quốc tế;","Giao thông vận tải: Đủ loại hình (ô tô, sắt, sông, biển, hàng không, ống); kết nối đường quốc tế;","Từ khoá cần ghi nhớ: Giao thông vận tải;","Điểm nhấn ghi nhớ: Hà Nội, Đà Nẵng và TP Hồ Chí Minh là các đầu mối giao thông, cửa ngõ quốc tế","Đường sắt: Tuyến Bắc – Nam (Thống Nhất) dài và quan trọng nhất; các tuyến khác ở phía bắc: Hà Nội – Hải Phòng, Hà Nội – Lào Cai, Hà Nội – Lạng Sơn;","Bưu chính viễn thông: Phát triển theo hướng chuyển đổi số."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Khối lượng vận chuyển hàng hóa cao nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Khối lượng vận chuyển hàng hóa cao nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Khối lượng vận chuyển hàng hóa cao nhất.","Hay nhầm: Chưa đúng với nội dung bài học: Hai cảng loại đặc biệt.","Hay nhầm: Chưa đúng với nội dung bài học: Hai cảng loại đặc biệt.","Hay nhầm: Chưa đúng với nội dung bài học: Hai cảng loại đặc biệt."],"q":{"n":14,"lv":{"Biết":5,"Hiểu":4,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 21. Thương mại và du lịch","sum":["Nội thương: tổng mức bán lẻ hàng hóa và doanh thu dịch vụ tiêu dùng tăng nhanh, liên tục; đa dạng loại hình (chợ truyền thống, siêu thị, trung tâm thương mại, cửa hàng tiện ích); thương mại điện tử…","Nội thương: Tổng mức bán lẻ hàng hóa và doanh thu dịch vụ tiêu dùng tăng nhanh, liên tục;","Từ khoá cần ghi nhớ: Nội thương; ngoại thương; thương mại điện tử; du lịch; trung tâm thương mại; siêu thị.","Điểm nhấn ghi nhớ: Hà Nội và TP Hồ Chí Minh là hai trung tâm thương mại lớn nhất; thương mại điện tử tăng nhanh","Ngoại thương: Năm 2021 tổng trị giá xuất nhập khẩu 669,0 tỉ USD; xuất khẩu 336,1 tỉ USD (50,2%), nhập khẩu 332,9 tỉ USD (49,8%), xuất siêu 3,2 tỉ USD.","Du lịch: Là ngành kinh tế mũi nhọn; doanh thu và khách tăng nhanh 2000–2019, phục hồi từ năm 2022 sau dịch bệnh."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Hai trung tâm thương mại lớn nhất cả nước.","Hay nhầm: Chưa đúng với nội dung bài học: Hai trung tâm thương mại lớn nhất cả nước.","Hay nhầm: Chưa đúng với nội dung bài học: Hai trung tâm thương mại lớn nhất cả nước.","Hay nhầm: Chưa đúng với nội dung bài học: Xuất khẩu 336,1, nhập khẩu 332,9 tỉ USD.","Hay nhầm: Chưa đúng với nội dung bài học: Xuất khẩu 336,1, nhập khẩu 332,9 tỉ USD.","Hay nhầm: Chưa đúng với nội dung bài học: Xuất khẩu 336,1, nhập khẩu 332,9 tỉ USD."],"q":{"n":14,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 22. Thực hành: Tìm hiểu sự phát triển một số ngành dịch vụ","sum":["Nội dung: tìm hiểu thực tế và viết báo cáo về một hoạt động dịch vụ độc đáo ở địa phương: hoạt động thương mại (chợ truyền thống, trung tâm thương mại) hoặc sản phẩm du lịch đặc sắc.","Nội dung: Tìm hiểu thực tế và viết báo cáo về một hoạt động dịch vụ độc đáo ở địa phương: hoạt động thương mại (chợ truyền thống, trung tâm thương mại) hoặc…","Từ khoá cần ghi nhớ: Báo cáo; hoạt động dịch vụ; chợ truyền thống; trung tâm thương mại; du lịch địa phương; khảo sát thực tế.","Điểm nhấn ghi nhớ: Viết báo cáo về một hoạt động dịch vụ độc đáo ở địa phương"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Cần nguồn tin cậy, kiểm chứng.","Hay nhầm: Chưa đúng với nội dung bài học: Cần nguồn tin cậy, kiểm chứng.","Hay nhầm: Chưa đúng với nội dung bài học: Cần nguồn tin cậy, kiểm chứng.","Hay nhầm: Chưa đúng với nội dung bài học: Theo gợi ý thực hiện.","Hay nhầm: Chưa đúng với nội dung bài học: Theo gợi ý thực hiện.","Hay nhầm: Chưa đúng với nội dung bài học: Theo gợi ý thực hiện."],"q":{"n":7,"lv":{"Biết":1,"Hiểu":3,"Vận dụng":2,"Nâng cao":1}}}]},{"t":"Phần 4. Địa lí các vùng kinh tế","l":[{"t":"Bài 23. Khai thác thế mạnh ở Trung du và miền núi Bắc Bộ","sum":["Khái quát: vùng gồm 14 tỉnh (Lai Châu, Điện Biên, Sơn La, Hòa Bình, Lào Cai, Yên Bái, Phú Thọ, Hà Giang, Tuyên Quang, Cao Bằng, Lạng Sơn, Bắc Kạn, Thái Nguyên, Bắc Giang); diện tích 95,2 nghìn km²…","Khái quát: Vùng gồm 14 tỉnh (Lai Châu, Điện Biên, Sơn La, Hòa Bình, Lào Cai, Yên Bái, Phú Thọ, Hà Giang, Tuyên Quang, Cao Bằng, Lạng Sơn, Bắc Kạn, Thái Nguyên,…","Từ khoá cần ghi nhớ: Trung du và miền núi Bắc Bộ;","Điểm nhấn ghi nhớ: Vùng gồm 14 tỉnh, diện tích khoảng 95,2 nghìn km² (2021)","Khoáng sản: Giàu nhất nước ta; than (Lạng Sơn, Thái Nguyên), sắt (Yên Bái, Lào Cai, Hà Giang), đồng (Sơn La, Bắc Giang), đồng – vàng (Lào Cai), thiếc (Cao Bằng,…","Thủy điện: Tiềm năng lớn nhất nước; hệ thống sông Hồng chiếm trên 30% trữ năng thủy điện cả nước (11 triệu kW), sông Đà gần 6 triệu kW."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Nhiều loại khoáng sản trữ lượng lớn.","Hay nhầm: Chưa đúng với nội dung bài học: Nhiều loại khoáng sản trữ lượng lớn.","Hay nhầm: Chưa đúng với nội dung bài học: Nhiều loại khoáng sản trữ lượng lớn.","Hay nhầm: Chưa đúng với nội dung bài học: Công suất 1 200, 2 400, 1 920 MW.","Hay nhầm: Chưa đúng với nội dung bài học: Công suất 1 200, 2 400, 1 920 MW.","Hay nhầm: Chưa đúng với nội dung bài học: Công suất 1 200, 2 400, 1 920 MW."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 24. Phát triển kinh tế - xã hội ở Đồng bằng sông Hồng","sum":["Khái quát: vùng gồm 2 thành phố trực thuộc Trung ương (Hà Nội, Hải Phòng) và 9 tỉnh (Hải Dương, Hà Nam, Nam Định, Thái Bình, Hưng Yên, Ninh Bình, Vĩnh Phúc, Bắc Ninh, Quảng Ninh); diện tích 21,3…","Khái quát: Vùng gồm 2 thành phố trực thuộc Trung ương (Hà Nội, Hải Phòng) và 9 tỉnh (Hải Dương, Hà Nam, Nam Định, Thái Bình, Hưng Yên, Ninh Bình, Vĩnh Phúc,…","Từ khoá cần ghi nhớ: Đồng bằng sông Hồng;","Điểm nhấn ghi nhớ: Vùng gồm 2 thành phố trực thuộc Trung ương và 9 tỉnh, diện tích 21,3 nghìn km² (2021)","Thế mạnh tự nhiên: Đồng bằng phù sa do sông Hồng, sông Thái Bình bồi đắp, đất màu mỡ;","Kinh tế – xã hội: Lao động dồi dào, trình độ cao nhất cả nước (37,0% lao động qua đào tạo năm 2021); cơ sở hạ tầng tốt nhất cả nước; chính sách tái cơ cấu, kinh tế…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: 23,2 triệu người, 1 091 người/km².","Hay nhầm: Chưa đúng với nội dung bài học: 23,2 triệu người, 1 091 người/km².","Hay nhầm: Chưa đúng với nội dung bài học: 23,2 triệu người, 1 091 người/km².","Hay nhầm: Chưa đúng với nội dung bài học: Cùng 9 tỉnh.","Hay nhầm: Chưa đúng với nội dung bài học: Cùng 9 tỉnh.","Hay nhầm: Chưa đúng với nội dung bài học: Cùng 9 tỉnh."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 25. Phát triển nông nghiệp, lâm nghiệp và thủy sản ở Bắc Trung Bộ","sum":["Khái quát: Bắc Trung Bộ gồm 6 tỉnh (Thanh Hóa, Nghệ An, Hà Tĩnh, Quảng Bình, Quảng Trị, Thừa Thiên Huế), diện tích 51,2 nghìn km², là một phần của vùng Bắc Trung Bộ và Duyên hải miền Trung (theo…","Khái quát: Bắc Trung Bộ gồm 6 tỉnh (Thanh Hóa, Nghệ An, Hà Tĩnh, Quảng Bình, Quảng Trị, Thừa Thiên Huế), diện tích 51,2 nghìn km², là một phần của vùng Bắc…","Từ khoá cần ghi nhớ: Bắc Trung Bộ;","Điểm nhấn ghi nhớ: Bắc Trung Bộ gồm 6 tỉnh, từ Thanh Hoá đến Thừa Thiên Huế; diện tích 51,2 nghìn km²","Thế mạnh: Lãnh thổ hẹp ngang, trên 70% diện tích là đồi núi (tây đồi núi – đồng bằng chuyển tiếp – biển đảo ở đông);","Nông nghiệp: Chiếm 74,5% giá trị sản xuất nông – lâm – thủy sản (2021)."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Thanh Hóa, Nghệ An, Hà Tĩnh, Quảng Bình, Quảng Trị, Thừa Thiên Huế.","Hay nhầm: Chưa đúng với nội dung bài học: Thanh Hóa, Nghệ An, Hà Tĩnh, Quảng Bình, Quảng Trị, Thừa Thiên Huế.","Hay nhầm: Chưa đúng với nội dung bài học: Thanh Hóa, Nghệ An, Hà Tĩnh, Quảng Bình, Quảng Trị, Thừa Thiên Huế.","Hay nhầm: Chưa đúng với nội dung bài học: Đồng bằng lớn, đất phù sa.","Hay nhầm: Chưa đúng với nội dung bài học: Đồng bằng lớn, đất phù sa.","Hay nhầm: Chưa đúng với nội dung bài học: Đồng bằng lớn, đất phù sa."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 26. Phát triển kinh tế biển ở Duyên hải Nam Trung Bộ","sum":["Khái quát: vùng gồm 8 tỉnh, thành phố (Đà Nẵng, Quảng Nam, Quảng Ngãi, Bình Định, Phú Yên, Khánh Hòa, Ninh Thuận, Bình Thuận), diện tích hơn 44 nghìn km²; giáp Bắc Trung Bộ, Tây Nguyên, Đông Nam Bộ…","Khái quát: Vùng gồm 8 tỉnh, thành phố (Đà Nẵng, Quảng Nam, Quảng Ngãi, Bình Định, Phú Yên, Khánh Hòa, Ninh Thuận, Bình Thuận), diện tích hơn 44 nghìn km²; giáp…","Từ khoá cần ghi nhớ: Duyên hải Nam Trung Bộ;","Điểm nhấn ghi nhớ: Vùng gồm 8 tỉnh, thành phố, diện tích hơn 44 nghìn km²","Thế mạnh: Bờ biển dài, hải sản phong phú (tôm he, tôm hùm, cá mú, cá ngừ, ngọc trai); ngư trường Ninh Thuận – Bình Thuận – Bà Rịa – Vũng Tàu, Hoàng Sa –…","Khai thác sinh vật biển: Thủy sản đóng góp 6,5% GRDP (2021); hải sản khai thác chiếm gần 90% sản lượng hải sản vùng; sản lượng cá biển 996 nghìn tấn (2021); cá ngừ đại dương…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Công suất 6,5 triệu tấn/năm.","Hay nhầm: Chưa đúng với nội dung bài học: Công suất 6,5 triệu tấn/năm.","Hay nhầm: Chưa đúng với nội dung bài học: Công suất 6,5 triệu tấn/năm.","Hay nhầm: Chưa đúng với nội dung bài học: Huyện đảo Trường Sa thuộc Khánh Hòa.","Hay nhầm: Chưa đúng với nội dung bài học: Huyện đảo Trường Sa thuộc Khánh Hòa.","Hay nhầm: Chưa đúng với nội dung bài học: Huyện đảo Trường Sa thuộc Khánh Hòa."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 27. Thực hành: Viết báo cáo về ý nghĩa của phát triển kinh tế biển đối với quốc phòng an ninh ở Duyên hải Nam…","sum":["Nội dung: thu thập thông tin từ sách, báo, tạp chí, internet và viết báo cáo về ý nghĩa của phát triển kinh tế biển đối với quốc phòng an ninh ở Duyên hải Nam Trung Bộ.","Nội dung: Thu thập thông tin từ sách, báo, tạp chí, internet và viết báo cáo về ý nghĩa của phát triển kinh tế biển đối với quốc phòng an ninh ở Duyên hải Nam…","Từ khoá cần ghi nhớ: Kinh tế biển; quốc phòng an ninh; cảng biển;","Điểm nhấn ghi nhớ: Phát triển kinh tế biển gắn với bảo vệ quốc phòng an ninh trên các đảo"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Cần nguồn tin cậy.","Hay nhầm: Chưa đúng với nội dung bài học: Cần nguồn tin cậy.","Hay nhầm: Chưa đúng với nội dung bài học: Cần nguồn tin cậy.","Hay nhầm: Chưa đúng với nội dung bài học: Hiện diện thường xuyên trên biển.","Hay nhầm: Chưa đúng với nội dung bài học: Hiện diện thường xuyên trên biển.","Hay nhầm: Chưa đúng với nội dung bài học: Hiện diện thường xuyên trên biển."],"q":{"n":8,"lv":{"Biết":1,"Hiểu":4,"Vận dụng":2,"Nâng cao":1}}},{"t":"Bài 28. Khai thác thế mạnh để phát triển kinh tế ở Tây Nguyên","sum":["Khái quát: Tây Nguyên gồm 5 tỉnh (Kon Tum, Gia Lai, Đắk Lắk, Đắk Nông, Lâm Đồng); diện tích 54,5 nghìn km² (2021); giáp Lào, Cam-pu-chia, Đông Nam Bộ, Bắc Trung Bộ và Duyên hải miền Trung; vị trí…","Khái quát: Tây Nguyên gồm 5 tỉnh (Kon Tum, Gia Lai, Đắk Lắk, Đắk Nông, Lâm Đồng); diện tích 54,5 nghìn km² (2021); giáp Lào, Cam-pu-chia, Đông Nam Bộ, Bắc…","Từ khoá cần ghi nhớ: Tây Nguyên;","Điểm nhấn ghi nhớ: Vùng gồm 5 tỉnh, diện tích 54,5 nghìn km², mật độ khoảng 111 người/km², thấp nhất cả nước","Cây công nghiệp lâu năm: Cao nguyên xếp tầng (Kon Tum, Pleiku, Đắk Lắk, Lâm Viên, Mơ Nông, Di Linh), đất badan lớn, khí hậu cận xích đạo phân hóa theo độ cao và mùa, sông Sê…","Lâm nghiệp: Rừng hơn 2,5 triệu ha, chiếm 17,5% rừng cả nước (2021); vườn quốc gia Yok Đôn, Kon Ka Kinh, Chư Mom Ray, Chư Yang Sin; khu dự trữ sinh quyển thế…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Chiếm khoảng 90% diện tích cà phê cả nước.","Hay nhầm: Chưa đúng với nội dung bài học: Chiếm khoảng 90% diện tích cà phê cả nước.","Hay nhầm: Chưa đúng với nội dung bài học: Chiếm khoảng 90% diện tích cà phê cả nước.","Hay nhầm: Chưa đúng với nội dung bài học: Đắk Lắk dẫn đầu.","Hay nhầm: Chưa đúng với nội dung bài học: Đắk Lắk dẫn đầu.","Hay nhầm: Chưa đúng với nội dung bài học: Đắk Lắk dẫn đầu."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 29. Phát triển kinh tế - xã hội ở Đông Nam Bộ","sum":["Khái quát: vùng gồm TP. Hồ Chí Minh và 5 tỉnh (Bình Dương, Bình Phước, Tây Ninh, Đồng Nai, Bà Rịa – Vũng Tàu); diện tích 23,6 nghìn km²; giáp Cam-pu-chia, đồng bằng sông Cửu Long, Tây Nguyên, Bắc…","Khái quát: Vùng gồm TP.","Từ khoá cần ghi nhớ: Đông Nam Bộ;","Điểm nhấn ghi nhớ: Vùng gồm TP Hồ Chí Minh và 5 tỉnh, diện tích 23,6 nghìn km²","Thế mạnh tự nhiên: Địa hình bằng phẳng;","Công nghiệp: GRDP vùng chiếm hơn 30% GDP cả nước (2021)."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: 66,4% năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: 66,4% năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: 66,4% năm 2021.","Hay nhầm: Chưa đúng với nội dung bài học: Có vai trò quan trọng với cả nước.","Hay nhầm: Chưa đúng với nội dung bài học: Có vai trò quan trọng với cả nước.","Hay nhầm: Chưa đúng với nội dung bài học: Có vai trò quan trọng với cả nước."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 30. Sử dụng hợp lí tự nhiên để phát triển kinh tế ở Đồng bằng sông Cửu Long","sum":["Khái quát: diện tích 40,9 nghìn km²; gồm TP. Cần Thơ và 12 tỉnh (Long An, Vĩnh Long, Tiền Giang, Bến Tre, Hậu Giang, Sóc Trăng, Trà Vinh, Bạc Liêu, Đồng Tháp, An Giang, Kiên Giang, Cà Mau); vùng đất…","Khái quát: Diện tích 40,9 nghìn km²; gồm TP.","Từ khoá cần ghi nhớ: Đồng bằng sông Cửu Long;","Điểm nhấn ghi nhớ: Vùng gồm TP Cần Thơ và 12 tỉnh, diện tích 40,9 nghìn km²","Thế mạnh tự nhiên: Đồng bằng châu thổ lớn nhất, thấp, bằng phẳng; ba loại đất chính: phù sa sông (hơn 1 triệu ha, dọc sông Tiền, sông Hậu), đất phèn (hơn 1,6 triệu ha:…","Sử dụng hợp lí tự nhiên: Vùng là trọng điểm sản xuất lương thực, thực phẩm lớn nhất cả nước nhưng đất phèn, mặn, khô hạn, mất cân bằng nguồn nước, biến đổi khí hậu."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Địa hình thấp, bằng phẳng.","Hay nhầm: Chưa đúng với nội dung bài học: Địa hình thấp, bằng phẳng.","Hay nhầm: Chưa đúng với nội dung bài học: Địa hình thấp, bằng phẳng.","Hay nhầm: Chưa đúng với nội dung bài học: Đất phèn hơn 1,6 triệu ha.","Hay nhầm: Chưa đúng với nội dung bài học: Đất phèn hơn 1,6 triệu ha.","Hay nhầm: Chưa đúng với nội dung bài học: Đất phèn hơn 1,6 triệu ha."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 31. Thực hành: Viết báo cáo về biến đổi khí hậu ở Đồng bằng sông Cửu Long","sum":["Nội dung: tìm hiểu và viết báo cáo về ảnh hưởng và giải pháp ứng phó với biến đổi khí hậu ở đồng bằng sông Cửu Long.","Nội dung: Tìm hiểu và viết báo cáo về ảnh hưởng và giải pháp ứng phó với biến đổi khí hậu ở đồng bằng sông Cửu Long.","Từ khoá cần ghi nhớ: Biến đổi khí hậu;","Điểm nhấn ghi nhớ: Báo cáo gồm ảnh hưởng và giải pháp ứng phó với biến đổi khí hậu","Gợi ý cấu trúc báo cáo: Ảnh hưởng của biến đổi khí hậu: đến tự nhiên (nước biển dâng, xâm nhập mặn, hạn hán, sạt lở bờ sông, bờ biển, suy giảm đa dạng sinh học), đến hoạt…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Vùng thấp, ven biển.","Hay nhầm: Chưa đúng với nội dung bài học: Vùng thấp, ven biển.","Hay nhầm: Chưa đúng với nội dung bài học: Vùng thấp, ven biển.","Hay nhầm: Chưa đúng với nội dung bài học: Giảm nguyên nhân gây biến đổi khí hậu.","Hay nhầm: Chưa đúng với nội dung bài học: Giảm nguyên nhân gây biến đổi khí hậu.","Hay nhầm: Chưa đúng với nội dung bài học: Giảm nguyên nhân gây biến đổi khí hậu."],"q":{"n":10,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":3,"Nâng cao":1}}},{"t":"Bài 32. Phát triển các vùng kinh tế trọng điểm","sum":["Vùng kinh tế trọng điểm là bộ phận lãnh thổ quốc gia hội tụ điều kiện, yếu tố thuận lợi, tiềm lực kinh tế lớn, giữ vai trò động lực, đầu tàu thúc đẩy phát triển chung.","Khái niệm: Vùng kinh tế trọng điểm là bộ phận lãnh thổ quốc gia hội tụ điều kiện, yếu tố thuận lợi, tiềm lực kinh tế lớn, giữ vai trò động lực, đầu tàu thúc…","Từ khoá cần ghi nhớ: Vùng kinh tế trọng điểm;","Điểm nhấn ghi nhớ: Vùng kinh tế trọng điểm giữ vai trò động lực, đầu tàu thúc đẩy phát triển chung","Vùng kinh tế trọng điểm Bắc Bộ: Thành lập 1997 (Hà Nội, Hải Phòng, Quảng Ninh, Hưng Yên, Hải Dương), mở rộng 2004 thêm Vĩnh Phúc, Bắc Ninh (7 tỉnh, thành phố, hơn 15 nghìn km²,…","Vùng kinh tế trọng điểm miền Trung: Thành lập 1997 (Đà Nẵng, Thừa Thiên Huế, Quảng Nam, Quảng Ngãi), 2004 thêm Bình Định (5 tỉnh, thành phố, khoảng 28 nghìn km², 6,6 triệu người)."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: GRDP đứng đầu 4 vùng.","Hay nhầm: Chưa đúng với nội dung bài học: GRDP đứng đầu 4 vùng.","Hay nhầm: Chưa đúng với nội dung bài học: GRDP đứng đầu 4 vùng.","Hay nhầm: Chưa đúng với nội dung bài học: Thành lập năm 2009.","Hay nhầm: Chưa đúng với nội dung bài học: Thành lập năm 2009.","Hay nhầm: Chưa đúng với nội dung bài học: Thành lập năm 2009."],"q":{"n":15,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":5,"Nâng cao":1}}}]},{"t":"Phần 5. Phát triển kinh tế và đảm bảo quốc phòng an ninh ở Biển Đông và các đảo, quần đảo","l":[{"t":"Bài 33. Phát triển kinh tế và đảm bảo quốc phòng an ninh ở Biển Đông và các đảo, quần đảo","sum":["Biển Đông nằm ở phía tây Thái Bình Dương, trải dài từ khoảng vĩ độ 3°N đến 26°B và từ khoảng kinh độ 100°Đ đến 121°Đ; diện tích 3,44 triệu km², lớn thứ hai ở Thái Bình Dương và thứ ba thế giới; có…","Khái niệm: Biển Đông nằm ở phía tây Thái Bình Dương, trải dài từ khoảng vĩ độ 3°N đến 26°B và từ khoảng kinh độ 100°Đ đến 121°Đ; diện tích 3,44 triệu km², lớn…","Từ khoá cần ghi nhớ: Biển Đông;","Điểm nhấn ghi nhớ: Biển Đông lớn thứ hai ở Thái Bình Dương và thứ ba thế giới; có vịnh Bắc Bộ và vịnh Thái Lan","Biển Việt Nam rộng trên 1 triệu…: Biển Việt Nam rộng trên 1 triệu km² (gấp khoảng ba lần diện tích đất liền), gồm nội thủy, lãnh hải, vùng tiếp giáp lãnh hải, vùng đặc quyền kinh tế…","Tài nguyên: Sinh vật (khoảng 2 000 loài cá, trên 110 loài có giá trị kinh tế cao; trữ lượng hải sản khoảng 4 triệu tấn; rong biển, vườn quốc gia, khu dự trữ…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Lớn thứ ba thế giới.","Hay nhầm: Chưa đúng với nội dung bài học: Lớn thứ ba thế giới.","Hay nhầm: Chưa đúng với nội dung bài học: Lớn thứ ba thế giới.","Hay nhầm: Chưa đúng với nội dung bài học: Hai vịnh biển lớn.","Hay nhầm: Chưa đúng với nội dung bài học: Hai vịnh biển lớn.","Hay nhầm: Chưa đúng với nội dung bài học: Hai vịnh biển lớn."],"q":{"n":17,"lv":{"Biết":6,"Hiểu":5,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 34. Thực hành: Viết báo cáo tuyên truyền về bảo vệ chủ quyền biển, đảo của Việt Nam","sum":["Nội dung: thu thập tài liệu, tranh ảnh, video để viết báo cáo tuyên truyền về bảo vệ chủ quyền biển, đảo; chọn một trong hai nội dung: (1) chủ quyền của Việt Nam ở quần đảo Hoàng Sa và Trường Sa;","Nội dung: Thu thập tài liệu, tranh ảnh, video để viết báo cáo tuyên truyền về bảo vệ chủ quyền biển, đảo; chọn một trong hai nội dung:","Từ khoá cần ghi nhớ: Chủ quyền biển đảo;","Điểm nhấn ghi nhớ: Luật Biển Việt Nam số 18/2012/QH13 ngày 21/6/2012","Gợi ý thực hiện: Lựa chọn nội dung; sưu tầm, tổng hợp thông tin (nội dung bài 33, internet, sách, báo, tạp chí, video, Luật Biển Việt Nam); viết báo cáo với bố cục…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Ban hành ngày 21 tháng 6 năm 2012.","Hay nhầm: Chưa đúng với nội dung bài học: Ban hành ngày 21 tháng 6 năm 2012.","Hay nhầm: Chưa đúng với nội dung bài học: Ban hành ngày 21 tháng 6 năm 2012.","Hay nhầm: Chưa đúng với nội dung bài học: Hai nội dung gợi ý.","Hay nhầm: Chưa đúng với nội dung bài học: Hai nội dung gợi ý.","Hay nhầm: Chưa đúng với nội dung bài học: Hai nội dung gợi ý."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":2,"Nâng cao":1}}}]},{"t":"Phần 6. Địa lí địa phương","l":[{"t":"Bài 35. Thực hành: Tìm hiểu địa lí địa phương","sum":["Nội dung: tìm hiểu địa lí địa phương (tỉnh, thành phố trực thuộc Trung ương) theo các chủ đề và viết báo cáo giới thiệu.","Nội dung: Tìm hiểu địa lí địa phương (tỉnh, thành phố trực thuộc Trung ương) theo các chủ đề và viết báo cáo giới thiệu.","Từ khoá cần ghi nhớ: Địa lí địa phương; tự nhiên; dân cư; kinh tế; báo cáo giới thiệu;","Điểm nhấn ghi nhớ: Nguồn tư liệu: sách Địa lí 12, tài liệu Giáo dục địa phương, niên giám thống kê","Bốn chủ đề gợi ý: Vị trí địa lí, phạm vi lãnh thổ: diện tích, khu vực, tiếp giáp, phân chia hành chính, ý nghĩa"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Tìm hiểu địa phương mình.","Hay nhầm: Chưa đúng với nội dung bài học: Tìm hiểu địa phương mình.","Hay nhầm: Chưa đúng với nội dung bài học: Tìm hiểu địa phương mình.","Hay nhầm: Chưa đúng với nội dung bài học: Vị trí, tự nhiên, dân cư – xã hội, kinh tế.","Hay nhầm: Chưa đúng với nội dung bài học: Vị trí, tự nhiên, dân cư – xã hội, kinh tế.","Hay nhầm: Chưa đúng với nội dung bài học: Vị trí, tự nhiên, dân cư – xã hội, kinh tế."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3,"Nâng cao":1}}}]}]}]},{"id":"gdktpl","name":"Giáo dục kinh tế và pháp luật","b":[{"t":"Giáo dục kinh tế và pháp luật 12","c":[{"t":"Chủ đề 1. Tăng trưởng và phát triển kinh tế","l":[{"t":"Bài 1. Tăng trưởng và phát triển kinh tế","sum":["Tăng trưởng kinh tế là sự tăng lên về thu nhập hay tổng giá trị hàng hoá và dịch vụ mà nền kinh tế tạo ra trong một thời kì nhất định (so với thời kì gốc).","Khái niệm: Tăng trưởng kinh tế là sự tăng lên về thu nhập hay tổng giá trị hàng hoá và dịch vụ mà nền kinh tế tạo ra trong một thời kì nhất định (so với thời…","Từ khoá cần ghi nhớ: Tăng trưởng kinh tế; phát triển kinh tế;","Điểm nhấn ghi nhớ: GDP là giá trị bằng tiền của hàng hoá, dịch vụ cuối cùng sản xuất trên lãnh thổ một nước trong một năm","C là chi tiêu của hộ gia…: C là chi tiêu của hộ gia đình, I của doanh nghiệp, G của chính phủ, X là kim ngạch xuất khẩu, M là kim ngạch nhập khẩu.","Vai trò của tăng trưởng: Làm GDP/người tăng, tạo việc làm, tăng thu nhập, nâng cao đời sống; tạo điều kiện phát triển kết cấu hạ tầng, văn hoá, y tế, phúc lợi, quốc phòng –…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Tăng trưởng là sự thay đổi về lượng.","Hay nhầm: Chưa đúng với nội dung bài học: Tăng trưởng là sự thay đổi về lượng.","Hay nhầm: Chưa đúng với nội dung bài học: Tăng trưởng là sự thay đổi về lượng.","Hay nhầm: Chưa đúng với nội dung bài học: GDP tính theo lãnh thổ.","Hay nhầm: Chưa đúng với nội dung bài học: GDP tính theo lãnh thổ.","Hay nhầm: Chưa đúng với nội dung bài học: GDP tính theo lãnh thổ."],"q":{"n":21,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":7,"Nâng cao":2}}}]},{"t":"Chủ đề 2. Hội nhập kinh tế quốc tế","l":[{"t":"Bài 2. Hội nhập kinh tế quốc tế","sum":["Hội nhập kinh tế quốc tế là quá trình một quốc gia gắn kết nền kinh tế của mình với nền kinh tế các quốc gia khác trong khu vực và trên thế giới dựa trên sự chia sẻ lợi ích, đồng thời tuân thủ các…","Khái niệm: Hội nhập kinh tế quốc tế là quá trình một quốc gia gắn kết nền kinh tế của mình với nền kinh tế các quốc gia khác trong khu vực và trên thế giới dựa…","Từ khoá cần ghi nhớ: Hội nhập kinh tế quốc tế; toàn cầu hoá; chia sẻ lợi ích; chuẩn mực quốc tế; thị trường.","Điểm nhấn ghi nhớ: Hội nhập là tất yếu khách quan: mở rộng thị trường, thu hút vốn đầu tư, thúc đẩy tăng trưởng","Ba cấp độ hội nhập: Song phương (giữa hai quốc gia, nguyên tắc bình đẳng, cùng có lợi;","Năm mức độ tham gia từ thấp đến cao: Thoả thuận thương mại ưu đãi (mức thấp nhất, ưu đãi thuế quan và phi thuế quan), hiệp định thương mại tự do (xoá bỏ hầu hết hàng rào thuế quan nhưng…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Dựa trên chia sẻ lợi ích và chuẩn mực chung.","Hay nhầm: Chưa đúng với nội dung bài học: Dựa trên chia sẻ lợi ích và chuẩn mực chung.","Hay nhầm: Chưa đúng với nội dung bài học: Dựa trên chia sẻ lợi ích và chuẩn mực chung.","Hay nhầm: Chưa đúng với nội dung bài học: Theo phạm vi tham gia.","Hay nhầm: Chưa đúng với nội dung bài học: Theo phạm vi tham gia.","Hay nhầm: Chưa đúng với nội dung bài học: Theo phạm vi tham gia."],"q":{"n":20,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":7,"Nâng cao":1}}}]},{"t":"Chủ đề 3. Bảo hiểm và an sinh xã hội","l":[{"t":"Bài 3. Bảo hiểm","sum":["Bảo hiểm là hoạt động chuyển giao rủi ro giữa bên tham gia bảo hiểm và tổ chức bảo hiểm: bên tham gia nộp phí để lập quỹ dự trữ, khi gặp rủi ro hay sự kiện bảo hiểm thì được tổ chức bảo hiểm dùng…","Khái niệm: Bảo hiểm là hoạt động chuyển giao rủi ro giữa bên tham gia bảo hiểm và tổ chức bảo hiểm: bên tham gia nộp phí để lập quỹ dự trữ, khi gặp rủi ro hay…","Từ khoá cần ghi nhớ: Bảo hiểm; chuyển giao rủi ro; phí bảo hiểm; quỹ dự trữ; bảo hiểm xã hội; dịch vụ tài chính.","Điểm nhấn ghi nhớ: Người tham gia nộp phí để lập quỹ; khi gặp rủi ro, tổ chức bảo hiểm bồi thường từ quỹ này","Các loại hình bảo hiểm: Bảo hiểm xã hội (bù đắp một phần thu nhập khi ốm đau, thai sản, tai nạn lao động, bệnh nghề nghiệp, hết tuổi lao động; gồm bắt buộc và tự nguyện);…","Cơ sở có nguy hiểm về cháy…: Cơ sở có nguy hiểm về cháy, nổ phải mua bảo hiểm cháy, nổ bắt buộc (Nghị định 67/2023/NĐ-CP): đối tượng gồm nhà, công trình, máy móc, thiết bị, hàng…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Phí lập quỹ dự trữ để bồi thường.","Hay nhầm: Chưa đúng với nội dung bài học: Phí lập quỹ dự trữ để bồi thường.","Hay nhầm: Chưa đúng với nội dung bài học: Phí lập quỹ dự trữ để bồi thường.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Luật Bảo hiểm xã hội 2014.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Luật Bảo hiểm xã hội 2014.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Luật Bảo hiểm xã hội 2014."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":1}}},{"t":"Bài 4. An sinh xã hội","sum":["An sinh xã hội là hệ thống các chính sách, chương trình của Nhà nước và các lực lượng xã hội nhằm hạn chế, phòng ngừa và khắc phục rủi ro cho thành viên cộng đồng khi bị mất hoặc giảm thu nhập hay…","Khái niệm: An sinh xã hội là hệ thống các chính sách, chương trình của Nhà nước và các lực lượng xã hội nhằm hạn chế, phòng ngừa và khắc phục rủi ro cho thành…","Từ khoá cần ghi nhớ: An sinh xã hội; giảm nghèo; phòng ngừa và khắc phục rủi ro; công bằng xã hội; bốn chính sách cơ bản.","Điểm nhấn ghi nhớ: An sinh xã hội giúp thành viên cộng đồng vượt qua rủi ro khi mất hoặc giảm thu nhập","Bốn chính sách an sinh xã hội cơ bản ở Việt Nam: Hỗ trợ việc làm, thu nhập và giảm nghèo","Vai trò: Là tiêu chí đánh giá tiến bộ xã hội; là công cụ quản lí của Nhà nước để phân phối lại của cải, giảm chênh lệch giữa các vùng và bất bình đẳng; phòng…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Nhằm ổn định và công bằng xã hội.","Hay nhầm: Chưa đúng với nội dung bài học: Nhằm ổn định và công bằng xã hội.","Hay nhầm: Chưa đúng với nội dung bài học: Nhằm ổn định và công bằng xã hội.","Hay nhầm: Chưa đúng với nội dung bài học: Việc làm, bảo hiểm, trợ giúp xã hội, dịch vụ xã hội cơ bản.","Hay nhầm: Chưa đúng với nội dung bài học: Việc làm, bảo hiểm, trợ giúp xã hội, dịch vụ xã hội cơ bản.","Hay nhầm: Chưa đúng với nội dung bài học: Việc làm, bảo hiểm, trợ giúp xã hội, dịch vụ xã hội cơ bản."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}}]},{"t":"Chủ đề 4. Lập kế hoạch kinh doanh","l":[{"t":"Bài 5. Lập kế hoạch kinh doanh","sum":["Kế hoạch kinh doanh là bản trình bày ý tưởng kinh doanh và cách thức hiện thực hoá ý tưởng đó, gồm định hướng tương lai, mục tiêu và chiến lược phát triển trong một khoảng thời gian nhất định.","Khái niệm: Kế hoạch kinh doanh là bản trình bày ý tưởng kinh doanh và cách thức hiện thực hoá ý tưởng đó, gồm định hướng tương lai, mục tiêu và chiến lược phát…","Từ khoá cần ghi nhớ: Kế hoạch kinh doanh;","Điểm nhấn ghi nhớ: Kế hoạch kinh doanh gồm ý tưởng, mục tiêu và chiến lược hiện thực hoá ý tưởng","Nội dung cơ bản: Tóm tắt kế hoạch (tên kế hoạch, ý tưởng, mục tiêu, chiến lược, điều kiện thực hiện, cơ hội và rủi ro)","Năm bước lập kế hoạch: Bước 1 xác định ý tưởng kinh doanh (mới, sáng tạo, khả thi, có lợi nhuận; trả lời kinh doanh gì, cho ai, bằng cách nào)."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Gồm định hướng, mục tiêu, chiến lược.","Hay nhầm: Chưa đúng với nội dung bài học: Gồm định hướng, mục tiêu, chiến lược.","Hay nhầm: Chưa đúng với nội dung bài học: Gồm định hướng, mục tiêu, chiến lược.","Hay nhầm: Chưa đúng với nội dung bài học: Doanh số, thị phần, có lợi nhuận.","Hay nhầm: Chưa đúng với nội dung bài học: Doanh số, thị phần, có lợi nhuận.","Hay nhầm: Chưa đúng với nội dung bài học: Doanh số, thị phần, có lợi nhuận."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":1}}}]},{"t":"Chủ đề 5. Trách nhiệm xã hội của doanh nghiệp","l":[{"t":"Bài 6. Trách nhiệm xã hội của doanh nghiệp","sum":["Theo Ngân hàng Thế giới, trách nhiệm xã hội của doanh nghiệp là sự cam kết đóng góp cho phát triển bền vững thông qua những việc làm nâng cao chất lượng đời sống của người lao động và gia đình họ,…","Khái niệm: Theo Ngân hàng Thế giới, trách nhiệm xã hội của doanh nghiệp là sự cam kết đóng góp cho phát triển bền vững thông qua những việc làm nâng cao chất…","Từ khoá cần ghi nhớ: Trách nhiệm xã hội; bắt buộc và tự nguyện; phát triển bền vững; cộng đồng; người lao động.","Điểm nhấn ghi nhớ: Trách nhiệm xã hội là cam kết đóng góp cho phát triển bền vững, có lợi cho doanh nghiệp và xã hội","Bốn hình thức thực hiện: Trách nhiệm kinh tế (kinh doanh hiệu quả, việc làm, thu nhập, sản phẩm chất lượng, an toàn); trách nhiệm pháp lí (tuân thủ pháp luật về thuế, môi…","Công dân khi tham gia điều hành…: Công dân khi tham gia điều hành doanh nghiệp phải tuân thủ pháp luật, bảo đảm an toàn và quyền lợi chính đáng của người lao động, chất lượng sản…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Theo Ngân hàng Thế giới.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Ngân hàng Thế giới.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Ngân hàng Thế giới.","Hay nhầm: Chưa đúng với nội dung bài học: Kinh tế, pháp lí, đạo đức, nhân văn.","Hay nhầm: Chưa đúng với nội dung bài học: Kinh tế, pháp lí, đạo đức, nhân văn.","Hay nhầm: Chưa đúng với nội dung bài học: Kinh tế, pháp lí, đạo đức, nhân văn."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":1}}}]},{"t":"Chủ đề 6. Quản lí thu, chi trong gia đình","l":[{"t":"Bài 7. Quản lí thu, chi trong gia đình","sum":["Thu nhập gia đình là các khoản đến từ đóng góp của các thành viên (tiền lương, tiền công, lợi tức tiền gửi, lợi nhuận kinh doanh...).","Khái niệm: Thu nhập gia đình là các khoản đến từ đóng góp của các thành viên (tiền lương, tiền công, lợi tức tiền gửi, lợi nhuận kinh doanh...).","Từ khoá cần ghi nhớ: Thu nhập gia đình; chi tiêu gia đình; quản lí thu chi; nhu cầu của các thành viên; tiết kiệm.","Điểm nhấn ghi nhớ: Quản lí thu, chi là cân đối thu nhập và chi tiêu để đáp ứng nhu cầu của các thành viên","Mục tiêu tài chính theo thời gian: Ngắn hạn (6 tháng đến 1 năm: mua đồ dùng, kì nghỉ), trung hạn (2 – 5 năm: trả trước mua xe, kinh phí sinh con), dài hạn (từ 5 năm trở lên: du học,…","Chi thiết yếu là các khoản bắt…: Chi thiết yếu là các khoản bắt buộc hằng tháng (ăn, mặc, ở, đi lại, sinh hoạt, học hành); chi không thiết yếu là giao tế xã hội và mua sắm xa xỉ."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Nhằm cân đối tài chính.","Hay nhầm: Chưa đúng với nội dung bài học: Nhằm cân đối tài chính.","Hay nhầm: Chưa đúng với nội dung bài học: Nhằm cân đối tài chính.","Hay nhầm: Chưa đúng với nội dung bài học: Ví dụ mua tủ lạnh, kì nghỉ.","Hay nhầm: Chưa đúng với nội dung bài học: Ví dụ mua tủ lạnh, kì nghỉ.","Hay nhầm: Chưa đúng với nội dung bài học: Ví dụ mua tủ lạnh, kì nghỉ."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":1}}}]},{"t":"Chủ đề 7. Một số quyền và nghĩa vụ của công dân về kinh tế","l":[{"t":"Bài 8. Quyền và nghĩa vụ của công dân về kinh doanh và nộp thuế","sum":["Căn cứ pháp lí: Hiến pháp 2013, Luật Doanh nghiệp 2020, Luật Đầu tư 2020, Luật Quản lí thuế 2019.","Căn cứ pháp lí: Hiến pháp 2013, Luật Doanh nghiệp 2020, Luật Đầu tư 2020, Luật Quản lí thuế 2019.","Từ khoá cần ghi nhớ: Tự do kinh doanh; nộp thuế;","Điểm nhấn ghi nhớ: Điều 33 Hiến pháp 2013: tự do kinh doanh trong ngành nghề pháp luật không cấm;","Quyền về kinh doanh: Tự do kinh doanh ngành nghề pháp luật không cấm; tự chủ lựa chọn mô hình, loại hình tổ chức kinh tế, quy mô, địa bàn; bình đẳng trong kinh doanh…","Hành vi bị nghiêm cấm: Kinh doanh không đăng kí hoặc khi bị thu hồi giấy chứng nhận; kê khai không trung thực, khống vốn điều lệ; kinh doanh ngành nghề cấm (ma tuý, mại…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Quyền gắn với giới hạn của pháp luật.","Hay nhầm: Chưa đúng với nội dung bài học: Quyền gắn với giới hạn của pháp luật.","Hay nhầm: Chưa đúng với nội dung bài học: Quyền gắn với giới hạn của pháp luật.","Hay nhầm: Chưa đúng với nội dung bài học: Nộp thuế mang tính bắt buộc.","Hay nhầm: Chưa đúng với nội dung bài học: Nộp thuế mang tính bắt buộc.","Hay nhầm: Chưa đúng với nội dung bài học: Nộp thuế mang tính bắt buộc."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":6,"Nâng cao":1}}},{"t":"Bài 9. Quyền và nghĩa vụ của công dân về sở hữu tài sản và tôn trọng tài sản của người khác","sum":["Tài sản là vật, tiền, giấy tờ có giá và quyền tài sản. Điều 32 Hiến pháp 2013: mọi người có quyền sở hữu về thu nhập hợp pháp, của cải để dành, nhà ở, tư liệu sinh hoạt, tư liệu sản xuất, phần vốn…","Tài sản là vật, tiền, giấy tờ có giá và quyền tài sản: Điều 32 Hiến pháp 2013: mọi người có quyền sở hữu về thu nhập hợp pháp, của cải để dành, nhà ở, tư liệu sinh hoạt, tư liệu sản xuất, phần vốn góp…","Từ khoá cần ghi nhớ: Tài sản; quyền sở hữu; chiếm hữu; sử dụng;","Điểm nhấn ghi nhớ: Điều 32 Hiến pháp 2013: quyền sở hữu thu nhập hợp pháp, nhà ở, tư liệu sản xuất; sở hữu gồm ba quyền","Quyền chiếm hữu: Nắm giữ, quản lí, chi phối trực tiếp tài sản (không trái pháp luật, đạo đức xã hội).","Nghĩa vụ về sở hữu tài sản: Tuân thủ Hiến pháp và pháp luật; tôn trọng tài sản và quyền sở hữu của người khác; khai và nộp thuế phát sinh từ sở hữu tài sản."],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Theo Hiến pháp và Bộ luật Dân sự.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Hiến pháp và Bộ luật Dân sự.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Hiến pháp và Bộ luật Dân sự.","Hay nhầm: Chưa đúng với nội dung bài học: Có thể chuyển giao cho người khác.","Hay nhầm: Chưa đúng với nội dung bài học: Có thể chuyển giao cho người khác.","Hay nhầm: Chưa đúng với nội dung bài học: Có thể chuyển giao cho người khác."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":1}}}]},{"t":"Chủ đề 8. Quyền và nghĩa vụ của công dân về văn hoá, xã hội","l":[{"t":"Bài 10. Quyền và nghĩa vụ của công dân trong hôn nhân và gia đình","sum":["Điều 36 Hiến pháp 2013: nam, nữ có quyền kết hôn, li hôn; hôn nhân theo nguyên tắc tự nguyện, tiến bộ, một vợ một chồng, vợ chồng bình đẳng, tôn trọng lẫn nhau.","Điều 36 Hiến pháp 2013: Nam, nữ có quyền kết hôn, li hôn; hôn nhân theo nguyên tắc tự nguyện, tiến bộ, một vợ một chồng, vợ chồng bình đẳng, tôn trọng lẫn nhau.","Từ khoá cần ghi nhớ: Hôn nhân; kết hôn; li hôn; một vợ một chồng; vợ chồng bình đẳng;","Điểm nhấn ghi nhớ: Điều kiện kết hôn: nam từ đủ 20 tuổi, nữ từ đủ 18 tuổi","Điều kiện kết hôn: Nam từ đủ 20 tuổi, nữ từ đủ 18 tuổi; do hai bên tự nguyện quyết định, không ai ép buộc, lừa dối; không thuộc trường hợp bị cấm kết hôn; phải đăng kí…","Li hôn: Công dân có quyền yêu cầu Toà án giải quyết li hôn khi mục đích hôn nhân không đạt được; có thể thuận tình hoặc theo yêu cầu một bên; chồng không có…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Theo Luật Hôn nhân và Gia đình 2014.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Luật Hôn nhân và Gia đình 2014.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Luật Hôn nhân và Gia đình 2014.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Luật Hôn nhân và Gia đình 2014.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Luật Hôn nhân và Gia đình 2014.","Hay nhầm: Chưa đúng với nội dung bài học: Theo Luật Hôn nhân và Gia đình 2014."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":1}}},{"t":"Bài 11. Quyền và nghĩa vụ của công dân trong học tập","sum":["Học tập là quyền và nghĩa vụ của công dân. Căn cứ: Hiến pháp 2013, Luật Giáo dục 2019.","Học tập là quyền và nghĩa vụ của công dân: Căn cứ: Hiến pháp 2013, Luật Giáo dục 2019.","Từ khoá cần ghi nhớ: Quyền học tập; nghĩa vụ học tập; phổ cập giáo dục;","Điểm nhấn ghi nhớ: Khoản 3 Điều 14 Luật Giáo dục 2019: công dân trong độ tuổi có nghĩa vụ học tập để hoàn thành giáo dục bắt buộc","Quyền học tập: Bình đẳng về cơ hội học tập, không phân biệt dân tộc, tôn giáo, giới tính, nguồn gốc gia đình, địa vị xã hội, hoàn cảnh kinh tế;","Nghĩa vụ học tập (Điều 82 Luật Giáo dục 2019): Học tập, rèn luyện theo chương trình, kế hoạch và quy tắc ứng xử; tôn trọng nhà giáo, cán bộ, người lao động của cơ sở giáo dục, đoàn kết giúp đỡ…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Khoản 3 Điều 14.","Hay nhầm: Chưa đúng với nội dung bài học: Khoản 3 Điều 14.","Hay nhầm: Chưa đúng với nội dung bài học: Khoản 3 Điều 14.","Hay nhầm: Chưa đúng với nội dung bài học: Không phân biệt đối xử.","Hay nhầm: Chưa đúng với nội dung bài học: Không phân biệt đối xử.","Hay nhầm: Chưa đúng với nội dung bài học: Không phân biệt đối xử."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":6,"Nâng cao":1}}},{"t":"Bài 12. Quyền và nghĩa vụ của công dân trong bảo vệ, chăm sóc sức khoẻ và bảo đảm an sinh xã hội","sum":["Điều 38 Hiến pháp 2013: mọi người có quyền được bảo vệ, chăm sóc sức khoẻ, bình đẳng trong sử dụng dịch vụ y tế và có nghĩa vụ thực hiện các quy định về phòng bệnh, khám bệnh, chữa bệnh.","Điều 38 Hiến pháp 2013: Mọi người có quyền được bảo vệ, chăm sóc sức khoẻ, bình đẳng trong sử dụng dịch vụ y tế và có nghĩa vụ thực hiện các quy định về phòng bệnh, khám…","Từ khoá cần ghi nhớ: Chăm sóc sức khoẻ;","Điểm nhấn ghi nhớ: Điều 38 Hiến pháp 2013: quyền được bảo vệ, chăm sóc sức khoẻ và nghĩa vụ phòng bệnh, khám bệnh, chữa bệnh","Quyền bảo vệ, chăm sóc sức khoẻ: Được Nhà nước, cơ quan, tổ chức, cá nhân bảo vệ trước nguy cơ rủi ro về sức khoẻ; không bị phân biệt đối xử về cơ hội chăm sóc sức khoẻ và dịch vụ y…","Nghĩa vụ: Tuân thủ quy định pháp luật về phòng bệnh, chấp hành yêu cầu của cơ quan chức năng, nhất là phòng chống bệnh truyền nhiễm; tôn trọng người hành…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Kèm nghĩa vụ phòng bệnh, khám bệnh, chữa bệnh.","Hay nhầm: Chưa đúng với nội dung bài học: Kèm nghĩa vụ phòng bệnh, khám bệnh, chữa bệnh.","Hay nhầm: Chưa đúng với nội dung bài học: Kèm nghĩa vụ phòng bệnh, khám bệnh, chữa bệnh.","Hay nhầm: Chưa đúng với nội dung bài học: Điều 9, 10, 11.","Hay nhầm: Chưa đúng với nội dung bài học: Điều 9, 10, 11.","Hay nhầm: Chưa đúng với nội dung bài học: Điều 9, 10, 11."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":1}}},{"t":"Bài 13. Quyền và nghĩa vụ của công dân trong bảo vệ di sản văn hoá, môi trường và tài nguyên thiên nhiên","sum":["Điều 41 Hiến pháp 2013: mọi người có quyền hưởng thụ và tiếp cận các giá trị văn hoá, tham gia đời sống văn hoá, sử dụng các cơ sở văn hoá.","Điều 41 Hiến pháp 2013: Mọi người có quyền hưởng thụ và tiếp cận các giá trị văn hoá, tham gia đời sống văn hoá, sử dụng các cơ sở văn hoá.","Từ khoá cần ghi nhớ: Di sản văn hoá; môi trường trong lành;","Điểm nhấn ghi nhớ: Điều 43 Hiến pháp 2013: quyền sống trong môi trường trong lành và nghĩa vụ bảo vệ môi trường","Bảo vệ di sản văn hoá: Quyền: tiếp cận, hưởng thụ giá trị di sản (trực tiếp hoặc gián tiếp); tham quan, nghiên cứu, sưu tầm, lưu giữ, truyền bá tư liệu; phát biểu ý kiến,…","Bảo vệ môi trường và tài nguyên thiên nhiên: Quyền: sống trong môi trường trong lành; khai thác, sử dụng tài nguyên theo quy định (đi đôi với giữ gìn, tái tạo); tham gia hoạt động bảo vệ môi…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Quyền đi đôi với nghĩa vụ.","Hay nhầm: Chưa đúng với nội dung bài học: Quyền đi đôi với nghĩa vụ.","Hay nhầm: Chưa đúng với nội dung bài học: Quyền đi đôi với nghĩa vụ.","Hay nhầm: Chưa đúng với nội dung bài học: Sửa đổi, bổ sung năm 2009.","Hay nhầm: Chưa đúng với nội dung bài học: Sửa đổi, bổ sung năm 2009.","Hay nhầm: Chưa đúng với nội dung bài học: Sửa đổi, bổ sung năm 2009."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":1}}}]},{"t":"Chủ đề 9. Một số vấn đề cơ bản của luật quốc tế","l":[{"t":"Bài 14. Một số vấn đề chung về pháp luật quốc tế","sum":["Pháp luật quốc tế (luật quốc tế) là hệ thống các nguyên tắc và quy phạm pháp luật do các quốc gia và chủ thể khác của luật quốc tế thoả thuận xây dựng trên cơ sở bình đẳng và tự nguyện để điều chỉnh…","Khái niệm: Pháp luật quốc tế (luật quốc tế) là hệ thống các nguyên tắc và quy phạm pháp luật do các quốc gia và chủ thể khác của luật quốc tế thoả thuận xây…","Từ khoá cần ghi nhớ: Pháp luật quốc tế; chủ thể; quốc gia; tổ chức quốc tế liên chính phủ; bình đẳng; tự nguyện.","Điểm nhấn ghi nhớ: Pháp luật quốc tế do các quốc gia thoả thuận xây dựng trên cơ sở bình đẳng và tự nguyện","Vai trò: Điều chỉnh quan hệ giữa các chủ thể nhằm giữ gìn hoà bình, an ninh quốc tế, bảo đảm nhân quyền và phát triển chung; là cơ sở thiết lập quan hệ ngoại…","Bảy nguyên tắc cơ bản (Hiến chương Liên hợp quốc và Tuyên bố năm 1970): Cấm dùng vũ lực hoặc đe doạ dùng vũ lực"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Ngoài ra có tổ chức quốc tế và dân tộc đấu tranh giành độc lập.","Hay nhầm: Chưa đúng với nội dung bài học: Ngoài ra có tổ chức quốc tế và dân tộc đấu tranh giành độc lập.","Hay nhầm: Chưa đúng với nội dung bài học: Ngoài ra có tổ chức quốc tế và dân tộc đấu tranh giành độc lập.","Hay nhầm: Chưa đúng với nội dung bài học: Ghi nhận trong Hiến chương Liên hợp quốc.","Hay nhầm: Chưa đúng với nội dung bài học: Ghi nhận trong Hiến chương Liên hợp quốc.","Hay nhầm: Chưa đúng với nội dung bài học: Ghi nhận trong Hiến chương Liên hợp quốc."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":1}}},{"t":"Bài 15. Công pháp quốc tế về dân cư, lãnh thổ và chủ quyền quốc gia","sum":["Dân cư quốc gia là tổng hợp những người sinh sống, cư trú trên lãnh thổ quốc gia, chịu sự quản lí bằng pháp luật của Nhà nước đó; gồm ba bộ phận: công dân nước sở tại, người nước ngoài và người…","Khái niệm: Dân cư quốc gia là tổng hợp những người sinh sống, cư trú trên lãnh thổ quốc gia, chịu sự quản lí bằng pháp luật của Nhà nước đó; gồm ba bộ phận:…","Từ khoá cần ghi nhớ: Dân cư quốc gia; công dân; người nước ngoài; người không quốc tịch; quốc tịch; lãnh thổ; chủ quyền.","Điểm nhấn ghi nhớ: Dân cư quốc gia gồm công dân, người nước ngoài và người không quốc tịch; chỉ quốc gia mới cấp quốc tịch","Chế độ pháp lí của người nước ngoài gồm: Đãi ngộ quốc gia (hưởng quyền chính trị, dân sự, kinh tế, văn hoá như công dân nước sở tại, trừ một số quyền liên quan an ninh quốc gia), đãi ngộ…","Cư trú chính trị: Quốc gia cho phép người nước ngoài bị truy nã vì hoạt động, quan điểm chính trị, khoa học, tôn giáo được nhập cảnh, cư trú; là quyền riêng của mỗi…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Mỗi bộ phận có chế độ pháp lí riêng.","Hay nhầm: Chưa đúng với nội dung bài học: Mỗi bộ phận có chế độ pháp lí riêng.","Hay nhầm: Chưa đúng với nội dung bài học: Mỗi bộ phận có chế độ pháp lí riêng.","Hay nhầm: Chưa đúng với nội dung bài học: Quốc gia là chủ thể duy nhất của luật quốc tế có quyền này.","Hay nhầm: Chưa đúng với nội dung bài học: Quốc gia là chủ thể duy nhất của luật quốc tế có quyền này.","Hay nhầm: Chưa đúng với nội dung bài học: Quốc gia là chủ thể duy nhất của luật quốc tế có quyền này."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":6,"Nâng cao":1}}},{"t":"Bài 16. Nguyên tắc cơ bản của Tổ chức Thương mại thế giới và hợp đồng thương mại quốc tế","sum":["Tổ chức Thương mại Thế giới (WTO) thành lập ngày 01 – 01 – 1995, trụ sở tại Giơnevơ (Thuỵ Sĩ), có trên 160 nước thành viên; chức năng: quản lí việc thực hiện các hiệp định thương mại, tạo khuôn khổ…","Khái niệm: Tổ chức Thương mại Thế giới (WTO) thành lập ngày 01 – 01 – 1995, trụ sở tại Giơnevơ (Thuỵ Sĩ), có trên 160 nước thành viên; chức năng: quản lí việc…","Từ khoá cần ghi nhớ: WTO;","Điểm nhấn ghi nhớ: WTO thành lập ngày 1/1/1995, trụ sở tại Giơnevơ, có trên 160 nước thành viên","Năm nguyên tắc cơ bản của WTO: Thương mại không phân biệt đối xử, gồm đối xử tối huệ quốc (ưu đãi dành cho một thành viên phải dành ngay lập tức và không điều kiện cho tất cả…","Ba nguyên tắc cơ bản của hợp…: Ba nguyên tắc cơ bản của hợp đồng thương mại quốc tế (Bộ nguyên tắc hợp đồng thương mại quốc tế PICC 2004 của UNIDROIT, Luật Thương mại 2005, Bộ…"],"e":["Hay nhầm: Chưa đúng với nội dung bài học: Ngày 01 – 01 – 1995, trụ sở ở Giơnevơ.","Hay nhầm: Chưa đúng với nội dung bài học: Ngày 01 – 01 – 1995, trụ sở ở Giơnevơ.","Hay nhầm: Chưa đúng với nội dung bài học: Ngày 01 – 01 – 1995, trụ sở ở Giơnevơ.","Hay nhầm: Chưa đúng với nội dung bài học: Theo GATT.","Hay nhầm: Chưa đúng với nội dung bài học: Theo GATT.","Hay nhầm: Chưa đúng với nội dung bài học: Theo GATT."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":7,"Nâng cao":1}}}]}]}]}]};
